INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('e5e1cc91-9088-5801-a966-11e07f07b0d6', 'ab4f850a-1027-56b6-a32d-678f09861448', NULL, 36, 36, 'For these things happened, that the Scripture might be fulfilled, "A bone of him will not be broken."'),
  ('49a47bf8-d2c0-5d08-adfa-50eb835d9cd7', 'ab4f850a-1027-56b6-a32d-678f09861448', NULL, 37, 37, 'Again another Scripture says, "They will look on him whom they pierced."'),
  ('deee07a4-6928-587e-a9a8-988105e05a0d', 'ab4f850a-1027-56b6-a32d-678f09861448', NULL, 38, 38, 'After these things, Joseph of Arimathaea, being a disciple of Jesus, but secretly for fear of the Jews, asked of Pilate that he might take away Jesus'' body. Pilate gave him permission. He came therefore and took away his body.'),
  ('8f5be380-add1-5107-a0c3-4c8e0941289b', 'ab4f850a-1027-56b6-a32d-678f09861448', NULL, 39, 39, 'Nicodemus, who at first came to Jesus by night, also came bringing a mixture of myrrh and aloes, about a hundred Roman pounds.'),
  ('a1e15d49-0dd2-5292-a882-561e23ffdefe', 'ab4f850a-1027-56b6-a32d-678f09861448', NULL, 40, 40, 'So they took Jesus'' body, and bound it in linen cloths with the spices, as the custom of the Jews is to bury.'),
  ('c85f1d2a-7ac6-5355-aa8b-22c9162e4d4e', 'ab4f850a-1027-56b6-a32d-678f09861448', NULL, 41, 41, 'Now in the place where he was crucified there was a garden. In the garden was a new tomb in which no man had ever yet been laid.'),
  ('40f5feb9-aab8-583b-a67f-e1d396735385', 'ab4f850a-1027-56b6-a32d-678f09861448', NULL, 42, 42, 'Then because of the Jews'' Preparation Day (for the tomb was near at hand) they laid Jesus there.'),
  ('a1264bf3-88fe-5f1a-ae3c-c526792f4975', '891ac25d-f7c9-5f57-a4c4-97548a0abd19', NULL, 1, 1, 'Now on the first day of the week, Mary Magdalene went early, while it was still dark, to the tomb, and saw the stone taken away from the tomb.'),
  ('7e74f8af-b323-573f-a56c-fe6a77029f89', '891ac25d-f7c9-5f57-a4c4-97548a0abd19', NULL, 2, 2, 'Therefore she ran and came to Simon Peter, and to the other disciple whom Jesus loved, and said to them, "They have taken away the Lord out of the tomb, and we don''t know where they have laid him!"'),
  ('f8ebe85c-d130-5ba8-af38-554f7163ee6e', '891ac25d-f7c9-5f57-a4c4-97548a0abd19', NULL, 3, 3, 'Therefore Peter and the other disciple went out, and they went toward the tomb.'),
  ('fa5fe061-f12c-5d67-a218-9326877ead5b', '891ac25d-f7c9-5f57-a4c4-97548a0abd19', NULL, 4, 4, 'They both ran together. The other disciple outran Peter, and came to the tomb first.'),
  ('e4158a76-dbca-52c8-a63e-f1c6a8b3ba4d', '891ac25d-f7c9-5f57-a4c4-97548a0abd19', NULL, 5, 5, 'Stooping and looking in, he saw the linen cloths lying, yet he didn''t enter in.'),
  ('05ffdfc5-b589-5067-a086-2e639c574071', '891ac25d-f7c9-5f57-a4c4-97548a0abd19', NULL, 6, 6, 'Then Simon Peter came, following him, and entered into the tomb. He saw the linen cloths lying,'),
  ('165d0e76-300b-5648-aa03-acacc92be742', '891ac25d-f7c9-5f57-a4c4-97548a0abd19', NULL, 7, 7, 'and the cloth that had been on his head, not lying with the linen cloths, but rolled up in a place by itself.'),
  ('8f7dea86-d699-58f6-ac6e-3da2af251e88', '891ac25d-f7c9-5f57-a4c4-97548a0abd19', NULL, 8, 8, 'So then the other disciple who came first to the tomb also entered in, and he saw and believed.'),
  ('0735023c-fa91-5e9a-a660-bc71d0a3dd73', '891ac25d-f7c9-5f57-a4c4-97548a0abd19', NULL, 9, 9, 'For as yet they didn''t know the Scripture, that he must rise from the dead.'),
  ('2d823cdb-a766-5a14-a745-6d39cbd9f8e8', '891ac25d-f7c9-5f57-a4c4-97548a0abd19', NULL, 10, 10, 'So the disciples went away again to their own homes.'),
  ('8f41c34f-e839-5f70-afc0-aa1c1325af1a', '891ac25d-f7c9-5f57-a4c4-97548a0abd19', NULL, 11, 11, 'But Mary was standing outside at the tomb weeping. So, as she wept, she stooped and looked into the tomb,'),
  ('a16feae9-2af7-5570-af9d-36f0bfd4b558', '891ac25d-f7c9-5f57-a4c4-97548a0abd19', NULL, 12, 12, 'and she saw two angels in white sitting, one at the head, and one at the feet, where the body of Jesus had lain.'),
  ('96fb248d-30aa-5164-a419-6c93af3cd19c', '891ac25d-f7c9-5f57-a4c4-97548a0abd19', NULL, 13, 13, 'They told her, "Woman, why are you weeping?" She said to them, "Because they have taken away my Lord, and I don''t know where they have laid him."'),
  ('05fc64c6-4443-5ebc-ac8d-858399488f5e', '891ac25d-f7c9-5f57-a4c4-97548a0abd19', NULL, 14, 14, 'When she had said this, she turned around and saw Jesus standing, and didn''t know that it was Jesus.'),
  ('8a7ccc1b-8950-5c45-a237-b2a7762ed932', '891ac25d-f7c9-5f57-a4c4-97548a0abd19', NULL, 15, 15, 'Jesus said to her, "Woman, why are you weeping? Who are you looking for?" She, supposing him to be the gardener, said to him, "Sir, if you have carried him away, tell me where you have laid him, and I will take him away."'),
  ('e5083f27-9cc7-53dd-abe0-6edbf3c59a41', '891ac25d-f7c9-5f57-a4c4-97548a0abd19', NULL, 16, 16, 'Jesus said to her, "Mary." She turned and said to him, "Rabboni!" which is to say, "Teacher!"'),
  ('c7d1f337-856f-50d6-a0d1-4bdfecc54b96', '891ac25d-f7c9-5f57-a4c4-97548a0abd19', NULL, 17, 17, 'Jesus said to her, "Don''t hold me, for I haven''t yet ascended to my Father; but go to my brothers, and tell them, ''I am ascending to my Father and your Father, to my God and your God.''"'),
  ('4692da07-7dc0-58a0-aab0-bb21562bdf61', '891ac25d-f7c9-5f57-a4c4-97548a0abd19', NULL, 18, 18, 'Mary Magdalene came and told the disciples that she had seen the Lord, and that he had said these things to her.'),
  ('a1f8e5b8-14a7-502a-a0d7-70f94da6315c', '891ac25d-f7c9-5f57-a4c4-97548a0abd19', NULL, 19, 19, 'When therefore it was evening, on that day, the first day of the week, and when the doors were locked where the disciples were assembled, for fear of the Jews, Jesus came and stood in the midst, and said to them, "Peace be to you."'),
  ('9e3d306a-eabb-57c7-aeb8-2655c2a92e4d', '891ac25d-f7c9-5f57-a4c4-97548a0abd19', NULL, 20, 20, 'When he had said this, he showed them his hands and his side. The disciples therefore were glad when they saw the Lord.'),
  ('d9554767-d67e-5744-ad79-ba140fb91fc8', '891ac25d-f7c9-5f57-a4c4-97548a0abd19', NULL, 21, 21, 'Jesus therefore said to them again, "Peace be to you. As the Father has sent me, even so I send you."'),
  ('a77a21bb-0abd-59cf-a0b6-b3148a70880c', '891ac25d-f7c9-5f57-a4c4-97548a0abd19', NULL, 22, 22, 'When he had said this, he breathed on them, and said to them, "Receive the Holy Spirit!'),
  ('68dccc95-1568-5a08-abb1-c7237ebaf3ab', '891ac25d-f7c9-5f57-a4c4-97548a0abd19', NULL, 23, 23, 'Whoever''s sins you forgive, they are forgiven them. Whoever''s sins you retain, they have been retained."'),
  ('1f2eb460-118e-515c-a293-088e14d9a259', '891ac25d-f7c9-5f57-a4c4-97548a0abd19', NULL, 24, 24, 'But Thomas, one of the twelve, called Didymus, wasn''t with them when Jesus came.'),
  ('69d97d6f-cb09-5aaf-ab2e-f5ff45caea4b', '891ac25d-f7c9-5f57-a4c4-97548a0abd19', NULL, 25, 25, 'The other disciples therefore said to him, "We have seen the Lord!" But he said to them, "Unless I see in his hands the print of the nails, and put my hand into his side, I will not believe."'),
  ('4111a83f-fd3f-5c7f-ae4a-de9274e9ebba', '891ac25d-f7c9-5f57-a4c4-97548a0abd19', NULL, 26, 26, 'After eight days again his disciples were inside, and Thomas was with them. Jesus came, the doors being locked, and stood in the midst, and said, "Peace be to you."'),
  ('50962cd9-a9ab-544b-a991-342927709065', '891ac25d-f7c9-5f57-a4c4-97548a0abd19', NULL, 27, 27, 'Then he said to Thomas, "Reach here your finger, and see my hands. Reach here your hand, and put it into my side. Don''t be unbelieving, but believing."'),
  ('29020452-c0af-5a63-a91b-55c6de20ebba', '891ac25d-f7c9-5f57-a4c4-97548a0abd19', NULL, 28, 28, 'Thomas answered him, "My Lord and my God!"'),
  ('26dc1fd2-32e7-57f4-a89a-346025f5469f', '891ac25d-f7c9-5f57-a4c4-97548a0abd19', NULL, 29, 29, 'Jesus said to him, "Because you have seen me, you have believed. Blessed are those who have not seen, and have believed."'),
  ('6cec4537-97f2-582d-a2bb-46eee26fe50e', '891ac25d-f7c9-5f57-a4c4-97548a0abd19', NULL, 30, 30, 'Therefore Jesus did many other signs in the presence of his disciples, which are not written in this book;'),
  ('00976c43-1dad-5a0f-a4f6-0149d7733edf', '891ac25d-f7c9-5f57-a4c4-97548a0abd19', NULL, 31, 31, 'but these are written, that you may believe that Jesus is the Christ, the Son of God, and that believing you may have life in his name.'),
  ('bf8737b2-37dc-556e-abc5-522e51f7ba14', 'bf7a8335-35ba-5663-a4bf-be01c0c81884', NULL, 1, 1, 'After these things, Jesus revealed himself again to the disciples at the sea of Tiberias. He revealed himself this way.'),
  ('e31b0076-9455-5540-a214-0742fcbbea64', 'bf7a8335-35ba-5663-a4bf-be01c0c81884', NULL, 2, 2, 'Simon Peter, Thomas called Didymus, Nathanael of Cana in Galilee, and the sons of Zebedee, and two others of his disciples were together.'),
  ('df089caf-b6dc-5c75-acd3-0dbe2e8b9e0f', 'bf7a8335-35ba-5663-a4bf-be01c0c81884', NULL, 3, 3, 'Simon Peter said to them, "I''m going fishing." They told him, "We are also coming with you." They immediately went out, and entered into the boat. That night, they caught nothing.'),
  ('b9cd3ecf-0436-513f-a122-e2d0e150502c', 'bf7a8335-35ba-5663-a4bf-be01c0c81884', NULL, 4, 4, 'But when day had already come, Jesus stood on the beach, yet the disciples didn''t know that it was Jesus.'),
  ('8db0d0d8-9f89-521e-acaf-6832e4fdb904', 'bf7a8335-35ba-5663-a4bf-be01c0c81884', NULL, 5, 5, 'Jesus therefore said to them, "Children, have you anything to eat?" They answered him, "No."'),
  ('30a2ce58-505a-5bed-aba4-b8812aac8b83', 'bf7a8335-35ba-5663-a4bf-be01c0c81884', NULL, 6, 6, 'He said to them, "Cast the net on the right side of the boat, and you will find some." They cast it therefore, and now they weren''t able to draw it in for the multitude of fish.'),
  ('3a0f6bb4-d267-55d0-a36e-6f0f6e7e01f5', 'bf7a8335-35ba-5663-a4bf-be01c0c81884', NULL, 7, 7, 'That disciple therefore whom Jesus loved said to Peter, "It''s the Lord!" So when Simon Peter heard that it was the Lord, he wrapped his coat around him (for he was naked), and threw himself into the sea.'),
  ('08de7e42-30ee-53bf-a1b8-bce82fe85b0d', 'bf7a8335-35ba-5663-a4bf-be01c0c81884', NULL, 8, 8, 'But the other disciples came in the little boat (for they were not far from the land, but about two hundred cubits away), dragging the net full of fish.'),
  ('29e75dd3-a101-5718-a2bb-91b091c9876b', 'bf7a8335-35ba-5663-a4bf-be01c0c81884', NULL, 9, 9, 'So when they got out on the land, they saw a fire of coals there, and fish laid on it, and bread.'),
  ('d937a40f-b13e-5851-ad88-c905b5212268', 'bf7a8335-35ba-5663-a4bf-be01c0c81884', NULL, 10, 10, 'Jesus said to them, "Bring some of the fish which you have just caught."'),
  ('85753454-2d11-502e-a672-0d0eefec6eb2', 'bf7a8335-35ba-5663-a4bf-be01c0c81884', NULL, 11, 11, 'Simon Peter went up, and drew the net to land, full of great fish, one hundred fifty-three; and even though there were so many, the net wasn''t torn.'),
  ('88aa6316-3f70-59f6-a3fc-8b42cc9dd981', 'bf7a8335-35ba-5663-a4bf-be01c0c81884', NULL, 12, 12, 'Jesus said to them, "Come and eat breakfast." None of the disciples dared inquire of him, "Who are you?" knowing that it was the Lord.'),
  ('f9294f05-180e-56d3-afb7-c82606f04d87', 'bf7a8335-35ba-5663-a4bf-be01c0c81884', NULL, 13, 13, 'Then Jesus came and took the bread, gave it to them, and the fish likewise.'),
  ('a82668bc-c4ed-5d77-a437-75f9f6121a75', 'bf7a8335-35ba-5663-a4bf-be01c0c81884', NULL, 14, 14, 'This is now the third time that Jesus was revealed to his disciples, after he had risen from the dead.'),
  ('bc6a66b9-0b13-5b71-a579-ad10c31ef17b', 'bf7a8335-35ba-5663-a4bf-be01c0c81884', NULL, 15, 15, 'So when they had eaten their breakfast, Jesus said to Simon Peter, "Simon, son of Jonah, do you love me more than these?" He said to him, "Yes, Lord; you know that I have affection for you." He said to him, "Feed my lambs."'),
  ('aa5cd4c0-0ea3-5adc-a3ed-a6f41cf1f0bc', 'bf7a8335-35ba-5663-a4bf-be01c0c81884', NULL, 16, 16, 'He said to him again a second time, "Simon, son of Jonah, do you love me?" He said to him, "Yes, Lord; you know that I have affection for you." He said to him, "Tend my sheep."'),
  ('af28379e-e9e0-5168-a0b9-5d657171ea48', 'bf7a8335-35ba-5663-a4bf-be01c0c81884', NULL, 17, 17, 'He said to him the third time, "Simon, son of Jonah, do you have affection for me?" Peter was grieved because he asked him the third time, "Do you have affection for me?" He said to him, "Lord, you know everything. You know that I have affection for you." Jesus said to him, "Feed my sheep.'),
  ('648483bd-2ed8-54b2-aa5e-b6a7c3fa29fd', 'bf7a8335-35ba-5663-a4bf-be01c0c81884', NULL, 18, 18, 'Most certainly I tell you, when you were young, you dressed yourself, and walked where you wanted to. But when you are old, you will stretch out your hands, and another will dress you, and carry you where you don''t want to go."'),
  ('de08bdb1-050f-58eb-af4e-81bb32c52f72', 'bf7a8335-35ba-5663-a4bf-be01c0c81884', NULL, 19, 19, 'Now he said this, signifying by what kind of death he would glorify God. When he had said this, he said to him, "Follow me."'),
  ('285e7969-65a5-5045-ad8c-c16cd2abba70', 'bf7a8335-35ba-5663-a4bf-be01c0c81884', NULL, 20, 20, 'Then Peter, turning around, saw a disciple following. This was the disciple whom Jesus sincerely loved, the one who had also leaned on Jesus'' breast at the supper and asked, "Lord, who is going to betray You?"'),
  ('40f68279-de91-592c-aa0a-dc8494816bf5', 'bf7a8335-35ba-5663-a4bf-be01c0c81884', NULL, 21, 21, 'Peter seeing him, said to Jesus, "Lord, what about this man?"'),
  ('0b90042b-30b9-54aa-a34b-49328eb2255f', 'bf7a8335-35ba-5663-a4bf-be01c0c81884', NULL, 22, 22, 'Jesus said to him, "If I desire that he stay until I come, what is that to you? You follow me."'),
  ('2e05725a-7a57-5df9-ae5f-fa20f5dcc741', 'bf7a8335-35ba-5663-a4bf-be01c0c81884', NULL, 23, 23, 'This saying therefore went out among the brothers, that this disciple wouldn''t die. Yet Jesus didn''t say to him that he wouldn''t die, but, "If I desire that he stay until I come, what is that to you?"'),
  ('ef0b1e04-5874-5bdf-a91d-4d63cf163043', 'bf7a8335-35ba-5663-a4bf-be01c0c81884', NULL, 24, 24, 'This is the disciple who testifies about these things, and wrote these things. We know that his witness is true.'),
  ('577b1682-f681-5fe4-a7b6-0cc57bbedcfa', 'bf7a8335-35ba-5663-a4bf-be01c0c81884', NULL, 25, 25, 'There are also many other things which Jesus did, which if they would all be written, I suppose that even the world itself wouldn''t have room for the books that would be written.'),
  ('986ac0cd-f1fa-517a-a897-4277f619dd4c', 'e7903654-679c-59d7-a6de-2e7909b80a50', NULL, 1, 1, 'The first book I wrote, Theophilus, concerned all that Jesus began both to do and to teach,'),
  ('307dd971-253f-591f-aba6-48a1183cd603', 'e7903654-679c-59d7-a6de-2e7909b80a50', NULL, 2, 2, 'until the day in which he was received up, after he had given commandment through the Holy Spirit to the apostles whom he had chosen.'),
  ('e6136e0f-c781-5fe9-a826-5b6c489c4386', 'e7903654-679c-59d7-a6de-2e7909b80a50', NULL, 3, 3, 'To these he also showed himself alive after he suffered, by many proofs, appearing to them over a period of forty days, and speaking about God''s Kingdom.'),
  ('c6cd7b2c-02af-5ebe-ab03-6a456f7a17e1', 'e7903654-679c-59d7-a6de-2e7909b80a50', NULL, 4, 4, 'Being assembled together with them, he commanded them, "Don''t depart from Jerusalem, but wait for the promise of the Father, which you heard from me.'),
  ('302407fa-db72-5caf-aa30-de142a1a346d', 'e7903654-679c-59d7-a6de-2e7909b80a50', NULL, 5, 5, 'For John indeed baptized in water, but you will be baptized in the Holy Spirit not many days from now."'),
  ('5a1b0684-cd10-50e7-a25f-9eb469ca4211', 'e7903654-679c-59d7-a6de-2e7909b80a50', NULL, 6, 6, 'Therefore, when they had come together, they asked him, "Lord, are you now restoring the kingdom to Israel?"'),
  ('aca05438-9ff9-5a9b-acb9-6c6f198ff30a', 'e7903654-679c-59d7-a6de-2e7909b80a50', NULL, 7, 7, 'He said to them, "It isn''t for you to know times or seasons which the Father has set within his own authority.'),
  ('91d9886a-94c9-5637-a1f2-82b99e285093', 'e7903654-679c-59d7-a6de-2e7909b80a50', NULL, 8, 8, 'But you will receive power when the Holy Spirit has come upon you. You will be witnesses to me in Jerusalem, in all Judea and Samaria, and to the uttermost parts of the earth."'),
  ('f3ecebfb-b7f3-5a47-a591-fd08896cea9c', 'e7903654-679c-59d7-a6de-2e7909b80a50', NULL, 9, 9, 'When he had said these things, as they were looking, he was taken up, and a cloud received him out of their sight.'),
  ('b82fae60-ffcd-545f-a50a-ad4e48712397', 'e7903654-679c-59d7-a6de-2e7909b80a50', NULL, 10, 10, 'While they were looking steadfastly into the sky as he went, behold, two men stood by them in white clothing,'),
  ('334ce9ac-3d71-569a-a7b2-e31930067c26', 'e7903654-679c-59d7-a6de-2e7909b80a50', NULL, 11, 11, 'who also said, "You men of Galilee, why do you stand looking into the sky? This Jesus, who was received up from you into the sky will come back in the same way as you saw him going into the sky."'),
  ('6239875f-f55a-50c1-a2ff-235db5d91fd1', 'e7903654-679c-59d7-a6de-2e7909b80a50', NULL, 12, 12, 'Then they returned to Jerusalem from the mountain called Olivet, which is near Jerusalem, a Sabbath day''s journey away.'),
  ('896c4dfe-ec34-57e8-a5ae-8324700cdde7', 'e7903654-679c-59d7-a6de-2e7909b80a50', NULL, 13, 13, 'When they had come in, they went up into the upper room, where they were staying; that is Peter, John, James, Andrew, Philip, Thomas, Bartholomew, Matthew, James the son of Alphaeus, Simon the Zealot, and Judas the son of James.'),
  ('9dd12877-4fdd-56dd-a263-5812a88d49aa', 'e7903654-679c-59d7-a6de-2e7909b80a50', NULL, 14, 14, 'All these with one accord continued steadfastly in prayer and supplication, along with the women, and Mary the mother of Jesus, and with his brothers.'),
  ('90732a14-9e6f-5bbe-a952-1a308baee5b6', 'e7903654-679c-59d7-a6de-2e7909b80a50', NULL, 15, 15, 'In these days, Peter stood up in the midst of the disciples (and the number of names was about one hundred twenty), and said,'),
  ('1499834f-0907-50d9-ac72-938d5cea46da', 'e7903654-679c-59d7-a6de-2e7909b80a50', NULL, 16, 16, '"Brothers, it was necessary that this Scripture should be fulfilled, which the Holy Spirit spoke before by the mouth of David concerning Judas, who was guide to those who took Jesus.'),
  ('3d445a1c-335f-5d14-a21d-69f72385f2c5', 'e7903654-679c-59d7-a6de-2e7909b80a50', NULL, 17, 17, 'For he was numbered with us, and received his portion in this ministry.'),
  ('a8eb2360-c6cc-591e-aeb4-91f6b31ad4d4', 'e7903654-679c-59d7-a6de-2e7909b80a50', NULL, 18, 18, 'Now this man obtained a field with the reward for his wickedness, and falling headlong, his body burst open, and all his intestines gushed out.'),
  ('a54dc88c-cd4e-5c6e-a494-49e5860c2871', 'e7903654-679c-59d7-a6de-2e7909b80a50', NULL, 19, 19, 'It became known to everyone who lived in Jerusalem that in their language that field was called ''Akeldama,'' that is, ''The field of blood.'''),
  ('6b7f5db5-ada8-5f19-a7fa-ae0fc25ff893', 'e7903654-679c-59d7-a6de-2e7909b80a50', NULL, 20, 20, 'For it is written in the book of Psalms, ''Let his habitation be made desolate. Let no one dwell therein;'' and, ''Let another take his office.'''),
  ('044c1e4f-3c24-58a0-a62b-798b635553f9', 'e7903654-679c-59d7-a6de-2e7909b80a50', NULL, 21, 21, '"Of the men therefore who have accompanied us all the time that the Lord Jesus went in and out among us,'),
  ('9f475959-9cf4-520f-ac07-99f51a9117c3', 'e7903654-679c-59d7-a6de-2e7909b80a50', NULL, 22, 22, 'beginning from the baptism of John, to the day that he was received up from us, of these one must become a witness with us of his resurrection."'),
  ('3a0ae7e0-fb5d-5d38-ac57-455946a668de', 'e7903654-679c-59d7-a6de-2e7909b80a50', NULL, 23, 23, 'They put forward two, Joseph called Barsabbas, who was surnamed Justus, and Matthias.'),
  ('6f2414b5-b68c-51f1-a9d0-c80d5baa425b', 'e7903654-679c-59d7-a6de-2e7909b80a50', NULL, 24, 24, 'They prayed, and said, "You, Lord, who know the hearts of all men, show which one of these two you have chosen'),
  ('f3df98bb-edd7-5a04-a2ec-9f38586a4888', 'e7903654-679c-59d7-a6de-2e7909b80a50', NULL, 25, 25, 'to take part in this ministry and apostleship from which Judas fell away, that he might go to his own place."'),
  ('0b855346-d446-5bc2-a393-697c5ee0a8f0', 'e7903654-679c-59d7-a6de-2e7909b80a50', NULL, 26, 26, 'They drew lots for them, and the lot fell on Matthias, and he was numbered with the eleven apostles.'),
  ('10688ffa-37ca-58ae-a19f-310fd99e6498', '59e2d2a7-70a4-51eb-a04b-483c4293b5ec', NULL, 1, 1, 'Now when the day of Pentecost had come, they were all with one accord in one place.'),
  ('ccc3695d-be54-5fae-a7a0-9809dbef1acb', '59e2d2a7-70a4-51eb-a04b-483c4293b5ec', NULL, 2, 2, 'Suddenly there came from the sky a sound like the rushing of a mighty wind, and it filled all the house where they were sitting.'),
  ('1b4d4c7d-f69a-5713-af5a-36fd5ff6f462', '59e2d2a7-70a4-51eb-a04b-483c4293b5ec', NULL, 3, 3, 'Tongues like fire appeared and were distributed to them, and one sat on each of them.'),
  ('8feb6d62-66ea-597c-a4b6-9cc64dbcfd69', '59e2d2a7-70a4-51eb-a04b-483c4293b5ec', NULL, 4, 4, 'They were all filled with the Holy Spirit, and began to speak with other languages, as the Spirit gave them the ability to speak.'),
  ('d6d6dc08-7b4d-5875-a641-191a8a64a688', '59e2d2a7-70a4-51eb-a04b-483c4293b5ec', NULL, 5, 5, 'Now there were dwelling in Jerusalem Jews, devout men, from every nation under the sky.'),
  ('1e3596b5-7e0e-5637-a99d-4bef7eb3465d', '59e2d2a7-70a4-51eb-a04b-483c4293b5ec', NULL, 6, 6, 'When this sound was heard, the multitude came together, and were bewildered, because everyone heard them speaking in his own language.'),
  ('b642523b-f051-5aca-a5e7-92e0ae74254e', '59e2d2a7-70a4-51eb-a04b-483c4293b5ec', NULL, 7, 7, 'They were all amazed and marveled, saying to one another, "Behold, aren''t all these who speak Galileans?'),
  ('9678e1f7-9738-5d18-a44e-bc309fbac9b8', '59e2d2a7-70a4-51eb-a04b-483c4293b5ec', NULL, 8, 8, 'How do we hear, everyone in our own native language?'),
  ('a46095ee-e550-5c17-ae9b-396762e9a043', '59e2d2a7-70a4-51eb-a04b-483c4293b5ec', NULL, 9, 9, 'Parthians, Medes, Elamites, and people from Mesopotamia, Judea, Cappadocia, Pontus, Asia,'),
  ('eaad518d-0509-5048-a663-69309f5c6657', '59e2d2a7-70a4-51eb-a04b-483c4293b5ec', NULL, 10, 10, 'Phrygia, Pamphylia, Egypt, the parts of Libya around Cyrene, visitors from Rome, both Jews and proselytes,'),
  ('fac07c16-9c91-5e63-a110-ce669025b641', '59e2d2a7-70a4-51eb-a04b-483c4293b5ec', NULL, 11, 11, 'Cretans and Arabians: we hear them speaking in our languages the mighty works of God!"'),
  ('8f011b9a-5675-5a04-aebd-677c849cd18b', '59e2d2a7-70a4-51eb-a04b-483c4293b5ec', NULL, 12, 12, 'They were all amazed, and were perplexed, saying one to another, "What does this mean?"'),
  ('06cd23a6-9bca-52a5-a547-7bbd06f2af17', '59e2d2a7-70a4-51eb-a04b-483c4293b5ec', NULL, 13, 13, 'Others, mocking, said, "They are filled with new wine."'),
  ('7ac41947-fdc9-5f58-a9d1-30e79fc2ac56', '59e2d2a7-70a4-51eb-a04b-483c4293b5ec', NULL, 14, 14, 'But Peter, standing up with the eleven, lifted up his voice, and spoke out to them, "You men of Judea, and all you who dwell at Jerusalem, let this be known to you, and listen to my words.'),
  ('c071fc3a-d2d6-5309-aeeb-388a3fa80dbe', '59e2d2a7-70a4-51eb-a04b-483c4293b5ec', NULL, 15, 15, 'For these aren''t drunken, as you suppose, seeing it is only the third hour of the day.'),
  ('aa81c399-30c6-5840-aa59-8f100aeebf56', '59e2d2a7-70a4-51eb-a04b-483c4293b5ec', NULL, 16, 16, 'But this is what has been spoken through the prophet Joel:'),
  ('fc93210c-6ad8-57db-a557-3472af29d5cb', '59e2d2a7-70a4-51eb-a04b-483c4293b5ec', NULL, 17, 17, '''It will be in the last days, says God, that I will pour out my Spirit on all flesh. Your sons and your daughters will prophesy. Your young men will see visions. Your old men will dream dreams.'),
  ('a2c88c44-a6d5-52b3-ab6c-97058f58f70c', '59e2d2a7-70a4-51eb-a04b-483c4293b5ec', NULL, 18, 18, 'Yes, and on my servants and on my handmaidens in those days, I will pour out my Spirit, and they will prophesy.'),
  ('0eaf94d2-531d-5900-a087-add6ba5509b1', '59e2d2a7-70a4-51eb-a04b-483c4293b5ec', NULL, 19, 19, 'I will show wonders in the sky above, and signs on the earth beneath; blood, and fire, and billows of smoke.'),
  ('d057363d-d67c-5799-a8a9-8f0256e59371', '59e2d2a7-70a4-51eb-a04b-483c4293b5ec', NULL, 20, 20, 'The sun will be turned into darkness, and the moon into blood, before the great and glorious day of the Lord comes.'),
  ('1e9e9882-255e-509a-a390-76a3821a532c', '59e2d2a7-70a4-51eb-a04b-483c4293b5ec', NULL, 21, 21, 'It will be, that whoever will call on the name of the Lord will be saved.'''),
  ('a8b1b2d7-bdcc-52c1-a521-7b2a675d8e59', '59e2d2a7-70a4-51eb-a04b-483c4293b5ec', NULL, 22, 22, '"Men of Israel, hear these words! Jesus of Nazareth, a man approved by God to you by mighty works and wonders and signs which God did by him in the midst of you, even as you yourselves know,'),
  ('ee2592d2-1432-5e9a-a402-3f902531d481', '59e2d2a7-70a4-51eb-a04b-483c4293b5ec', NULL, 23, 23, 'him, being delivered up by the determined counsel and foreknowledge of God, you have taken by the hand of lawless men, crucified and killed;'),
  ('6ce64e80-df78-5df8-a1d4-ef9a08239c59', '59e2d2a7-70a4-51eb-a04b-483c4293b5ec', NULL, 24, 24, 'whom God raised up, having freed him from the agony of death, because it was not possible that he should be held by it.'),
  ('180d5a4d-1dac-5f02-abf2-204b428ac70b', '59e2d2a7-70a4-51eb-a04b-483c4293b5ec', NULL, 25, 25, 'For David says concerning him, ''I saw the Lord always before my face, For he is on my right hand, that I should not be moved.'),
  ('8db3b288-7097-5269-afb3-df40e7b9f9b2', '59e2d2a7-70a4-51eb-a04b-483c4293b5ec', NULL, 26, 26, 'Therefore my heart was glad, and my tongue rejoiced. Moreover my flesh also will dwell in hope;'),
  ('e71c2f37-40c9-509b-a8b1-b23d3067ffbb', '59e2d2a7-70a4-51eb-a04b-483c4293b5ec', NULL, 27, 27, 'because you will not leave my soul in Hades, neither will you allow your Holy One to see decay.'),
  ('a7793c34-624d-5e37-ae38-ef17d5d48c68', '59e2d2a7-70a4-51eb-a04b-483c4293b5ec', NULL, 28, 28, 'You made known to me the ways of life. You will make me full of gladness with your presence.'''),
  ('197886b0-0ccc-5b4d-ace9-ab5bbe97e6d6', '59e2d2a7-70a4-51eb-a04b-483c4293b5ec', NULL, 29, 29, '"Brothers, I may tell you freely of the patriarch David, that he both died and was buried, and his tomb is with us to this day.'),
  ('ffcdc284-5583-5363-a12b-4160d7d1b679', '59e2d2a7-70a4-51eb-a04b-483c4293b5ec', NULL, 30, 30, 'Therefore, being a prophet, and knowing that God had sworn with an oath to him that of the fruit of his body, according to the flesh, he would raise up the Christ to sit on his throne,'),
  ('c987afc5-36f5-582a-ad29-7d1c429543e7', '59e2d2a7-70a4-51eb-a04b-483c4293b5ec', NULL, 31, 31, 'he foreseeing this spoke about the resurrection of the Christ, that neither was his soul left in Hades, nor did his flesh see decay.'),
  ('0cab463b-35ab-5302-ae9e-5daf65c868c3', '59e2d2a7-70a4-51eb-a04b-483c4293b5ec', NULL, 32, 32, 'This Jesus God raised up, to which we all are witnesses.'),
  ('a9dc51bf-5339-5ab3-ad72-55b4f4d2c774', '59e2d2a7-70a4-51eb-a04b-483c4293b5ec', NULL, 33, 33, 'Being therefore exalted by the right hand of God, and having received from the Father the promise of the Holy Spirit, he has poured out this, which you now see and hear.'),
  ('f038d51b-753e-589d-ab62-a550231afc37', '59e2d2a7-70a4-51eb-a04b-483c4293b5ec', NULL, 34, 34, 'For David didn''t ascend into the heavens, but he says himself, ''The Lord said to my Lord, "Sit by my right hand,'),
  ('fbbd9d92-701f-5e0e-ae00-810f7da0ffca', '59e2d2a7-70a4-51eb-a04b-483c4293b5ec', NULL, 35, 35, 'until I make your enemies a footstool for your feet."'''),
  ('c8155a1b-8600-5d34-ae02-4306cb49d595', '59e2d2a7-70a4-51eb-a04b-483c4293b5ec', NULL, 36, 36, '"Let all the house of Israel therefore know certainly that God has made him both Lord and Christ, this Jesus whom you crucified."'),
  ('400855a4-a15a-5599-aa95-9c59abfcd99a', '59e2d2a7-70a4-51eb-a04b-483c4293b5ec', NULL, 37, 37, 'Now when they heard this, they were cut to the heart, and said to Peter and the rest of the apostles, "Brothers, what shall we do?"'),
  ('90036453-7130-573f-afa8-260c6a494637', '59e2d2a7-70a4-51eb-a04b-483c4293b5ec', NULL, 38, 38, 'Peter said to them, "Repent, and be baptized, every one of you, in the name of Jesus Christ for the forgiveness of sins, and you will receive the gift of the Holy Spirit.'),
  ('85b2cb4f-0074-5713-a2a5-76ce6b6d35e3', '59e2d2a7-70a4-51eb-a04b-483c4293b5ec', NULL, 39, 39, 'For the promise is to you, and to your children, and to all who are far off, even as many as the Lord our God will call to himself."'),
  ('97d29e52-d2b6-512c-a0ce-e449b9da47ab', '59e2d2a7-70a4-51eb-a04b-483c4293b5ec', NULL, 40, 40, 'With many other words he testified, and exhorted them, saying, "Save yourselves from this crooked generation!"'),
  ('c72f13b0-3612-5d97-a6a3-5ab210843629', '59e2d2a7-70a4-51eb-a04b-483c4293b5ec', NULL, 41, 41, 'Then those who gladly received his word were baptized. There were added that day about three thousand souls.'),
  ('970dc34f-0f27-5aaf-a927-f232f82f338c', '59e2d2a7-70a4-51eb-a04b-483c4293b5ec', NULL, 42, 42, 'They continued steadfastly in the apostles'' teaching and fellowship, in the breaking of bread, and prayer.'),
  ('056ceffa-c740-55b8-a950-92a2708a9bbe', '59e2d2a7-70a4-51eb-a04b-483c4293b5ec', NULL, 43, 43, 'Fear came on every soul, and many wonders and signs were done through the apostles.'),
  ('f86c6bd2-233a-539f-ae53-ce4b9837d0c0', '59e2d2a7-70a4-51eb-a04b-483c4293b5ec', NULL, 44, 44, 'All who believed were together, and had all things in common.'),
  ('bd424b9a-03f4-564a-ae35-16a159ce8aac', '59e2d2a7-70a4-51eb-a04b-483c4293b5ec', NULL, 45, 45, 'They sold their possessions and goods, and distributed them to all, according as anyone had need.'),
  ('a73eacc5-c2be-5ba5-a68f-9cc941ae0e5b', '59e2d2a7-70a4-51eb-a04b-483c4293b5ec', NULL, 46, 46, 'Day by day, continuing steadfastly with one accord in the temple, and breaking bread at home, they took their food with gladness and singleness of heart,'),
  ('f8e85675-cd71-59eb-a17b-431dd9b97f2d', '59e2d2a7-70a4-51eb-a04b-483c4293b5ec', NULL, 47, 47, 'praising God, and having favor with all the people. The Lord added to the assembly day by day those who were being saved.'),
  ('11607a5f-3039-5f80-abc3-b3b08ef9eb85', 'c0be0d3e-ca70-5673-a6e3-15289d4fb84a', NULL, 1, 1, 'Peter and John were going up into the temple at the hour of prayer, the ninth hour.'),
  ('530c839f-7dc3-56f4-aa19-15cd7604883c', 'c0be0d3e-ca70-5673-a6e3-15289d4fb84a', NULL, 2, 2, 'A certain man who was lame from his mother''s womb was being carried, whom they laid daily at the door of the temple which is called Beautiful, to ask gifts for the needy of those who entered into the temple.'),
  ('0a127dc3-4620-5f7e-aa84-c2d5afcc7f67', 'c0be0d3e-ca70-5673-a6e3-15289d4fb84a', NULL, 3, 3, 'Seeing Peter and John about to go into the temple, he asked to receive gifts for the needy.'),
  ('0542075c-f5d7-5fd3-a3a2-61ebc8012a66', 'c0be0d3e-ca70-5673-a6e3-15289d4fb84a', NULL, 4, 4, 'Peter, fastening his eyes on him, with John, said, "Look at us."'),
  ('682f5c89-87a5-578d-a9b0-1becae820551', 'c0be0d3e-ca70-5673-a6e3-15289d4fb84a', NULL, 5, 5, 'He listened to them, expecting to receive something from them.'),
  ('6d7ee92a-db53-5f0a-a2dc-de0e8ef5633c', 'c0be0d3e-ca70-5673-a6e3-15289d4fb84a', NULL, 6, 6, 'But Peter said, "Silver and gold have I none, but what I have, that I give you. In the name of Jesus Christ of Nazareth, get up and walk!"'),
  ('5e444063-7086-5a19-a58b-5a608fc12028', 'c0be0d3e-ca70-5673-a6e3-15289d4fb84a', NULL, 7, 7, 'He took him by the right hand, and raised him up. Immediately his feet and his ankle bones received strength.'),
  ('d7f2e2a2-69a8-5382-a02a-24aba3b799dd', 'c0be0d3e-ca70-5673-a6e3-15289d4fb84a', NULL, 8, 8, 'Leaping up, he stood, and began to walk. He entered with them into the temple, walking, leaping, and praising God.'),
  ('4ea38151-1287-5b36-a1a9-e228d21f1584', 'c0be0d3e-ca70-5673-a6e3-15289d4fb84a', NULL, 9, 9, 'All the people saw him walking and praising God.'),
  ('98c2a410-7998-55af-a4a2-211db6815c10', 'c0be0d3e-ca70-5673-a6e3-15289d4fb84a', NULL, 10, 10, 'They recognized him, that it was he who used to sit begging for gifts for the needy at the Beautiful Gate of the temple. They were filled with wonder and amazement at what had happened to him.'),
  ('ae9c207d-0a81-5a18-a495-8656bb5837ea', 'c0be0d3e-ca70-5673-a6e3-15289d4fb84a', NULL, 11, 11, 'As the lame man who was healed held on to Peter and John, all the people ran together to them in the porch that is called Solomon''s, greatly wondering.'),
  ('920b7ada-e253-54f8-a4ca-e134c4404032', 'c0be0d3e-ca70-5673-a6e3-15289d4fb84a', NULL, 12, 12, 'When Peter saw it, he responded to the people, "You men of Israel, why do you marvel at this man? Why do you fasten your eyes on us, as though by our own power or godliness we had made him walk?'),
  ('8e29f0c1-8a10-5378-afc7-40ac774f3fc3', 'c0be0d3e-ca70-5673-a6e3-15289d4fb84a', NULL, 13, 13, 'The God of Abraham, Isaac, and Jacob, the God of our fathers, has glorified his Servant Jesus, whom you delivered up, and denied in the presence of Pilate, when he had determined to release him.'),
  ('7160ed72-90e0-5c15-a0a2-649548510b0a', 'c0be0d3e-ca70-5673-a6e3-15289d4fb84a', NULL, 14, 14, 'But you denied the Holy and Righteous One, and asked for a murderer to be granted to you,'),
  ('2d16e90e-104b-5884-af67-dead445e9abd', 'c0be0d3e-ca70-5673-a6e3-15289d4fb84a', NULL, 15, 15, 'and killed the Prince of life, whom God raised from the dead, to which we are witnesses.'),
  ('c00de57d-1de5-567d-a0fb-1c2b5b036c10', 'c0be0d3e-ca70-5673-a6e3-15289d4fb84a', NULL, 16, 16, 'By faith in his name, his name has made this man strong, whom you see and know. Yes, the faith which is through him has given him this perfect soundness in the presence of you all.'),
  ('62855003-6709-5631-afb4-3fe7955ab0d2', 'c0be0d3e-ca70-5673-a6e3-15289d4fb84a', NULL, 17, 17, '"Now, brothers, I know that you did this in ignorance, as did also your rulers.'),
  ('c9fa9980-ed01-54b2-af53-50bf4a637ccf', 'c0be0d3e-ca70-5673-a6e3-15289d4fb84a', NULL, 18, 18, 'But the things which God announced by the mouth of all his prophets, that Christ should suffer, he thus fulfilled.'),
  ('ae5c2f1f-43d4-59ba-a49b-5d44b066a117', 'c0be0d3e-ca70-5673-a6e3-15289d4fb84a', NULL, 19, 19, '"Repent therefore, and turn again, that your sins may be blotted out, so that there may come times of refreshing from the presence of the Lord,'),
  ('be14ea02-e669-5445-a3eb-1b355c23b781', 'c0be0d3e-ca70-5673-a6e3-15289d4fb84a', NULL, 20, 20, 'and that he may send Christ Jesus, who was ordained for you before,'),
  ('de7343e8-76ae-5956-ab32-198b3862f5a1', 'c0be0d3e-ca70-5673-a6e3-15289d4fb84a', NULL, 21, 21, 'whom heaven must receive until the times of restoration of all things, which God spoke long ago by the mouth of his holy prophets.'),
  ('c713bc12-7ff6-507a-a068-098ca2bbb597', 'c0be0d3e-ca70-5673-a6e3-15289d4fb84a', NULL, 22, 22, 'For Moses indeed said to the fathers, ''The Lord God will raise up a prophet for you from among your brothers, like me. You shall listen to him in all things whatever he says to you.'),
  ('709aaa3f-f246-560a-aa91-10d0186e6432', 'c0be0d3e-ca70-5673-a6e3-15289d4fb84a', NULL, 23, 23, 'It will be, that every soul that will not listen to that prophet will be utterly destroyed from among the people.'''),
  ('85992ca4-ffe4-5073-ac36-6083b37f38c7', 'c0be0d3e-ca70-5673-a6e3-15289d4fb84a', NULL, 24, 24, 'Yes, and all the prophets from Samuel and those who followed after, as many as have spoken, they also told of these days.'),
  ('96f8e6df-31a0-5f53-a890-4862c309e0b6', 'c0be0d3e-ca70-5673-a6e3-15289d4fb84a', NULL, 25, 25, 'You are the children of the prophets, and of the covenant which God made with our fathers, saying to Abraham, ''In your seed will all the families of the earth be blessed.'''),
  ('4095d8a0-4dc2-5f5e-acf0-0068b74ffe1b', 'c0be0d3e-ca70-5673-a6e3-15289d4fb84a', NULL, 26, 26, 'God, having raised up his servant, Jesus, sent him to you first, to bless you, in turning away everyone of you from your wickedness."'),
  ('f7b76071-3b5b-5f77-a34d-06ce230869ea', 'cc1fab2a-6c33-5cf0-ae35-970a6cce882a', NULL, 1, 1, 'As they spoke to the people, the priests and the captain of the temple and the Sadducees came to them,'),
  ('43aea41c-7aa7-5b88-a73c-24a4c1361da5', 'cc1fab2a-6c33-5cf0-ae35-970a6cce882a', NULL, 2, 2, 'being upset because they taught the people and proclaimed in Jesus the resurrection from the dead.'),
  ('555b7894-addc-5493-a9d5-56501543f3d5', 'cc1fab2a-6c33-5cf0-ae35-970a6cce882a', NULL, 3, 3, 'They laid hands on them, and put them in custody until the next day, for it was now evening.'),
  ('8710dde2-ad07-5168-ad8a-3e46be26ca8a', 'cc1fab2a-6c33-5cf0-ae35-970a6cce882a', NULL, 4, 4, 'But many of those who heard the word believed, and the number of the men came to be about five thousand.'),
  ('ca290dff-b9c0-5f70-a345-acbc81a454ce', 'cc1fab2a-6c33-5cf0-ae35-970a6cce882a', NULL, 5, 5, 'It happened in the morning, that their rulers, elders, and scribes were gathered together in Jerusalem.'),
  ('118ba768-5ba4-5b32-a8ce-81b0a51e8864', 'cc1fab2a-6c33-5cf0-ae35-970a6cce882a', NULL, 6, 6, 'Annas the high priest was there, with Caiaphas, John, Alexander, and as many as were relatives of the high priest.'),
  ('09d8129d-4661-589c-acf9-d6ccc11987bb', 'cc1fab2a-6c33-5cf0-ae35-970a6cce882a', NULL, 7, 7, 'When they had stood them in the middle of them, they inquired, "By what power, or in what name, have you done this?"'),
  ('7d142e9f-5c89-5743-ae79-d2c35b2ddd86', 'cc1fab2a-6c33-5cf0-ae35-970a6cce882a', NULL, 8, 8, 'Then Peter, filled with the Holy Spirit, said to them, "You rulers of the people, and elders of Israel,'),
  ('0575bf43-9087-5608-a637-25af28206315', 'cc1fab2a-6c33-5cf0-ae35-970a6cce882a', NULL, 9, 9, 'if we are examined today concerning a good deed done to a crippled man, by what means this man has been healed,'),
  ('3ff1af3c-dbc2-5f15-ae46-6cc8f6709d5b', 'cc1fab2a-6c33-5cf0-ae35-970a6cce882a', NULL, 10, 10, 'be it known to you all, and to all the people of Israel, that in the name of Jesus Christ of Nazareth, whom you crucified, whom God raised from the dead, in him does this man stand here before you whole.'),
  ('1c9aa710-6885-59a1-a52c-0a86fed94315', 'cc1fab2a-6c33-5cf0-ae35-970a6cce882a', NULL, 11, 11, 'He is ''the stone which was regarded as worthless by you, the builders, which has become the head of the corner.'''),
  ('db1b7234-3853-57c2-aeb8-1393747dc7b7', 'cc1fab2a-6c33-5cf0-ae35-970a6cce882a', NULL, 12, 12, 'There is salvation in none other, for neither is there any other name under heaven, that is given among men, by which we must be saved!"'),
  ('9326a6ae-62e4-5540-a7a8-94500f810149', 'cc1fab2a-6c33-5cf0-ae35-970a6cce882a', NULL, 13, 13, 'Now when they saw the boldness of Peter and John, and had perceived that they were unlearned and ignorant men, they marveled. They recognized that they had been with Jesus.'),
  ('f6a34cbe-7450-5bd9-ade9-8de72a232e54', 'cc1fab2a-6c33-5cf0-ae35-970a6cce882a', NULL, 14, 14, 'Seeing the man who was healed standing with them, they could say nothing against it.'),
  ('5d22e690-b441-5454-a3e9-59a0a27f5b24', 'cc1fab2a-6c33-5cf0-ae35-970a6cce882a', NULL, 15, 15, 'But when they had commanded them to go aside out of the council, they conferred among themselves,'),
  ('7211b345-862a-5747-ad38-057df4413a51', 'cc1fab2a-6c33-5cf0-ae35-970a6cce882a', NULL, 16, 16, 'saying, "What shall we do to these men? Because indeed a notable miracle has been done through them, as can be plainly seen by all who dwell in Jerusalem, and we can''t deny it.'),
  ('e78c9734-0c13-5c6c-a5c1-219b9eb5aa1e', 'cc1fab2a-6c33-5cf0-ae35-970a6cce882a', NULL, 17, 17, 'But so that this spreads no further among the people, let''s threaten them, that from now on they don''t speak to anyone in this name."'),
  ('25db0580-ea21-5b8d-ad2f-6336feef197a', 'cc1fab2a-6c33-5cf0-ae35-970a6cce882a', NULL, 18, 18, 'They called them, and commanded them not to speak at all nor teach in the name of Jesus.'),
  ('0e6e95e7-ed30-5c42-a4fd-71f85395147b', 'cc1fab2a-6c33-5cf0-ae35-970a6cce882a', NULL, 19, 19, 'But Peter and John answered them, "Whether it is right in the sight of God to listen to you rather than to God, judge for yourselves,'),
  ('e6b2016a-4689-5c8c-a068-cb095993ed3c', 'cc1fab2a-6c33-5cf0-ae35-970a6cce882a', NULL, 20, 20, 'for we can''t help telling the things which we saw and heard."'),
  ('1c70e065-7ed2-5fff-a5a1-b0e7d6478e59', 'cc1fab2a-6c33-5cf0-ae35-970a6cce882a', NULL, 21, 21, 'When they had further threatened them, they let them go, finding no way to punish them, because of the people; for everyone glorified God for that which was done.'),
  ('a2ae8191-7b64-5eb5-a4aa-51283c9e467f', 'cc1fab2a-6c33-5cf0-ae35-970a6cce882a', NULL, 22, 22, 'For the man on whom this miracle of healing was performed was more than forty years old.'),
  ('6beb9883-3b8e-52d6-af0c-aae963b700cb', 'cc1fab2a-6c33-5cf0-ae35-970a6cce882a', NULL, 23, 23, 'Being let go, they came to their own company, and reported all that the chief priests and the elders had said to them.'),
  ('7df41e5b-912a-5981-afcc-81df86b054e7', 'cc1fab2a-6c33-5cf0-ae35-970a6cce882a', NULL, 24, 24, 'When they heard it, they lifted up their voice to God with one accord, and said, "O Lord, you are God, who made the heaven, the earth, the sea, and all that is in them;'),
  ('3c609ee2-447d-59ba-a5bc-c7db145c9a21', 'cc1fab2a-6c33-5cf0-ae35-970a6cce882a', NULL, 25, 25, 'who by the mouth of your servant, David, said, ''Why do the nations rage, and the peoples plot a vain thing?'),
  ('857140f5-2524-5046-ab68-a6bc7c6b449f', 'cc1fab2a-6c33-5cf0-ae35-970a6cce882a', NULL, 26, 26, 'The kings of the earth take a stand, and the rulers take council together, against the Lord, and against his Christ.'''),
  ('72340d5d-9368-5b93-ab46-716e45592a0f', 'cc1fab2a-6c33-5cf0-ae35-970a6cce882a', NULL, 27, 27, '"For truly, in this city against your holy servant, Jesus, whom you anointed, both Herod and Pontius Pilate, with the Gentiles and the people of Israel, were gathered together'),
  ('159b6d59-0354-5fae-a2ce-3986d5bc348c', 'cc1fab2a-6c33-5cf0-ae35-970a6cce882a', NULL, 28, 28, 'to do whatever your hand and your council foreordained to happen.'),
  ('e9704c88-1ae2-5fe6-a1fd-c3cf825da6f6', 'cc1fab2a-6c33-5cf0-ae35-970a6cce882a', NULL, 29, 29, 'Now, Lord, look at their threats, and grant to your servants to speak your word with all boldness,'),
  ('14fda8c5-cac4-5a04-abba-b453c088bc72', 'cc1fab2a-6c33-5cf0-ae35-970a6cce882a', NULL, 30, 30, 'while you stretch out your hand to heal; and that signs and wonders may be done through the name of your holy Servant Jesus."'),
  ('3d106d3e-044b-59b6-a3ca-3870d0a6fdbe', 'cc1fab2a-6c33-5cf0-ae35-970a6cce882a', NULL, 31, 31, 'When they had prayed, the place was shaken where they were gathered together. They were all filled with the Holy Spirit, and they spoke the word of God with boldness.'),
  ('9365b74c-1e73-58d6-a040-77f2efbd15a9', 'cc1fab2a-6c33-5cf0-ae35-970a6cce882a', NULL, 32, 32, 'The multitude of those who believed were of one heart and soul. Not one of them claimed that anything of the things which he possessed was his own, but they had all things in common.'),
  ('65b6296c-0e2d-51fe-a8e5-83082c1f09f6', 'cc1fab2a-6c33-5cf0-ae35-970a6cce882a', NULL, 33, 33, 'With great power, the apostles gave their testimony of the resurrection of the Lord Jesus. Great grace was on them all.'),
  ('06d3dd21-77ec-5e3d-a871-ac7c71800632', 'cc1fab2a-6c33-5cf0-ae35-970a6cce882a', NULL, 34, 34, 'For neither was there among them any who lacked, for as many as were owners of lands or houses sold them, and brought the proceeds of the things that were sold,'),
  ('b304204a-a6c7-5242-a655-d6c2ced3c00b', 'cc1fab2a-6c33-5cf0-ae35-970a6cce882a', NULL, 35, 35, 'and laid them at the apostles'' feet, and distribution was made to each, according as anyone had need.'),
  ('316a2935-1335-5c93-a8ca-c4c2946ef64b', 'cc1fab2a-6c33-5cf0-ae35-970a6cce882a', NULL, 36, 36, 'Joses, who by the apostles was surnamed Barnabas (which is, being interpreted, Son of Encouragement), a Levite, a man of Cyprus by race,'),
  ('407493c8-9e10-59a0-a057-40772115c5fe', 'cc1fab2a-6c33-5cf0-ae35-970a6cce882a', NULL, 37, 37, 'having a field, sold it, and brought the money and laid it at the apostles'' feet.'),
  ('76650bcc-72e0-56db-a488-110715d44a79', '80df09ad-3d2e-5a47-a8a5-1f17c9a1d544', NULL, 1, 1, 'But a certain man named Ananias, with Sapphira, his wife, sold a possession,'),
  ('2d2f9cd0-4dc9-5511-a598-e23b706bed98', '80df09ad-3d2e-5a47-a8a5-1f17c9a1d544', NULL, 2, 2, 'and kept back part of the price, his wife also being aware of it, and brought a certain part, and laid it at the apostles'' feet.'),
  ('befe0fbe-25dc-57e2-af2d-8ea37cb77b07', '80df09ad-3d2e-5a47-a8a5-1f17c9a1d544', NULL, 3, 3, 'But Peter said, "Ananias, why has Satan filled your heart to lie to the Holy Spirit, and to keep back part of the price of the land?'),
  ('1994973a-33ac-5c5c-a462-b61810ae5c0c', '80df09ad-3d2e-5a47-a8a5-1f17c9a1d544', NULL, 4, 4, 'While you kept it, didn''t it remain your own? After it was sold, wasn''t it in your power? How is it that you have conceived this thing in your heart? You haven''t lied to men, but to God."'),
  ('27884229-3548-585e-aacd-d28ff68014c8', '80df09ad-3d2e-5a47-a8a5-1f17c9a1d544', NULL, 5, 5, 'Ananias, hearing these words, fell down and died. Great fear came on all who heard these things.'),
  ('f44d5276-0fb1-5dc6-a8bb-9f6a5a0874c3', '80df09ad-3d2e-5a47-a8a5-1f17c9a1d544', NULL, 6, 6, 'The young men arose and wrapped him up, and they carried him out and buried him.'),
  ('8041f793-7340-5e5e-a4cf-68740fbeae56', '80df09ad-3d2e-5a47-a8a5-1f17c9a1d544', NULL, 7, 7, 'About three hours later, his wife, not knowing what had happened, came in.'),
  ('0191b48d-fed5-5c51-aa2c-39c73040dd38', '80df09ad-3d2e-5a47-a8a5-1f17c9a1d544', NULL, 8, 8, 'Peter answered her, "Tell me whether you sold the land for so much." She said, "Yes, for so much."'),
  ('c087baf8-d7b4-577a-a636-a28c96ed5b2e', '80df09ad-3d2e-5a47-a8a5-1f17c9a1d544', NULL, 9, 9, 'But Peter asked her, "How is it that you have agreed together to tempt the Spirit of the Lord? Behold, the feet of those who have buried your husband are at the door, and they will carry you out."'),
  ('d1d802ad-8a2e-517c-a5ce-0c4dfa6b7e77', '80df09ad-3d2e-5a47-a8a5-1f17c9a1d544', NULL, 10, 10, 'She fell down immediately at his feet, and died. The young men came in and found her dead, and they carried her out and buried her by her husband.'),
  ('2e216080-12ab-5424-a0f9-9d6cfdd1464f', '80df09ad-3d2e-5a47-a8a5-1f17c9a1d544', NULL, 11, 11, 'Great fear came on the whole assembly, and on all who heard these things.'),
  ('a77dd5e4-df61-5f30-abd6-e53b6e9ea03b', '80df09ad-3d2e-5a47-a8a5-1f17c9a1d544', NULL, 12, 12, 'By the hands of the apostles many signs and wonders were done among the people. They were all with one accord in Solomon''s porch.'),
  ('73f610bf-b2d6-57c2-aa2c-f02f14250f41', '80df09ad-3d2e-5a47-a8a5-1f17c9a1d544', NULL, 13, 13, 'None of the rest dared to join them, however the people honored them.'),
  ('82ba24f0-79cb-5afd-a785-5e784272425c', '80df09ad-3d2e-5a47-a8a5-1f17c9a1d544', NULL, 14, 14, 'More believers were added to the Lord, multitudes of both men and women.'),
  ('01a414b8-35c8-5f31-a3a8-15d435e1889f', '80df09ad-3d2e-5a47-a8a5-1f17c9a1d544', NULL, 15, 15, 'They even carried out the sick into the streets, and laid them on cots and mattresses, so that as Peter came by, at the least his shadow might overshadow some of them.'),
  ('1e6cfd3b-0a0b-5296-ab23-6d5fa7714201', '80df09ad-3d2e-5a47-a8a5-1f17c9a1d544', NULL, 16, 16, 'Multitudes also came together from the cities around Jerusalem, bringing sick people, and those who were tormented by unclean spirits: and they were all healed.'),
  ('f64e9684-1757-5ea4-ab26-7c4af7415e80', '80df09ad-3d2e-5a47-a8a5-1f17c9a1d544', NULL, 17, 17, 'But the high priest rose up, and all those who were with him (which is the sect of the Sadducees), and they were filled with jealousy,'),
  ('fceb8ebb-dd31-58d2-a74f-5d98c1ea87cc', '80df09ad-3d2e-5a47-a8a5-1f17c9a1d544', NULL, 18, 18, 'and laid hands on the apostles, and put them in public custody.'),
  ('34a02c35-8ec3-5d44-ac64-cc90a553b784', '80df09ad-3d2e-5a47-a8a5-1f17c9a1d544', NULL, 19, 19, 'But an angel of the Lord opened the prison doors by night, and brought them out, and said,'),
  ('c4fb8555-0218-5bdd-a75d-7c0345fc4208', '80df09ad-3d2e-5a47-a8a5-1f17c9a1d544', NULL, 20, 20, '"Go stand and speak in the temple to the people all the words of this life."'),
  ('bb8d8d3e-5c62-52d4-af1b-5139c485c8bc', '80df09ad-3d2e-5a47-a8a5-1f17c9a1d544', NULL, 21, 21, 'When they heard this, they entered into the temple about daybreak, and taught. But the high priest came, and those who were with him, and called the council together, and all the senate of the children of Israel, and sent to the prison to have them brought.'),
  ('4d869b58-33a4-5872-afc7-91c7472e4037', '80df09ad-3d2e-5a47-a8a5-1f17c9a1d544', NULL, 22, 22, 'But the officers who came didn''t find them in the prison. They returned and reported,'),
  ('d5f0deba-529f-5ae0-a4f3-7b13ad19e0de', '80df09ad-3d2e-5a47-a8a5-1f17c9a1d544', NULL, 23, 23, '"We found the prison shut and locked, and the guards standing before the doors, but when we opened them, we found no one inside!"'),
  ('d348070b-3afb-5ab7-a3d0-3581a0a9e269', '80df09ad-3d2e-5a47-a8a5-1f17c9a1d544', NULL, 24, 24, 'Now when the high priest, the captain of the temple, and the chief priests heard these words, they were very perplexed about them and what might become of this.'),
  ('e403a611-e5f4-5f5b-a3d9-58cd5bdd7a71', '80df09ad-3d2e-5a47-a8a5-1f17c9a1d544', NULL, 25, 25, 'One came and told them, "Behold, the men whom you put in prison are in the temple, standing and teaching the people."'),
  ('b63bb815-f298-5e1c-a663-36eacd04d6f7', '80df09ad-3d2e-5a47-a8a5-1f17c9a1d544', NULL, 26, 26, 'Then the captain went with the officers, and brought them without violence, for they were afraid that the people might stone them.'),
  ('71496ac1-4ba2-5cc8-a30d-faf8b0b540e0', '80df09ad-3d2e-5a47-a8a5-1f17c9a1d544', NULL, 27, 27, 'When they had brought them, they set them before the council. The high priest questioned them,'),
  ('662a2c91-61ec-5990-abe2-e1492be6879f', '80df09ad-3d2e-5a47-a8a5-1f17c9a1d544', NULL, 28, 28, 'saying, "Didn''t we strictly command you not to teach in this name? Behold, you have filled Jerusalem with your teaching, and intend to bring this man''s blood on us."'),
  ('643dfc74-e6af-593a-a3f6-149167ac397b', '80df09ad-3d2e-5a47-a8a5-1f17c9a1d544', NULL, 29, 29, 'But Peter and the apostles answered, "We must obey God rather than men.'),
  ('9bc9ce87-1049-5fdc-a5bf-78361966f00e', '80df09ad-3d2e-5a47-a8a5-1f17c9a1d544', NULL, 30, 30, 'The God of our fathers raised up Jesus, whom you killed, hanging him on a tree.'),
  ('aba8d87a-e0e3-5fc0-a0b1-83c515a36cb8', '80df09ad-3d2e-5a47-a8a5-1f17c9a1d544', NULL, 31, 31, 'God exalted him with his right hand to be a Prince and a Savior, to give repentance to Israel, and remission of sins.'),
  ('c4a536e8-b775-52b2-a38c-fd2ff55cb890', '80df09ad-3d2e-5a47-a8a5-1f17c9a1d544', NULL, 32, 32, 'We are His witnesses of these things; and so also is the Holy Spirit, whom God has given to those who obey him."'),
  ('e8ff979c-9f96-5053-addc-18b3e4e0a742', '80df09ad-3d2e-5a47-a8a5-1f17c9a1d544', NULL, 33, 33, 'But they, when they heard this, were cut to the heart, and determined to kill them.'),
  ('c7660ba2-8b38-5ee2-aeea-6e2095e68cd9', '80df09ad-3d2e-5a47-a8a5-1f17c9a1d544', NULL, 34, 34, 'But one stood up in the council, a Pharisee named Gamaliel, a teacher of the law, honored by all the people, and commanded to put the apostles out for a little while.'),
  ('858083ad-e1e8-57a9-a38f-2ffe8baa43a5', '80df09ad-3d2e-5a47-a8a5-1f17c9a1d544', NULL, 35, 35, 'He said to them, "You men of Israel, be careful concerning these men, what you are about to do.'),
  ('755b2baa-cc1b-5925-a473-aa5c85be3317', '80df09ad-3d2e-5a47-a8a5-1f17c9a1d544', NULL, 36, 36, 'For before these days Theudas rose up, making himself out to be somebody; to whom a number of men, about four hundred, joined themselves: who was slain; and all, as many as obeyed him, were dispersed, and came to nothing.'),
  ('a7674b6d-0f4f-5fbc-a523-9cd2edf19d3b', '80df09ad-3d2e-5a47-a8a5-1f17c9a1d544', NULL, 37, 37, 'After this man, Judas of Galilee rose up in the days of the enrollment, and drew away some people after him. He also perished, and all, as many as obeyed him, were scattered abroad.'),
  ('f9b7a6dd-273d-5499-a713-7841bd7d2258', '80df09ad-3d2e-5a47-a8a5-1f17c9a1d544', NULL, 38, 38, 'Now I tell you, withdraw from these men, and leave them alone. For if this counsel or this work is of men, it will be overthrown.'),
  ('5bc4a3fc-1c2b-518e-a25e-1b3aa67ea6ee', '80df09ad-3d2e-5a47-a8a5-1f17c9a1d544', NULL, 39, 39, 'But if it is of God, you will not be able to overthrow it, and you would be found even to be fighting against God!"'),
  ('59771039-ac89-549b-a1ab-c351583dda92', '80df09ad-3d2e-5a47-a8a5-1f17c9a1d544', NULL, 40, 40, 'They agreed with him. Summoning the apostles, they beat them and commanded them not to speak in the name of Jesus, and let them go.'),
  ('40a64815-9fa0-5df2-ae8b-a6b133ccc453', '80df09ad-3d2e-5a47-a8a5-1f17c9a1d544', NULL, 41, 41, 'They therefore departed from the presence of the council, rejoicing that they were counted worthy to suffer dishonor for Jesus'' name.'),
  ('715ea43a-28db-5216-afb3-a595e3991a6d', '80df09ad-3d2e-5a47-a8a5-1f17c9a1d544', NULL, 42, 42, 'Every day, in the temple and at home, they never stopped teaching and preaching Jesus, the Christ.'),
  ('48f5c937-13e1-5123-afe7-cea4bea77bb0', '293bb1fd-f31b-522c-a995-88cce82e2792', NULL, 1, 1, 'Now in those days, when the number of the disciples was multiplying, a complaint arose from the Hellenists against the Hebrews, because their widows were neglected in the daily service.'),
  ('bf679803-5420-5878-ad18-5ab492ed852d', '293bb1fd-f31b-522c-a995-88cce82e2792', NULL, 2, 2, 'The twelve summoned the multitude of the disciples and said, "It is not appropriate for us to forsake the word of God and serve tables.'),
  ('3027e6b6-cfb4-5269-a063-f1228a8a03b5', '293bb1fd-f31b-522c-a995-88cce82e2792', NULL, 3, 3, 'Therefore select from among you, brothers, seven men of good report, full of the Holy Spirit and of wisdom, whom we may appoint over this business.'),
  ('cfdf7ce4-7a0b-53cf-a789-9f8ca1015826', '293bb1fd-f31b-522c-a995-88cce82e2792', NULL, 4, 4, 'But we will continue steadfastly in prayer and in the ministry of the word."'),
  ('35f50b52-9141-5381-a3d6-dc010df952d2', '293bb1fd-f31b-522c-a995-88cce82e2792', NULL, 5, 5, 'These words pleased the whole multitude. They chose Stephen, a man full of faith and of the Holy Spirit, Philip, Prochorus, Nicanor, Timon, Parmenas, and Nicolaus, a proselyte of Antioch;'),
  ('09b9bfed-2bba-57e0-abdc-c690406feb80', '293bb1fd-f31b-522c-a995-88cce82e2792', NULL, 6, 6, 'whom they set before the apostles. When they had prayed, they laid their hands on them.'),
  ('1abe52f6-0477-539c-a39b-109df1462dfb', '293bb1fd-f31b-522c-a995-88cce82e2792', NULL, 7, 7, 'The word of God increased and the number of the disciples multiplied in Jerusalem exceedingly. A great company of the priests were obedient to the faith.'),
  ('d933fe0c-4b47-55c8-ae92-2bb176332edd', '293bb1fd-f31b-522c-a995-88cce82e2792', NULL, 8, 8, 'Stephen, full of faith and power, performed great wonders and signs among the people.'),
  ('3bf1577c-5ae6-539f-a560-b3d05842ea19', '293bb1fd-f31b-522c-a995-88cce82e2792', NULL, 9, 9, 'But some of those who were of the synagogue called "The Libertines," and of the Cyrenians, of the Alexandrians, and of those of Cilicia and Asia arose, disputing with Stephen.')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('5a478230-0775-5268-a1ae-f40437a201fe', '293bb1fd-f31b-522c-a995-88cce82e2792', NULL, 10, 10, 'They weren''t able to withstand the wisdom and the Spirit by which he spoke.'),
  ('85ad4b1d-2ff7-52e2-aca1-f9d9bbdbdd5a', '293bb1fd-f31b-522c-a995-88cce82e2792', NULL, 11, 11, 'Then they secretly induced men to say, "We have heard him speak blasphemous words against Moses and God."'),
  ('062e1cf1-677c-5f99-abd3-97b62d13fc03', '293bb1fd-f31b-522c-a995-88cce82e2792', NULL, 12, 12, 'They stirred up the people, the elders, and the scribes, and came against him and seized him, and brought him in to the council,'),
  ('505ee5ed-f64b-5804-aaf7-661ca54dbd94', '293bb1fd-f31b-522c-a995-88cce82e2792', NULL, 13, 13, 'and set up false witnesses who said, "This man never stops speaking blasphemous words against this holy place and the law.'),
  ('44a8ea59-0f53-5557-aa5d-be03cc03fe6f', '293bb1fd-f31b-522c-a995-88cce82e2792', NULL, 14, 14, 'For we have heard him say that this Jesus of Nazareth will destroy this place, and will change the customs which Moses delivered to us."'),
  ('79c365bf-3eba-59bc-a99d-44548f2cdb07', '293bb1fd-f31b-522c-a995-88cce82e2792', NULL, 15, 15, 'All who sat in the council, fastening their eyes on him, saw his face like it was the face of an angel.'),
  ('b73512f7-ff76-5dce-a59f-59c88387ecf6', 'e01d0359-c2af-5630-a6c0-93e4d0d62aad', NULL, 1, 1, 'The high priest said, "Are these things so?"'),
  ('36671f8d-e935-5595-a91d-985d83cb2a3c', 'e01d0359-c2af-5630-a6c0-93e4d0d62aad', NULL, 2, 2, 'He said, "Brothers and fathers, listen. The God of glory appeared to our father Abraham, when he was in Mesopotamia, before he lived in Haran,'),
  ('245fd049-0d47-5193-a417-33d85ddf7dc3', 'e01d0359-c2af-5630-a6c0-93e4d0d62aad', NULL, 3, 3, 'and said to him, ''Get out of your land, and from your relatives, and come into a land which I will show you.'''),
  ('763798b8-8b54-5a2e-a098-35f9a6199f77', 'e01d0359-c2af-5630-a6c0-93e4d0d62aad', NULL, 4, 4, 'Then he came out of the land of the Chaldaeans, and lived in Haran. From there, when his father was dead, God moved him into this land, where you are now living.'),
  ('ce583164-c5d7-5739-a57d-11f5998c3688', 'e01d0359-c2af-5630-a6c0-93e4d0d62aad', NULL, 5, 5, 'He gave him no inheritance in it, no, not so much as to set his foot on. He promised that he would give it to him for a possession, and to his seed after him, when he still had no child.'),
  ('3e3f41fd-9401-50c9-a7ac-2bf5a159b66a', 'e01d0359-c2af-5630-a6c0-93e4d0d62aad', NULL, 6, 6, 'God spoke in this way: that his seed would live as aliens in a strange land, and that they would be enslaved and mistreated for four hundred years.'),
  ('84fc5d68-7b61-5235-a787-c08a5e5e87fa', 'e01d0359-c2af-5630-a6c0-93e4d0d62aad', NULL, 7, 7, '''I will judge the nation to which they will be in bondage,'' said God, ''and after that will they come out, and serve me in this place.'''),
  ('4b076bb0-e6c7-5626-aa20-9f42d6900917', 'e01d0359-c2af-5630-a6c0-93e4d0d62aad', NULL, 8, 8, 'He gave him the covenant of circumcision. So Abraham became the father of Isaac, and circumcised him the eighth day. Isaac became the father of Jacob, and Jacob became the father of the twelve patriarchs.'),
  ('652e0f8d-4ca0-58ee-a0ae-e167c50c47dd', 'e01d0359-c2af-5630-a6c0-93e4d0d62aad', NULL, 9, 9, '"The patriarchs, moved with jealousy against Joseph, sold him into Egypt. God was with him,'),
  ('f6113b1b-7bef-55c2-a7fe-20b1e3091dac', 'e01d0359-c2af-5630-a6c0-93e4d0d62aad', NULL, 10, 10, 'and delivered him out of all his afflictions, and gave him favor and wisdom before Pharaoh, king of Egypt. He made him governor over Egypt and all his house.'),
  ('2d44dcd1-dcb4-5ed4-aab1-50b96e560571', 'e01d0359-c2af-5630-a6c0-93e4d0d62aad', NULL, 11, 11, 'Now a famine came over all the land of Egypt and Canaan, and great affliction. Our fathers found no food.'),
  ('483ed3e8-14a8-5a79-a408-1c2a98746e25', 'e01d0359-c2af-5630-a6c0-93e4d0d62aad', NULL, 12, 12, 'But when Jacob heard that there was grain in Egypt, he sent out our fathers the first time.'),
  ('8ae3f930-20b2-5cbc-ab84-34a980b1582c', 'e01d0359-c2af-5630-a6c0-93e4d0d62aad', NULL, 13, 13, 'On the second time Joseph was made known to his brothers, and Joseph''s race was revealed to Pharaoh.'),
  ('4f34a34e-fc30-5e71-a241-849f7956afe5', 'e01d0359-c2af-5630-a6c0-93e4d0d62aad', NULL, 14, 14, 'Joseph sent, and summoned Jacob, his father, and all his relatives, seventy-five souls.'),
  ('8a067a88-c35c-5358-ab8c-089645cd6b8e', 'e01d0359-c2af-5630-a6c0-93e4d0d62aad', NULL, 15, 15, 'Jacob went down into Egypt, and he died, himself and our fathers,'),
  ('503c9906-3c68-512c-a5a1-33aded71d059', 'e01d0359-c2af-5630-a6c0-93e4d0d62aad', NULL, 16, 16, 'and they were brought back to Shechem, and laid in the tomb that Abraham bought for a price in silver from the children of Hamor of Shechem.'),
  ('90e6138e-d9b6-5305-a4eb-b31fc20ffec6', 'e01d0359-c2af-5630-a6c0-93e4d0d62aad', NULL, 17, 17, '"But as the time of the promise came close which God had sworn to Abraham, the people grew and multiplied in Egypt,'),
  ('68b37b75-8869-5631-a84f-48aabfda45a2', 'e01d0359-c2af-5630-a6c0-93e4d0d62aad', NULL, 18, 18, 'until there arose a different king, who didn''t know Joseph.'),
  ('4a95c1ef-0a96-5b89-aeaf-1b52d58cad4e', 'e01d0359-c2af-5630-a6c0-93e4d0d62aad', NULL, 19, 19, 'The same took advantage of our race, and mistreated our fathers, and forced them to throw out their babies, so that they wouldn''t stay alive.'),
  ('a029e435-8c0b-5452-af15-4de8589455cd', 'e01d0359-c2af-5630-a6c0-93e4d0d62aad', NULL, 20, 20, 'At that time Moses was born, and was exceedingly handsome. He was nourished three months in his father''s house.'),
  ('efa31eb5-a1cc-507b-a708-11f7ae0eed36', 'e01d0359-c2af-5630-a6c0-93e4d0d62aad', NULL, 21, 21, 'When he was thrown out, Pharaoh''s daughter took him up, and reared him as her own son.'),
  ('3e82dc96-0a34-513d-a96a-67935191dd8d', 'e01d0359-c2af-5630-a6c0-93e4d0d62aad', NULL, 22, 22, 'Moses was instructed in all the wisdom of the Egyptians. He was mighty in his words and works.'),
  ('79a48f05-5b61-5a78-a1b9-d9f926abe6fb', 'e01d0359-c2af-5630-a6c0-93e4d0d62aad', NULL, 23, 23, 'But when he was forty years old, it came into his heart to visit his brothers, the children of Israel.'),
  ('b8a9bb8f-f943-5f25-ac5c-d901971553ab', 'e01d0359-c2af-5630-a6c0-93e4d0d62aad', NULL, 24, 24, 'Seeing one of them suffer wrong, he defended him, and avenged him who was oppressed, striking the Egyptian.'),
  ('8a7a0b16-067b-5556-a361-efd3d81670dd', 'e01d0359-c2af-5630-a6c0-93e4d0d62aad', NULL, 25, 25, 'He supposed that his brothers understood that God, by his hand, was giving them deliverance; but they didn''t understand.'),
  ('17deee95-cd89-54ab-ad66-4ac54f550656', 'e01d0359-c2af-5630-a6c0-93e4d0d62aad', NULL, 26, 26, '"The day following, he appeared to them as they fought, and urged them to be at peace again, saying, ''Sirs, you are brothers. Why do you wrong one another?'''),
  ('0a52aa0a-6468-5fb5-a54c-18068cf6db0c', 'e01d0359-c2af-5630-a6c0-93e4d0d62aad', NULL, 27, 27, 'But he who did his neighbor wrong pushed him away, saying, ''Who made you a ruler and a judge over us?'),
  ('b87d5f7b-ad8e-5176-a8f9-b325f0b6f710', 'e01d0359-c2af-5630-a6c0-93e4d0d62aad', NULL, 28, 28, 'Do you want to kill me, as you killed the Egyptian yesterday?'''),
  ('a56d70e0-52b7-59a7-a3cc-25a34a32c0d7', 'e01d0359-c2af-5630-a6c0-93e4d0d62aad', NULL, 29, 29, 'Moses fled at this saying, and became a stranger in the land of Midian, where he became the father of two sons.'),
  ('a1056566-862d-567f-a5e7-04e7ced578ac', 'e01d0359-c2af-5630-a6c0-93e4d0d62aad', NULL, 30, 30, '"When forty years were fulfilled, an angel of the Lord appeared to him in the wilderness of Mount Sinai, in a flame of fire in a bush.'),
  ('a783d167-5f42-5338-aded-48c4c2448cb8', 'e01d0359-c2af-5630-a6c0-93e4d0d62aad', NULL, 31, 31, 'When Moses saw it, he wondered at the sight. As he came close to see, a voice of the Lord came to him,'),
  ('60de6958-02c4-586e-a8cb-c73382f93697', 'e01d0359-c2af-5630-a6c0-93e4d0d62aad', NULL, 32, 32, '''I am the God of your fathers, the God of Abraham, the God of Isaac, and the God of Jacob.'' Moses trembled, and dared not look.'),
  ('e5e7f2e9-8234-5e7c-a1b3-25f550086089', 'e01d0359-c2af-5630-a6c0-93e4d0d62aad', NULL, 33, 33, 'The Lord said to him, ''Take your sandals off of your feet, for the place where you stand is holy ground.'),
  ('f6d38f95-c1ba-5dc5-a46c-4c4a1e61feaa', 'e01d0359-c2af-5630-a6c0-93e4d0d62aad', NULL, 34, 34, 'I have surely seen the affliction of my people that is in Egypt, and have heard their groaning. I have come down to deliver them. Now come, I will send you into Egypt.'''),
  ('4e123c86-b4e5-50f2-abdb-9e60c72cf934', 'e01d0359-c2af-5630-a6c0-93e4d0d62aad', NULL, 35, 35, '"This Moses, whom they refused, saying, ''Who made you a ruler and a judge?''--God has sent him as both a ruler and a deliverer by the hand of the angel who appeared to him in the bush.'),
  ('03d6e34b-0a0c-53c5-a0c1-a3adda4c8cd2', 'e01d0359-c2af-5630-a6c0-93e4d0d62aad', NULL, 36, 36, 'This man led them out, having worked wonders and signs in Egypt, in the Red Sea, and in the wilderness for forty years.'),
  ('f4a1210e-e65b-522d-a49e-09bbd20997e4', 'e01d0359-c2af-5630-a6c0-93e4d0d62aad', NULL, 37, 37, 'This is that Moses, who said to the children of Israel, ''The Lord our God will raise up a prophet for you from among your brothers, like me.'''),
  ('10fa323e-4fb0-5606-a79d-2a510b90e0ff', 'e01d0359-c2af-5630-a6c0-93e4d0d62aad', NULL, 38, 38, 'This is he who was in the assembly in the wilderness with the angel that spoke to him on Mount Sinai, and with our fathers, who received living oracles to give to us,'),
  ('7a93836c-0f13-567b-aa7a-569132e6ebde', 'e01d0359-c2af-5630-a6c0-93e4d0d62aad', NULL, 39, 39, 'to whom our fathers wouldn''t be obedient, but rejected him, and turned back in their hearts to Egypt,'),
  ('76f5be5a-abaa-51be-a2e5-e975dedb74d6', 'e01d0359-c2af-5630-a6c0-93e4d0d62aad', NULL, 40, 40, 'saying to Aaron, ''Make us gods that will go before us, for as for this Moses, who led us out of the land of Egypt, we don''t know what has become of him.'''),
  ('ddaa825b-b96f-5ac1-a190-d8cc7863aa33', 'e01d0359-c2af-5630-a6c0-93e4d0d62aad', NULL, 41, 41, 'They made a calf in those days, and brought a sacrifice to the idol, and rejoiced in the works of their hands.'),
  ('454a1f0f-0c02-5c18-af99-3ad7d365d94f', 'e01d0359-c2af-5630-a6c0-93e4d0d62aad', NULL, 42, 42, 'But God turned, and gave them up to serve the army of the sky, as it is written in the book of the prophets, ''Did you offer to me slain animals and sacrifices forty years in the wilderness, O house of Israel?'),
  ('ccf43197-75c2-5c9b-abd0-b2f68011333d', 'e01d0359-c2af-5630-a6c0-93e4d0d62aad', NULL, 43, 43, 'You took up the tabernacle of Moloch, the star of your god Rephan, the figures which you made to worship. I will carry you away beyond Babylon.'''),
  ('06819681-422e-50c2-a981-ccbf7e9d8666', 'e01d0359-c2af-5630-a6c0-93e4d0d62aad', NULL, 44, 44, '"Our fathers had the tabernacle of the testimony in the wilderness, even as he who spoke to Moses commanded him to make it according to the pattern that he had seen;'),
  ('1aa5253c-111c-5998-af47-2f283be3ba7c', 'e01d0359-c2af-5630-a6c0-93e4d0d62aad', NULL, 45, 45, 'which also our fathers, in their turn, brought in with Joshua when they entered into the possession of the nations, whom God drove out before the face of our fathers, to the days of David,'),
  ('68905d95-74be-5f74-a336-4834abce72d8', 'e01d0359-c2af-5630-a6c0-93e4d0d62aad', NULL, 46, 46, 'who found favor in the sight of God, and asked to find a habitation for the God of Jacob.'),
  ('9547438b-5981-5a9c-a6fc-9561d1c8c999', 'e01d0359-c2af-5630-a6c0-93e4d0d62aad', NULL, 47, 47, 'But Solomon built him a house.'),
  ('c22a0d67-16fd-59c4-a2d3-fff018c6f100', 'e01d0359-c2af-5630-a6c0-93e4d0d62aad', NULL, 48, 48, 'However, the Most High doesn''t dwell in temples made with hands, as the prophet says,'),
  ('5df4cc20-bbce-5030-a66f-03bfe836b7de', 'e01d0359-c2af-5630-a6c0-93e4d0d62aad', NULL, 49, 49, '''heaven is my throne, and the earth a footstool for my feet. What kind of house will you build me?'' says the Lord; ''or what is the place of my rest?'),
  ('380cae34-39ee-50d9-ab2b-0607cd00b16d', 'e01d0359-c2af-5630-a6c0-93e4d0d62aad', NULL, 50, 50, 'Didn''t my hand make all these things?'''),
  ('967dc958-2e77-5ace-a33d-cf701c748279', 'e01d0359-c2af-5630-a6c0-93e4d0d62aad', NULL, 51, 51, '"You stiff-necked and uncircumcised in heart and ears, you always resist the Holy Spirit! As your fathers did, so you do.'),
  ('5ff92c6f-8ef6-5943-aa1c-4f9fb0e84431', 'e01d0359-c2af-5630-a6c0-93e4d0d62aad', NULL, 52, 52, 'Which of the prophets didn''t your fathers persecute? They killed those who foretold the coming of the Righteous One, of whom you have now become betrayers and murderers.'),
  ('e5d0e61c-037b-5dfb-adc2-811f9faaed07', 'e01d0359-c2af-5630-a6c0-93e4d0d62aad', NULL, 53, 53, 'You received the law as it was ordained by angels, and didn''t keep it!"'),
  ('f1bdefb5-5b13-5b94-ab39-a61b66f8ad7d', 'e01d0359-c2af-5630-a6c0-93e4d0d62aad', NULL, 54, 54, 'Now when they heard these things, they were cut to the heart, and they gnashed at him with their teeth.'),
  ('271836d4-ebc9-5c57-a88c-edb45bff0dc2', 'e01d0359-c2af-5630-a6c0-93e4d0d62aad', NULL, 55, 55, 'But he, being full of the Holy Spirit, looked up steadfastly into heaven, and saw the glory of God, and Jesus standing on the right hand of God,'),
  ('9a2a7924-d83b-5e5b-af11-679142a00bf5', 'e01d0359-c2af-5630-a6c0-93e4d0d62aad', NULL, 56, 56, 'and said, "Behold, I see the heavens opened, and the Son of Man standing at the right hand of God!"'),
  ('2d05f5eb-8bef-5bd0-a96f-06069b48fc93', 'e01d0359-c2af-5630-a6c0-93e4d0d62aad', NULL, 57, 57, 'But they cried out with a loud voice, and stopped their ears, and rushed at him with one accord.'),
  ('878c4704-81cb-5be0-a653-a9c47e895179', 'e01d0359-c2af-5630-a6c0-93e4d0d62aad', NULL, 58, 58, 'They threw him out of the city, and stoned him. The witnesses placed their garments at the feet of a young man named Saul.'),
  ('22926c1a-15f6-5ecf-a019-9431526be060', 'e01d0359-c2af-5630-a6c0-93e4d0d62aad', NULL, 59, 59, 'They stoned Stephen as he called out, saying, "Lord Jesus, receive my spirit!"'),
  ('a46f830a-81e0-5014-aba4-f6e650cccc1e', 'e01d0359-c2af-5630-a6c0-93e4d0d62aad', NULL, 60, 60, 'He kneeled down, and cried with a loud voice, "Lord, don''t hold this sin against them!" When he had said this, he fell asleep.'),
  ('efb9f00e-5ff0-5fbd-a53d-84fec99e9d5a', 'b023b4e1-614a-5174-ad7b-b2bffa09afe3', NULL, 1, 1, 'Saul was consenting to his death. A great persecution arose against the assembly which was in Jerusalem in that day. They were all scattered abroad throughout the regions of Judea and Samaria, except for the apostles.'),
  ('6bc50cfd-59c3-5a77-a394-03464359eba4', 'b023b4e1-614a-5174-ad7b-b2bffa09afe3', NULL, 2, 2, 'Devout men buried Stephen, and lamented greatly over him.'),
  ('f4521669-9b20-5250-a5bc-801ce071742c', 'b023b4e1-614a-5174-ad7b-b2bffa09afe3', NULL, 3, 3, 'But Saul ravaged the assembly, entering into every house, and dragged both men and women off to prison.'),
  ('0ef099c8-3d94-504b-a08c-0f2a8a8939e7', 'b023b4e1-614a-5174-ad7b-b2bffa09afe3', NULL, 4, 4, 'Therefore those who were scattered abroad went around preaching the word.'),
  ('29654c35-d338-53d5-aa1c-6e3d099bc7a3', 'b023b4e1-614a-5174-ad7b-b2bffa09afe3', NULL, 5, 5, 'Philip went down to the city of Samaria, and proclaimed to them the Christ.'),
  ('7eb30e42-2754-523e-a351-9baf1417c4b1', 'b023b4e1-614a-5174-ad7b-b2bffa09afe3', NULL, 6, 6, 'The multitudes listened with one accord to the things that were spoken by Philip, when they heard and saw the signs which he did.'),
  ('4f67c093-5020-51ad-ae3a-899030f4a585', 'b023b4e1-614a-5174-ad7b-b2bffa09afe3', NULL, 7, 7, 'For unclean spirits came out of many of those who had them. They came out, crying with a loud voice. Many who had been paralyzed and lame were healed.'),
  ('171c2337-c97e-5edf-a2db-342014925cf2', 'b023b4e1-614a-5174-ad7b-b2bffa09afe3', NULL, 8, 8, 'There was great joy in that city.'),
  ('e6b8c801-ed91-5ba1-a642-dca57c56b615', 'b023b4e1-614a-5174-ad7b-b2bffa09afe3', NULL, 9, 9, 'But there was a certain man, Simon by name, who used to practice sorcery in the city, and amazed the people of Samaria, making himself out to be some great one,'),
  ('20c20217-7f43-55d4-a1e6-67a5685d5e80', 'b023b4e1-614a-5174-ad7b-b2bffa09afe3', NULL, 10, 10, 'to whom they all listened, from the least to the greatest, saying, "This man is that great power of God."'),
  ('82f04c0c-c61b-5064-a370-6823dbdba1e6', 'b023b4e1-614a-5174-ad7b-b2bffa09afe3', NULL, 11, 11, 'They listened to him, because for a long time he had amazed them with his sorceries.'),
  ('49134204-ba2d-56d3-a18a-ee041cee486e', 'b023b4e1-614a-5174-ad7b-b2bffa09afe3', NULL, 12, 12, 'But when they believed Philip preaching good news concerning the Kingdom of God and the name of Jesus Christ, they were baptized, both men and women.'),
  ('d059784e-e5a2-54e1-af15-1d4472963f6f', 'b023b4e1-614a-5174-ad7b-b2bffa09afe3', NULL, 13, 13, 'Simon himself also believed. Being baptized, he continued with Philip. Seeing signs and great miracles occurring, he was amazed.'),
  ('de67793a-f464-5479-ac86-eb32db133e18', 'b023b4e1-614a-5174-ad7b-b2bffa09afe3', NULL, 14, 14, 'Now when the apostles who were at Jerusalem heard that Samaria had received the word of God, they sent Peter and John to them,'),
  ('1c602033-e857-53e8-a442-87eb17f0c873', 'b023b4e1-614a-5174-ad7b-b2bffa09afe3', NULL, 15, 15, 'who, when they had come down, prayed for them, that they might receive the Holy Spirit;'),
  ('bc346948-996f-56d2-ae52-4f5e7f5cbefb', 'b023b4e1-614a-5174-ad7b-b2bffa09afe3', NULL, 16, 16, 'for as yet he had fallen on none of them. They had only been baptized in the name of Christ Jesus.'),
  ('5d78c30e-1c7b-5956-a200-3b0b35773145', 'b023b4e1-614a-5174-ad7b-b2bffa09afe3', NULL, 17, 17, 'Then they laid their hands on them, and they received the Holy Spirit.'),
  ('2b0a4453-3917-5901-a9c0-a7757aa5acd8', 'b023b4e1-614a-5174-ad7b-b2bffa09afe3', NULL, 18, 18, 'Now when Simon saw that the Holy Spirit was given through the laying on of the apostles'' hands, he offered them money,'),
  ('bbd393a4-b393-599c-a5cb-541f0434fac4', 'b023b4e1-614a-5174-ad7b-b2bffa09afe3', NULL, 19, 19, 'saying, "Give me also this power, that whoever I lay my hands on may receive the Holy Spirit."'),
  ('bd0001e9-7ff2-51ca-a471-2d78fedd0040', 'b023b4e1-614a-5174-ad7b-b2bffa09afe3', NULL, 20, 20, 'But Peter said to him, "May your silver perish with you, because you thought you could obtain the gift of God with money!'),
  ('3cb4662c-198c-59d3-a5b2-8a4f87f648d9', 'b023b4e1-614a-5174-ad7b-b2bffa09afe3', NULL, 21, 21, 'You have neither part nor lot in this matter, for your heart isn''t right before God.'),
  ('e5b7cd70-e147-5842-a021-f3245d5b9c69', 'b023b4e1-614a-5174-ad7b-b2bffa09afe3', NULL, 22, 22, 'Repent therefore of this, your wickedness, and ask God if perhaps the thought of your heart may be forgiven you.'),
  ('6f9fc209-2f52-5bef-af4a-f5588f139f26', 'b023b4e1-614a-5174-ad7b-b2bffa09afe3', NULL, 23, 23, 'For I see that you are in the gall of bitterness and in the bondage of iniquity."'),
  ('9a7da9b9-ac57-5e25-aade-a6a4a525e0ef', 'b023b4e1-614a-5174-ad7b-b2bffa09afe3', NULL, 24, 24, 'Simon answered, "Pray for me to the Lord, that none of the things which you have spoken happen to me."'),
  ('6428b55d-e89e-5158-a7d7-8163b5ddaec3', 'b023b4e1-614a-5174-ad7b-b2bffa09afe3', NULL, 25, 25, 'They therefore, when they had testified and spoken the word of the Lord, returned to Jerusalem, and preached the Good News to many villages of the Samaritans.'),
  ('319f15fe-4b60-50ce-aa56-124c1f9d07d5', 'b023b4e1-614a-5174-ad7b-b2bffa09afe3', NULL, 26, 26, 'But an angel of the Lord spoke to Philip, saying, "Arise, and go toward the south to the way that goes down from Jerusalem to Gaza. This is a desert."'),
  ('d34c3167-c8c6-5ff8-af02-253e9383ed78', 'b023b4e1-614a-5174-ad7b-b2bffa09afe3', NULL, 27, 27, 'He arose and went; and behold, there was a man of Ethiopia, a eunuch of great authority under Candace, queen of the Ethiopians, who was over all her treasure, who had come to Jerusalem to worship.'),
  ('c210062b-9df9-59cd-ae96-a95ba3bef219', 'b023b4e1-614a-5174-ad7b-b2bffa09afe3', NULL, 28, 28, 'He was returning and sitting in his chariot, and was reading the prophet Isaiah.'),
  ('bb497ab4-cf9f-5394-a9e0-c31377ecdf3b', 'b023b4e1-614a-5174-ad7b-b2bffa09afe3', NULL, 29, 29, 'The Spirit said to Philip, "Go near, and join yourself to this chariot."'),
  ('aa713a30-6dc1-5ebd-aa58-fd22983ce893', 'b023b4e1-614a-5174-ad7b-b2bffa09afe3', NULL, 30, 30, 'Philip ran to him, and heard him reading Isaiah the prophet, and said, "Do you understand what you are reading?"'),
  ('e97210c7-3b82-507e-acce-cf521e913a1c', 'b023b4e1-614a-5174-ad7b-b2bffa09afe3', NULL, 31, 31, 'He said, "How can I, unless someone explains it to me?" He begged Philip to come up and sit with him.'),
  ('61116103-03bb-5888-ae11-93708febaeaf', 'b023b4e1-614a-5174-ad7b-b2bffa09afe3', NULL, 32, 32, 'Now the passage of the Scripture which he was reading was this, "He was led as a sheep to the slaughter. As a lamb before his shearer is silent, so he doesn''t open his mouth.'),
  ('251b3777-eabb-5004-ae5e-8501f7acf420', 'b023b4e1-614a-5174-ad7b-b2bffa09afe3', NULL, 33, 33, 'In his humiliation, his judgment was taken away. Who will declare His generation? For his life is taken from the earth."'),
  ('2841bd8b-033e-5eee-a573-88d7475f87c0', 'b023b4e1-614a-5174-ad7b-b2bffa09afe3', NULL, 34, 34, 'The eunuch answered Philip, "Who is the prophet talking about? About himself, or about someone else?"'),
  ('495f0c25-fd5e-5e2b-a14a-9b95af267ea7', 'b023b4e1-614a-5174-ad7b-b2bffa09afe3', NULL, 35, 35, 'Philip opened his mouth, and beginning from this Scripture, preached to him Jesus.'),
  ('f2ec33ef-0c39-52bb-a105-ba73f35379bb', 'b023b4e1-614a-5174-ad7b-b2bffa09afe3', NULL, 36, 36, 'As they went on the way, they came to some water, and the eunuch said, "Behold, here is water. What is keeping me from being baptized?"'),
  ('c7668c40-70f8-5399-a151-9a66af5caf7a', 'b023b4e1-614a-5174-ad7b-b2bffa09afe3', NULL, 37, 37, ''),
  ('2dadeb4a-d5d9-57f6-a683-1aba74be8b6e', 'b023b4e1-614a-5174-ad7b-b2bffa09afe3', NULL, 38, 38, 'He commanded the chariot to stand still, and they both went down into the water, both Philip and the eunuch, and he baptized him.'),
  ('7f5c0986-f111-56af-a413-25cc5a3f6f29', 'b023b4e1-614a-5174-ad7b-b2bffa09afe3', NULL, 39, 39, 'When they came up out of the water, the Spirit of the Lord caught Philip away, and the eunuch didn''t see him any more, for he went on his way rejoicing.'),
  ('9062c523-1159-5d8d-a203-9296dff8d10f', 'b023b4e1-614a-5174-ad7b-b2bffa09afe3', NULL, 40, 40, 'But Philip was found at Azotus. Passing through, he preached the Good News to all the cities, until he came to Caesarea.'),
  ('3bcd7edf-8208-5992-a896-ce4a096254d4', '05e4e26a-c88f-5e37-a62b-ba7638b362d5', NULL, 1, 1, 'But Saul, still breathing threats and slaughter against the disciples of the Lord, went to the high priest,'),
  ('3ee0a4d0-1a6c-574f-a8c1-51b089b6cf9a', '05e4e26a-c88f-5e37-a62b-ba7638b362d5', NULL, 2, 2, 'and asked for letters from him to the synagogues of Damascus, that if he found any who were of the Way, whether men or women, he might bring them bound to Jerusalem.'),
  ('9d3d5ede-7f97-5f8e-a2fb-9db3413eb216', '05e4e26a-c88f-5e37-a62b-ba7638b362d5', NULL, 3, 3, 'As he traveled, it happened that he got close to Damascus, and suddenly a light from the sky shone around him.'),
  ('478492d4-6a77-5bcd-aef9-4d151f762aa8', '05e4e26a-c88f-5e37-a62b-ba7638b362d5', NULL, 4, 4, 'He fell on the earth, and heard a voice saying to him, "Saul, Saul, why do you persecute me?"'),
  ('220f8e7a-7edc-5aea-a4ac-85533f4a89a6', '05e4e26a-c88f-5e37-a62b-ba7638b362d5', NULL, 5, 5, 'He said, "Who are you, Lord?" The Lord said, "I am Jesus, whom you are persecuting.'),
  ('3ac57864-422e-5a65-a2df-2dfc6d701119', '05e4e26a-c88f-5e37-a62b-ba7638b362d5', NULL, 6, 6, 'But rise up, and enter into the city, and you will be told what you must do."'),
  ('134d2f10-49df-5fef-add5-b2d1383ff6ae', '05e4e26a-c88f-5e37-a62b-ba7638b362d5', NULL, 7, 7, 'The men who traveled with him stood speechless, hearing the sound, but seeing no one.'),
  ('ce9a4f55-4e4a-52eb-ae66-26d3b7815b20', '05e4e26a-c88f-5e37-a62b-ba7638b362d5', NULL, 8, 8, 'Saul arose from the ground, and when his eyes were opened, he saw no one. They led him by the hand, and brought him into Damascus.'),
  ('57bf6802-2ce3-5013-aa57-ae0d4e9081fb', '05e4e26a-c88f-5e37-a62b-ba7638b362d5', NULL, 9, 9, 'He was without sight for three days, and neither ate nor drank.'),
  ('9d30779b-35f1-5739-aa3a-0ee4a4951ba0', '05e4e26a-c88f-5e37-a62b-ba7638b362d5', NULL, 10, 10, 'Now there was a certain disciple at Damascus named Ananias. The Lord said to him in a vision, "Ananias!" He said, "Behold, it''s me, Lord."'),
  ('db54e791-86c4-5f22-a6a3-744ddeaa4ed4', '05e4e26a-c88f-5e37-a62b-ba7638b362d5', NULL, 11, 11, 'The Lord said to him, "Arise, and go to the street which is called Straight, and inquire in the house of Judah for one named Saul, a man of Tarsus. For behold, he is praying,'),
  ('2f1ba261-fe2e-5a01-a08c-22c123bacc22', '05e4e26a-c88f-5e37-a62b-ba7638b362d5', NULL, 12, 12, 'and in a vision he has seen a man named Ananias coming in, and laying his hands on him, that he might receive his sight."'),
  ('78edacaf-3366-5277-ae90-d05cb7436eda', '05e4e26a-c88f-5e37-a62b-ba7638b362d5', NULL, 13, 13, 'But Ananias answered, "Lord, I have heard from many about this man, how much evil he did to your saints at Jerusalem.'),
  ('0c74da9d-0fcc-5c1b-aaa9-2bbb68e06aa6', '05e4e26a-c88f-5e37-a62b-ba7638b362d5', NULL, 14, 14, 'Here he has authority from the chief priests to bind all who call on your name."'),
  ('12325ae4-8baf-54c3-a829-fea675b72ed8', '05e4e26a-c88f-5e37-a62b-ba7638b362d5', NULL, 15, 15, 'But the Lord said to him, "Go your way, for he is my chosen vessel to bear my name before the nations and kings, and the children of Israel.'),
  ('9b0ace23-1d78-5c5b-af0a-b1529de6aab1', '05e4e26a-c88f-5e37-a62b-ba7638b362d5', NULL, 16, 16, 'For I will show him how many things he must suffer for my name''s sake."'),
  ('96c6ff4f-1ff3-54f0-a1f0-99e938ebda42', '05e4e26a-c88f-5e37-a62b-ba7638b362d5', NULL, 17, 17, 'Ananias departed, and entered into the house. Laying his hands on him, he said, "Brother Saul, the Lord, who appeared to you on the road by which you came, has sent me, that you may receive your sight, and be filled with the Holy Spirit."'),
  ('89a3cd4e-d9d8-5191-a6de-22083c57ff70', '05e4e26a-c88f-5e37-a62b-ba7638b362d5', NULL, 18, 18, 'Immediately something like scales fell from his eyes, and he received his sight. He arose and was baptized.'),
  ('1a870fdf-1fe9-539a-a3af-37e73a13659e', '05e4e26a-c88f-5e37-a62b-ba7638b362d5', NULL, 19, 19, 'He took food and was strengthened. Saul stayed several days with the disciples who were at Damascus.'),
  ('9595b841-e2c8-5971-ab4d-95450ff8eb04', '05e4e26a-c88f-5e37-a62b-ba7638b362d5', NULL, 20, 20, 'Immediately in the synagogues he proclaimed the Christ, that he is the Son of God.'),
  ('cdea8b77-da33-5a59-a6af-4873155fb65f', '05e4e26a-c88f-5e37-a62b-ba7638b362d5', NULL, 21, 21, 'All who heard him were amazed, and said, "Isn''t this he who in Jerusalem made havoc of those who called on this name? And he had come here intending to bring them bound before the chief priests!"'),
  ('0a23e846-0e8e-5ba3-a5fb-7ef09bb6d7b2', '05e4e26a-c88f-5e37-a62b-ba7638b362d5', NULL, 22, 22, 'But Saul increased more in strength, and confounded the Jews who lived at Damascus, proving that this is the Christ.'),
  ('fbd6d249-4399-52d7-ada2-7080a67ac361', '05e4e26a-c88f-5e37-a62b-ba7638b362d5', NULL, 23, 23, 'When many days were fulfilled, the Jews conspired together to kill him,'),
  ('229767ef-c073-5a5d-a17a-9df1e400495d', '05e4e26a-c88f-5e37-a62b-ba7638b362d5', NULL, 24, 24, 'but their plot became known to Saul. They watched the gates both day and night that they might kill him,'),
  ('d7bd813b-543a-5e48-a85a-5a5abc96a840', '05e4e26a-c88f-5e37-a62b-ba7638b362d5', NULL, 25, 25, 'but his disciples took him by night, and let him down through the wall, lowering him in a basket.'),
  ('644afdd9-9f40-5c4f-a5db-106095f583fd', '05e4e26a-c88f-5e37-a62b-ba7638b362d5', NULL, 26, 26, 'When Saul had come to Jerusalem, he tried to join himself to the disciples; but they were all afraid of him, not believing that he was a disciple.'),
  ('b4d08eb0-d39c-54d1-a083-d496dbde673d', '05e4e26a-c88f-5e37-a62b-ba7638b362d5', NULL, 27, 27, 'But Barnabas took him, and brought him to the apostles, and declared to them how he had seen the Lord in the way, and that he had spoken to him, and how at Damascus he had preached boldly in the name of Jesus.'),
  ('a0dc2cb7-21aa-597d-a034-2242f49e1583', '05e4e26a-c88f-5e37-a62b-ba7638b362d5', NULL, 28, 28, 'He was with them entering into Jerusalem,'),
  ('83168bcd-8fe2-5b33-a0a5-23ccd95fec73', '05e4e26a-c88f-5e37-a62b-ba7638b362d5', NULL, 29, 29, 'preaching boldly in the name of the Lord Jesus. He spoke and disputed against the Hellenists, but they were seeking to kill him.'),
  ('a8c0cd9b-8b83-5617-aa6a-268d4dd5193b', '05e4e26a-c88f-5e37-a62b-ba7638b362d5', NULL, 30, 30, 'When the brothers knew it, they brought him down to Caesarea, and sent him off to Tarsus.'),
  ('3c94bac5-67a4-5268-a4b2-9e4483a026b5', '05e4e26a-c88f-5e37-a62b-ba7638b362d5', NULL, 31, 31, 'So the assemblies throughout all Judea and Galilee and Samaria had peace, and were built up. They were multiplied, walking in the fear of the Lord and in the comfort of the Holy Spirit.'),
  ('f8f620f8-0f0e-5e06-aee4-ef6a0f18f060', '05e4e26a-c88f-5e37-a62b-ba7638b362d5', NULL, 32, 32, 'It happened, as Peter went throughout all those parts, he came down also to the saints who lived at Lydda.'),
  ('a7520514-7a6b-5aa6-a3d4-c576c4f5732c', '05e4e26a-c88f-5e37-a62b-ba7638b362d5', NULL, 33, 33, 'There he found a certain man named Aeneas, who had been bedridden for eight years, because he was paralyzed.'),
  ('a3aeb687-a970-56a6-a358-50bb9868ccb8', '05e4e26a-c88f-5e37-a62b-ba7638b362d5', NULL, 34, 34, 'Peter said to him, "Aeneas, Jesus Christ heals you. Get up and make your bed!" Immediately he arose.'),
  ('d9ffa3b7-682b-5299-a2ff-3e9e03c4988b', '05e4e26a-c88f-5e37-a62b-ba7638b362d5', NULL, 35, 35, 'All who lived at Lydda and in Sharon saw him, and they turned to the Lord.'),
  ('5ec48e46-1d2c-54c6-a163-eba7a7f9d506', '05e4e26a-c88f-5e37-a62b-ba7638b362d5', NULL, 36, 36, 'Now there was at Joppa a certain disciple named Tabitha, which when translated, means Dorcas. This woman was full of good works and acts of mercy which she did.'),
  ('c41b2908-84ba-5cf1-a410-4bf4c85de2e7', '05e4e26a-c88f-5e37-a62b-ba7638b362d5', NULL, 37, 37, 'It happened in those days that she fell sick, and died. When they had washed her, they laid her in an upper room.'),
  ('6ca8c210-0712-5449-a66d-a3f1ff8d7e12', '05e4e26a-c88f-5e37-a62b-ba7638b362d5', NULL, 38, 38, 'As Lydda was near Joppa, the disciples, hearing that Peter was there, sent two men to him, imploring him not to delay in coming to them.'),
  ('1c3f8343-1b85-5fe9-a434-2e7fb8580972', '05e4e26a-c88f-5e37-a62b-ba7638b362d5', NULL, 39, 39, 'Peter got up and went with them. When he had come, they brought him into the upper room. All the widows stood by him weeping, and showing the coats and garments which Dorcas had made while she was with them.'),
  ('e67385ba-128b-5a78-a5c8-2b07ce4589f5', '05e4e26a-c88f-5e37-a62b-ba7638b362d5', NULL, 40, 40, 'Peter put them all out, and kneeled down and prayed. Turning to the body, he said, "Tabitha, get up!" She opened her eyes, and when she saw Peter, she sat up.'),
  ('eaa81850-4e1a-5bf1-a6a6-1264b633074e', '05e4e26a-c88f-5e37-a62b-ba7638b362d5', NULL, 41, 41, 'He gave her his hand, and raised her up. Calling the saints and widows, he presented her alive.'),
  ('ab32d9ee-5618-5bc2-a938-eb9cfa0117bf', '05e4e26a-c88f-5e37-a62b-ba7638b362d5', NULL, 42, 42, 'And it became known throughout all Joppa, and many believed in the Lord.'),
  ('55f68e38-e934-53d9-ab29-25fda60c4751', '05e4e26a-c88f-5e37-a62b-ba7638b362d5', NULL, 43, 43, 'It happened, that he stayed many days in Joppa with one Simon, a tanner.'),
  ('ca9ca819-21a2-5ac0-a668-981326e8e4f9', 'ed199c48-06ea-52ca-a911-401afc8774b5', NULL, 1, 1, 'Now there was a certain man in Caesarea, Cornelius by name, a centurion of what was called the Italian Regiment,'),
  ('6f3554b9-fad8-5fa0-a078-66a5a4f5d959', 'ed199c48-06ea-52ca-a911-401afc8774b5', NULL, 2, 2, 'a devout man, and one who feared God with all his house, who gave gifts for the needy generously to the people, and always prayed to God.'),
  ('1a98cbb5-6a9d-50fd-aeed-f88e3491db05', 'ed199c48-06ea-52ca-a911-401afc8774b5', NULL, 3, 3, 'At about the ninth hour of the day, he clearly saw in a vision an angel of God coming to him, and saying to him, "Cornelius!"'),
  ('940d3e08-9f04-5f32-ad14-019a64f0f96f', 'ed199c48-06ea-52ca-a911-401afc8774b5', NULL, 4, 4, 'He, fastening his eyes on him, and being frightened, said, "What is it, Lord?" He said to him, "Your prayers and your gifts to the needy have gone up for a memorial before God.'),
  ('8b7efa87-cb10-5b04-a0a1-ee26d2924c86', 'ed199c48-06ea-52ca-a911-401afc8774b5', NULL, 5, 5, 'Now send men to Joppa, and get Simon, who is surnamed Peter.'),
  ('08a7ddab-df94-5fd1-af1c-2cba80d044a7', 'ed199c48-06ea-52ca-a911-401afc8774b5', NULL, 6, 6, 'He lodges with one Simon, a tanner, whose house is by the seaside."'),
  ('0a20d1e4-8376-5e36-a628-0c4952394dda', 'ed199c48-06ea-52ca-a911-401afc8774b5', NULL, 7, 7, 'When the angel who spoke to him had departed, Cornelius called two of his household servants and a devout soldier of those who waited on him continually.'),
  ('c02baf60-fb59-566b-a10f-18e4cc1dfac5', 'ed199c48-06ea-52ca-a911-401afc8774b5', NULL, 8, 8, 'Having explained everything to them, he sent them to Joppa.'),
  ('99fe6848-98c0-5157-aa4d-3fdca387ca8d', 'ed199c48-06ea-52ca-a911-401afc8774b5', NULL, 9, 9, 'Now on the next day as they were on their journey, and got close to the city, Peter went up on the housetop to pray at about noon.'),
  ('fe073a23-9a55-5c50-a17e-e4badb4b3a30', 'ed199c48-06ea-52ca-a911-401afc8774b5', NULL, 10, 10, 'He became hungry and desired to eat, but while they were preparing, he fell into a trance.'),
  ('fe188cd9-d672-5eea-a257-5da0de92c15e', 'ed199c48-06ea-52ca-a911-401afc8774b5', NULL, 11, 11, 'He saw heaven opened and a certain container descending to him, like a great sheet let down by four corners on the earth,'),
  ('b33897c6-ea53-5d10-a8c7-a1040dd30a42', 'ed199c48-06ea-52ca-a911-401afc8774b5', NULL, 12, 12, 'in which were all kinds of four-footed animals of the earth, wild animals, reptiles, and birds of the sky.'),
  ('c9cc3e3c-11c4-564f-adb3-34634fdf1d8c', 'ed199c48-06ea-52ca-a911-401afc8774b5', NULL, 13, 13, 'A voice came to him, "Rise, Peter, kill and eat!"'),
  ('208af74c-ded1-5a0d-a1be-1bde1321f74b', 'ed199c48-06ea-52ca-a911-401afc8774b5', NULL, 14, 14, 'But Peter said, "Not so, Lord; for I have never eaten anything that is common or unclean."'),
  ('bac51705-cee2-5a0f-ac8e-7d69eff9ec47', 'ed199c48-06ea-52ca-a911-401afc8774b5', NULL, 15, 15, 'A voice came to him again the second time, "What God has cleansed, you must not call unclean."'),
  ('0c45d54a-ca48-5a32-aabd-75337f4cfb77', 'ed199c48-06ea-52ca-a911-401afc8774b5', NULL, 16, 16, 'This was done three times, and immediately the vessel was received up into heaven.'),
  ('98e0e13f-3091-5bf8-a9a2-8dd52b959876', 'ed199c48-06ea-52ca-a911-401afc8774b5', NULL, 17, 17, 'Now while Peter was very perplexed in himself what the vision which he had seen might mean, behold, the men who were sent by Cornelius, having made inquiry for Simon''s house, stood before the gate,'),
  ('9dc0e870-6363-574c-a05d-e67324174930', 'ed199c48-06ea-52ca-a911-401afc8774b5', NULL, 18, 18, 'and called and asked whether Simon, who was surnamed Peter, was lodging there.'),
  ('7056e919-4798-5f03-a9ea-7efd7224fc6e', 'ed199c48-06ea-52ca-a911-401afc8774b5', NULL, 19, 19, 'While Peter was pondering the vision, the Spirit said to him, "Behold, three men seek you.'),
  ('dc959bd6-57e3-538a-af2b-0c25c1d79cf2', 'ed199c48-06ea-52ca-a911-401afc8774b5', NULL, 20, 20, 'But arise, get down, and go with them, doubting nothing; for I have sent them."'),
  ('556ad6cf-e73a-58ff-a290-7d66dc24e01e', 'ed199c48-06ea-52ca-a911-401afc8774b5', NULL, 21, 21, 'Peter went down to the men, and said, "Behold, I am he whom you seek. Why have you come?"'),
  ('785b7688-f475-5c4f-aca2-2182fd250555', 'ed199c48-06ea-52ca-a911-401afc8774b5', NULL, 22, 22, 'They said, "Cornelius, a centurion, a righteous man and one who fears God, and well spoken of by all the nation of the Jews, was directed by a holy angel to invite you to his house, and to listen to what you say."'),
  ('fbccca5c-f1d4-5a7e-a3f4-2d1454cf701a', 'ed199c48-06ea-52ca-a911-401afc8774b5', NULL, 23, 23, 'So he called them in and lodged them. On the next day Peter arose and went out with them, and some of the brothers from Joppa accompanied him.'),
  ('51b188af-59fc-5a27-aefd-cc2ea0ac5873', 'ed199c48-06ea-52ca-a911-401afc8774b5', NULL, 24, 24, 'On the next day they entered into Caesarea. Cornelius was waiting for them, having called together his relatives and his near friends.'),
  ('a02a7287-6797-5b2e-a401-420d2affe223', 'ed199c48-06ea-52ca-a911-401afc8774b5', NULL, 25, 25, 'When it happened that Peter entered, Cornelius met him, fell down at his feet, and worshiped him.'),
  ('c960fd61-a37f-5400-a539-995ecc751570', 'ed199c48-06ea-52ca-a911-401afc8774b5', NULL, 26, 26, 'But Peter raised him up, saying, "Stand up! I myself am also a man."'),
  ('cf4942cb-af79-5040-ad62-0582c611a7d0', 'ed199c48-06ea-52ca-a911-401afc8774b5', NULL, 27, 27, 'As he talked with him, he went in and found many gathered together.'),
  ('7611db13-995b-5c1a-a198-d41388fe992f', 'ed199c48-06ea-52ca-a911-401afc8774b5', NULL, 28, 28, 'He said to them, "You yourselves know how it is an unlawful thing for a man who is a Jew to join himself or come to one of another nation, but God has shown me that I shouldn''t call any man unholy or unclean.'),
  ('2ceb2c21-067d-50de-a4dd-edf6cd648e39', 'ed199c48-06ea-52ca-a911-401afc8774b5', NULL, 29, 29, 'Therefore also I came without complaint when I was sent for. I ask therefore, why did you send for me?"'),
  ('7ea50c0d-ffa0-58bc-a249-75bd08968ad3', 'ed199c48-06ea-52ca-a911-401afc8774b5', NULL, 30, 30, 'Cornelius said, "Four days ago, I was fasting until this hour, and at the ninth hour, I prayed in my house, and behold, a man stood before me in bright clothing,'),
  ('c9bc97b6-6d2c-5955-a329-2ad90499881c', 'ed199c48-06ea-52ca-a911-401afc8774b5', NULL, 31, 31, 'and said, ''Cornelius, your prayer is heard, and your gifts to the needy are remembered in the sight of God.'),
  ('25ff21db-6228-58a6-ae1c-98d4e8b77af0', 'ed199c48-06ea-52ca-a911-401afc8774b5', NULL, 32, 32, 'Send therefore to Joppa, and summon Simon, who is surnamed Peter. He lodges in the house of Simon a tanner, by the seaside. When he comes, he will speak to you.'''),
  ('a9f47421-91e3-59a0-aa3e-d2b1ee2ed167', 'ed199c48-06ea-52ca-a911-401afc8774b5', NULL, 33, 33, 'Therefore I sent to you at once, and it was good of you to come. Now therefore we are all here present in the sight of God to hear all things that have been commanded you by God."'),
  ('05eab81c-6c6b-5db5-a380-e98ac6e548c3', 'ed199c48-06ea-52ca-a911-401afc8774b5', NULL, 34, 34, 'Peter opened his mouth and said, "Truly I perceive that God doesn''t show favoritism;'),
  ('c0ce7c38-7f51-590e-a2db-868318cc41a1', 'ed199c48-06ea-52ca-a911-401afc8774b5', NULL, 35, 35, 'but in every nation he who fears him and works righteousness is acceptable to him.'),
  ('42be4e3e-bfb2-598d-ab28-af0db034b4bc', 'ed199c48-06ea-52ca-a911-401afc8774b5', NULL, 36, 36, 'The word which he sent to the children of Israel, preaching good news of peace by Jesus Christ--he is Lord of all--'),
  ('eaf7f346-464a-5b71-afc2-267285a7145d', 'ed199c48-06ea-52ca-a911-401afc8774b5', NULL, 37, 37, 'you yourselves know what happened, which was proclaimed throughout all Judea, beginning from Galilee, after the baptism which John preached;'),
  ('cccfe34f-e5c9-5769-a979-4807aa4e3e89', 'ed199c48-06ea-52ca-a911-401afc8774b5', NULL, 38, 38, 'even Jesus of Nazareth, how God anointed him with the Holy Spirit and with power, who went about doing good and healing all who were oppressed by the devil, for God was with him.'),
  ('71e6b114-2c90-5356-abbe-f61f615c4507', 'ed199c48-06ea-52ca-a911-401afc8774b5', NULL, 39, 39, 'We are witnesses of everything he did both in the country of the Jews, and in Jerusalem; whom they also killed, hanging him on a tree.'),
  ('f65c6107-5bfb-5e6d-aa6a-5858f02eda49', 'ed199c48-06ea-52ca-a911-401afc8774b5', NULL, 40, 40, 'God raised him up the third day, and gave him to be revealed,'),
  ('d0428b52-48f0-58a0-ac64-23b59bceae47', 'ed199c48-06ea-52ca-a911-401afc8774b5', NULL, 41, 41, 'not to all the people, but to witnesses who were chosen before by God, to us, who ate and drank with him after he rose from the dead.'),
  ('22fa165a-8c9d-571c-ab49-607e08896e52', 'ed199c48-06ea-52ca-a911-401afc8774b5', NULL, 42, 42, 'He commanded us to preach to the people and to testify that this is he who is appointed by God as the Judge of the living and the dead.'),
  ('0f57634b-bba1-512a-a18b-8ca8bb348035', 'ed199c48-06ea-52ca-a911-401afc8774b5', NULL, 43, 43, 'All the prophets testify about him, that through his name everyone who believes in him will receive remission of sins."'),
  ('c8f43f82-0cb7-5487-acb6-568c7a4b9740', 'ed199c48-06ea-52ca-a911-401afc8774b5', NULL, 44, 44, 'While Peter was still speaking these words, the Holy Spirit fell on all those who heard the word.'),
  ('97e9bd9a-f5c0-52ab-a2e8-f226a3029cb7', 'ed199c48-06ea-52ca-a911-401afc8774b5', NULL, 45, 45, 'They of the circumcision who believed were amazed, as many as came with Peter, because the gift of the Holy Spirit was also poured out on the Gentiles.'),
  ('e6e9b6f9-b229-5356-a542-e049e40fa03c', 'ed199c48-06ea-52ca-a911-401afc8774b5', NULL, 46, 46, 'For they heard them speaking in other languages and magnifying God. Then Peter answered,'),
  ('7ba5c5b7-0968-5ee9-a577-54a0de8f8245', 'ed199c48-06ea-52ca-a911-401afc8774b5', NULL, 47, 47, '"Can any man forbid the water, that these who have received the Holy Spirit as well as we should not be baptized?"'),
  ('99913b4e-b0c6-5bd2-a09f-7ce16335d226', 'ed199c48-06ea-52ca-a911-401afc8774b5', NULL, 48, 48, 'He commanded them to be baptized in the name of Jesus Christ. Then they asked him to stay some days.'),
  ('428f6b03-8891-5832-a67d-d3a4728fd1a7', '1cf32a1b-fa52-59fd-acde-d669ee35e8a1', NULL, 1, 1, 'Now the apostles and the brothers who were in Judea heard that the Gentiles had also received the word of God.'),
  ('f7cfee75-d4b6-5ba0-a2d7-aaaf96be3a8e', '1cf32a1b-fa52-59fd-acde-d669ee35e8a1', NULL, 2, 2, 'When Peter had come up to Jerusalem, those who were of the circumcision contended with him,'),
  ('e2d86569-b07c-5d40-ab72-bcbf1d60c71b', '1cf32a1b-fa52-59fd-acde-d669ee35e8a1', NULL, 3, 3, 'saying, "You went in to uncircumcised men, and ate with them!"'),
  ('ef5a2dee-c8db-56d3-a2a5-1834cce82b95', '1cf32a1b-fa52-59fd-acde-d669ee35e8a1', NULL, 4, 4, 'But Peter began, and explained to them in order, saying,'),
  ('fba2508a-93bd-5a67-a24a-e824968fd1ee', '1cf32a1b-fa52-59fd-acde-d669ee35e8a1', NULL, 5, 5, '"I was in the city of Joppa praying, and in a trance I saw a vision: a certain container descending, like it was a great sheet let down from heaven by four corners. It came as far as me.'),
  ('3b9fd3bf-8d26-5aa8-aee6-2523c2cd59b3', '1cf32a1b-fa52-59fd-acde-d669ee35e8a1', NULL, 6, 6, 'When I had looked intently at it, I considered, and saw the four-footed animals of the earth, wild animals, creeping things, and birds of the sky.'),
  ('14def2d3-89dc-55bc-a245-2c1faf5e1726', '1cf32a1b-fa52-59fd-acde-d669ee35e8a1', NULL, 7, 7, 'I also heard a voice saying to me, ''Rise, Peter, kill and eat!'''),
  ('e3c664f4-6cad-5c7e-ac21-fb99549da02d', '1cf32a1b-fa52-59fd-acde-d669ee35e8a1', NULL, 8, 8, 'But I said, ''Not so, Lord, for nothing unholy or unclean has ever entered into my mouth.'''),
  ('1629061e-bfc1-5223-aa33-45a9618c8c33', '1cf32a1b-fa52-59fd-acde-d669ee35e8a1', NULL, 9, 9, 'But a voice answered me the second time out of heaven, ''What God has cleansed, don''t you call unclean.'''),
  ('e04769ac-9f41-5d42-af66-fa8be1950904', '1cf32a1b-fa52-59fd-acde-d669ee35e8a1', NULL, 10, 10, 'This was done three times, and all were drawn up again into heaven.'),
  ('062fd210-1608-5ae9-a2cb-ae485a8fd5fc', '1cf32a1b-fa52-59fd-acde-d669ee35e8a1', NULL, 11, 11, 'Behold, immediately three men stood before the house where I was, having been sent from Caesarea to me.'),
  ('dbbe074e-818f-51f2-af52-6a799cd3c09a', '1cf32a1b-fa52-59fd-acde-d669ee35e8a1', NULL, 12, 12, 'The Spirit told me to go with them, without discriminating. These six brothers also accompanied me, and we entered into the man''s house.'),
  ('2069b5ae-eef8-5fbd-a967-059801809e40', '1cf32a1b-fa52-59fd-acde-d669ee35e8a1', NULL, 13, 13, 'He told us how he had seen the angel standing in his house, and saying to him, ''Send to Joppa, and get Simon, whose surname is Peter,'),
  ('c2cea796-7ff3-5cf6-a4fe-1456fd94b25e', '1cf32a1b-fa52-59fd-acde-d669ee35e8a1', NULL, 14, 14, 'who will speak to you words by which you will be saved, you and all your house.'''),
  ('136ac73f-c41a-5eee-a59b-4d28e041e4d8', '1cf32a1b-fa52-59fd-acde-d669ee35e8a1', NULL, 15, 15, 'As I began to speak, the Holy Spirit fell on them, even as on us at the beginning.'),
  ('f63f1ef9-1cd8-5984-a438-546c51b507ce', '1cf32a1b-fa52-59fd-acde-d669ee35e8a1', NULL, 16, 16, 'I remembered the word of the Lord, how he said, ''John indeed baptized in water, but you will be baptized in the Holy Spirit.'''),
  ('c59f9704-7f76-52fb-ad1f-5dcfc8dd47b6', '1cf32a1b-fa52-59fd-acde-d669ee35e8a1', NULL, 17, 17, 'If then God gave to them the same gift as us, when we believed in the Lord Jesus Christ, who was I, that I could withstand God?"'),
  ('a43e4c0b-0bef-5fd6-a05b-03c093ad8467', '1cf32a1b-fa52-59fd-acde-d669ee35e8a1', NULL, 18, 18, 'When they heard these things, they held their peace, and glorified God, saying, "Then God has also granted to the Gentiles repentance to life!"'),
  ('7ff1acb4-9c8b-54ce-a1f2-28a423f123c3', '1cf32a1b-fa52-59fd-acde-d669ee35e8a1', NULL, 19, 19, 'They therefore who were scattered abroad by the oppression that arose about Stephen traveled as far as Phoenicia, Cyprus, and Antioch, speaking the word to no one except to Jews only.'),
  ('fce0eb12-ff5c-5333-a0e6-fb52ef966c6b', '1cf32a1b-fa52-59fd-acde-d669ee35e8a1', NULL, 20, 20, 'But there were some of them, men of Cyprus and Cyrene, who, when they had come to Antioch, spoke to the Hellenists, preaching the Lord Jesus.'),
  ('206054c8-fd2a-5c0f-af53-d7a6500922d9', '1cf32a1b-fa52-59fd-acde-d669ee35e8a1', NULL, 21, 21, 'The hand of the Lord was with them, and a great number believed and turned to the Lord.'),
  ('b4117e08-9124-560c-a9b5-79309d1b2bf5', '1cf32a1b-fa52-59fd-acde-d669ee35e8a1', NULL, 22, 22, 'The report concerning them came to the ears of the assembly which was in Jerusalem. They sent out Barnabas to go as far as Antioch,'),
  ('76c6133d-2a5c-5bba-aaa1-bd1b91b6b770', '1cf32a1b-fa52-59fd-acde-d669ee35e8a1', NULL, 23, 23, 'who, when he had come, and had seen the grace of God, was glad. He exhorted them all, that with purpose of heart they should remain near to the Lord.'),
  ('7f7d01b7-c47a-5135-ad23-7e1e44300c2a', '1cf32a1b-fa52-59fd-acde-d669ee35e8a1', NULL, 24, 24, 'For he was a good man, and full of the Holy Spirit and of faith, and many people were added to the Lord.'),
  ('2d40e221-1687-5c77-af34-34b7afed2b18', '1cf32a1b-fa52-59fd-acde-d669ee35e8a1', NULL, 25, 25, 'Barnabas went out to Tarsus to look for Saul.'),
  ('a3af204f-0b96-5390-a23b-343eba517df9', '1cf32a1b-fa52-59fd-acde-d669ee35e8a1', NULL, 26, 26, 'When he had found him, he brought him to Antioch. It happened, that for a whole year they were gathered together with the assembly, and taught many people. The disciples were first called Christians in Antioch.'),
  ('93fa0813-cfea-577e-aebe-090d9cbf27b4', '1cf32a1b-fa52-59fd-acde-d669ee35e8a1', NULL, 27, 27, 'Now in these days, prophets came down from Jerusalem to Antioch.'),
  ('06a7aad0-f40f-50fe-a7c4-790aa6d35ff7', '1cf32a1b-fa52-59fd-acde-d669ee35e8a1', NULL, 28, 28, 'One of them named Agabus stood up, and indicated by the Spirit that there should be a great famine all over the world, which also happened in the days of Claudius.'),
  ('0b2f12b2-58d5-5e2b-a4e0-27f1b14590df', '1cf32a1b-fa52-59fd-acde-d669ee35e8a1', NULL, 29, 29, 'As any of the disciples had plenty, each determined to send relief to the brothers who lived in Judea;'),
  ('36b5f069-cafd-5658-a2ec-b1ad1f9d95c0', '1cf32a1b-fa52-59fd-acde-d669ee35e8a1', NULL, 30, 30, 'which they also did, sending it to the elders by the hands of Barnabas and Saul.'),
  ('10978496-4f38-5707-a4fc-2a1d334278bc', '7a5f28d7-b415-529c-a36d-bfc5b4e2b19b', NULL, 1, 1, 'Now about that time, King Herod stretched out his hands to oppress some of the assembly.'),
  ('d67bb7f3-e75d-5c74-af94-a52944c2cc4a', '7a5f28d7-b415-529c-a36d-bfc5b4e2b19b', NULL, 2, 2, 'He killed James, the brother of John, with the sword.'),
  ('b184081a-4e25-564d-a1d9-ad95f5e8601a', '7a5f28d7-b415-529c-a36d-bfc5b4e2b19b', NULL, 3, 3, 'When he saw that it pleased the Jews, he proceeded to seize Peter also. This was during the days of unleavened bread.'),
  ('5c24913d-b7ce-5fdb-a0bb-a84d2ff9daf8', '7a5f28d7-b415-529c-a36d-bfc5b4e2b19b', NULL, 4, 4, 'When he had arrested him, he put him in prison, and delivered him to four squads of four soldiers each to guard him, intending to bring him out to the people after the Passover.'),
  ('cc2bfeb8-d171-5f06-a437-939fc96716a6', '7a5f28d7-b415-529c-a36d-bfc5b4e2b19b', NULL, 5, 5, 'Peter therefore was kept in the prison, but constant prayer was made by the assembly to God for him.'),
  ('5ae6626f-29e6-5c99-adfd-d29fe2683498', '7a5f28d7-b415-529c-a36d-bfc5b4e2b19b', NULL, 6, 6, 'The same night when Herod was about to bring him out, Peter was sleeping between two soldiers, bound with two chains. Guards in front of the door kept the prison.'),
  ('fc14ed69-4afe-54e2-a752-ede446c1dcb1', '7a5f28d7-b415-529c-a36d-bfc5b4e2b19b', NULL, 7, 7, 'And behold, an angel of the Lord stood by him, and a light shone in the cell. He struck Peter on the side, and woke him up, saying, "Stand up quickly!" His chains fell off from his hands.'),
  ('ea4d9eab-8aae-51ce-acaa-fb4ae9e7836c', '7a5f28d7-b415-529c-a36d-bfc5b4e2b19b', NULL, 8, 8, 'The angel said to him, "Get dressed and put on your sandals." He did so. He said to him, "Put on your cloak, and follow me."'),
  ('092441da-6b17-5aac-a5b2-81e4e6be940a', '7a5f28d7-b415-529c-a36d-bfc5b4e2b19b', NULL, 9, 9, 'And he went out and followed him. He didn''t know that what was being done by the angel was real, but thought he saw a vision.'),
  ('d5615cbd-7188-54bc-afc6-e2158f7cecdb', '7a5f28d7-b415-529c-a36d-bfc5b4e2b19b', NULL, 10, 10, 'When they were past the first and the second guard, they came to the iron gate that leads into the city, which opened to them by itself. They went out, and went down one street, and immediately the angel departed from him.'),
  ('b0d7f103-bd67-5ac1-a22f-d7e5f45bfa3f', '7a5f28d7-b415-529c-a36d-bfc5b4e2b19b', NULL, 11, 11, 'When Peter had come to himself, he said, "Now I truly know that the Lord has sent out his angel and delivered me out of the hand of Herod, and from everything the Jewish people were expecting."'),
  ('992db168-d0e3-55e9-aa9e-37c3cf962731', '7a5f28d7-b415-529c-a36d-bfc5b4e2b19b', NULL, 12, 12, 'Thinking about that, he came to the house of Mary, the mother of John whose surname was Mark, where many were gathered together and were praying.'),
  ('ed21b6da-e184-55d8-a811-09c222b28cbf', '7a5f28d7-b415-529c-a36d-bfc5b4e2b19b', NULL, 13, 13, 'When Peter knocked at the door of the gate, a maid named Rhoda came to answer.'),
  ('019dd9c9-281d-540a-a432-d465769dcb9e', '7a5f28d7-b415-529c-a36d-bfc5b4e2b19b', NULL, 14, 14, 'When she recognized Peter''s voice, she didn''t open the gate for joy, but ran in, and reported that Peter was standing in front of the gate.'),
  ('ff388dbb-d31a-5b10-aedc-7c447b713d53', '7a5f28d7-b415-529c-a36d-bfc5b4e2b19b', NULL, 15, 15, 'They said to her, "You are crazy!" But she insisted that it was so. They said, "It is his angel."'),
  ('09886863-3759-595a-ac98-c4301ff94fb3', '7a5f28d7-b415-529c-a36d-bfc5b4e2b19b', NULL, 16, 16, 'But Peter continued knocking. When they had opened, they saw him, and were amazed.'),
  ('93d2fdd3-ff76-5c1d-aaf4-70cb8837ad1f', '7a5f28d7-b415-529c-a36d-bfc5b4e2b19b', NULL, 17, 17, 'But he, beckoning to them with his hand to be silent, declared to them how the Lord had brought him out of the prison. He said, "Tell these things to James, and to the brothers." Then he departed, and went to another place.'),
  ('c5cabe69-059b-552d-ac2f-82e66f5be32a', '7a5f28d7-b415-529c-a36d-bfc5b4e2b19b', NULL, 18, 18, 'Now as soon as it was day, there was no small stir among the soldiers about what had become of Peter.'),
  ('3ccf8748-7e82-5ae4-a07f-cf108bd7ef87', '7a5f28d7-b415-529c-a36d-bfc5b4e2b19b', NULL, 19, 19, 'When Herod had sought for him, and didn''t find him, he examined the guards, and commanded that they should be put to death. He went down from Judea to Caesarea, and stayed there.'),
  ('65c6ed41-5b4f-5193-a82d-68d791c0c8ca', '7a5f28d7-b415-529c-a36d-bfc5b4e2b19b', NULL, 20, 20, 'Now Herod was very angry with the people of Tyre and Sidon. They came with one accord to him, and, having made Blastus, the king''s personal aide, their friend, they asked for peace, because their country depended on the king''s country for food.'),
  ('cdf9c561-12a9-5e9f-a5e4-d12e3ae856f5', '7a5f28d7-b415-529c-a36d-bfc5b4e2b19b', NULL, 21, 21, 'On an appointed day, Herod dressed himself in royal clothing, sat on the throne, and gave a speech to them.'),
  ('3d838665-503f-517e-a6e2-6d10bdec1024', '7a5f28d7-b415-529c-a36d-bfc5b4e2b19b', NULL, 22, 22, 'The people shouted, "The voice of a god, and not of a man!"'),
  ('316ab0cb-0859-5a14-a054-5eebc7f07757', '7a5f28d7-b415-529c-a36d-bfc5b4e2b19b', NULL, 23, 23, 'Immediately an angel of the Lord struck him, because he didn''t give God the glory, and he was eaten by worms and died.')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('8809a455-ca80-5f8b-a576-ceb4e677d6e4', '7a5f28d7-b415-529c-a36d-bfc5b4e2b19b', NULL, 24, 24, 'But the word of God grew and multiplied.'),
  ('8cc5d154-80ae-5ee8-a78f-b2fd5f36c642', '7a5f28d7-b415-529c-a36d-bfc5b4e2b19b', NULL, 25, 25, 'Barnabas and Saul returned to Jerusalem, when they had fulfilled their service, also taking with them John whose surname was Mark.'),
  ('cf4703f1-2d33-5ed7-ae96-0d09f023d50f', '80acabf0-1c18-5cd1-a06d-20bde77e9a3d', NULL, 1, 1, 'Now in the assembly that was at Antioch there were some prophets and teachers: Barnabas, Simeon who was called Niger, Lucius of Cyrene, Manaen the foster brother of Herod the tetrarch, and Saul.'),
  ('4e43ae17-8dd1-54cc-a7c4-7a137228d442', '80acabf0-1c18-5cd1-a06d-20bde77e9a3d', NULL, 2, 2, 'As they served the Lord and fasted, the Holy Spirit said, "Separate Barnabas and Saul for me, for the work to which I have called them."'),
  ('4df7e6c7-afe8-5896-a65d-60284dc5a674', '80acabf0-1c18-5cd1-a06d-20bde77e9a3d', NULL, 3, 3, 'Then, when they had fasted and prayed and laid their hands on them, they sent them away.'),
  ('5b24322c-1a82-5326-a276-2b4c638112bc', '80acabf0-1c18-5cd1-a06d-20bde77e9a3d', NULL, 4, 4, 'So, being sent out by the Holy Spirit, they went down to Seleucia. From there they sailed to Cyprus.'),
  ('34992350-ee10-5a5b-a55e-622de1d2cab5', '80acabf0-1c18-5cd1-a06d-20bde77e9a3d', NULL, 5, 5, 'When they were at Salamis, they proclaimed the word of God in the Jewish synagogues. They had also John as their attendant.'),
  ('610657c3-08fc-54a1-a356-438a10fcb069', '80acabf0-1c18-5cd1-a06d-20bde77e9a3d', NULL, 6, 6, 'When they had gone through the island to Paphos, they found a certain sorcerer, a false prophet, a Jew, whose name was Bar Jesus,'),
  ('3a435b8e-c4de-5f12-a13a-8c56f8b4716a', '80acabf0-1c18-5cd1-a06d-20bde77e9a3d', NULL, 7, 7, 'who was with the proconsul, Sergius Paulus, a man of understanding. This man summoned Barnabas and Saul, and sought to hear the word of God.'),
  ('d3990499-b1d0-5248-aac5-63fdd11123ad', '80acabf0-1c18-5cd1-a06d-20bde77e9a3d', NULL, 8, 8, 'But Elymas the sorcerer (for so is his name by interpretation) withstood them, seeking to turn aside the proconsul from the faith.'),
  ('986df585-ec24-55c7-aa77-30a4801c9bb9', '80acabf0-1c18-5cd1-a06d-20bde77e9a3d', NULL, 9, 9, 'But Saul, who is also called Paul, filled with the Holy Spirit, fastened his eyes on him,'),
  ('99d697cf-5fbd-5b77-a59a-f9817b01a365', '80acabf0-1c18-5cd1-a06d-20bde77e9a3d', NULL, 10, 10, 'and said, "Full of all deceit and all cunning, you son of the devil, you enemy of all righteousness, will you not cease to pervert the right ways of the Lord?'),
  ('b1a2771e-7e8a-5073-a5f8-e9e64dbf2f36', '80acabf0-1c18-5cd1-a06d-20bde77e9a3d', NULL, 11, 11, 'Now, behold, the hand of the Lord is on you, and you will be blind, not seeing the sun for a season!" Immediately a mist and darkness fell on him. He went around seeking someone to lead him by the hand.'),
  ('0f79b0bf-505f-5bb0-a82a-afa3124e68a0', '80acabf0-1c18-5cd1-a06d-20bde77e9a3d', NULL, 12, 12, 'Then the proconsul, when he saw what was done, believed, being astonished at the teaching of the Lord.'),
  ('f33ff0a4-7ef0-5960-a792-fd366a5357a6', '80acabf0-1c18-5cd1-a06d-20bde77e9a3d', NULL, 13, 13, 'Now Paul and his company set sail from Paphos, and came to Perga in Pamphylia. John departed from them and returned to Jerusalem.'),
  ('a3cf513a-8220-5eba-a12e-260128d62b8b', '80acabf0-1c18-5cd1-a06d-20bde77e9a3d', NULL, 14, 14, 'But they, passing on from Perga, came to Antioch of Pisidia. They went into the synagogue on the Sabbath day, and sat down.'),
  ('80a4ce5e-da3b-54f9-a6f0-b463eeeedb0f', '80acabf0-1c18-5cd1-a06d-20bde77e9a3d', NULL, 15, 15, 'After the reading of the law and the prophets, the rulers of the synagogue sent to them, saying, "Brothers, if you have any word of exhortation for the people, speak."'),
  ('4658dd4b-dd09-5a53-ad28-5a26bf298c96', '80acabf0-1c18-5cd1-a06d-20bde77e9a3d', NULL, 16, 16, 'Paul stood up, and beckoning with his hand said, "Men of Israel, and you who fear God, listen.'),
  ('70c0ba40-0f67-512b-a6ab-e1ab17429710', '80acabf0-1c18-5cd1-a06d-20bde77e9a3d', NULL, 17, 17, 'The God of this people chose our fathers, and exalted the people when they stayed as aliens in the land of Egypt, and with an uplifted arm, he led them out of it.'),
  ('d824797b-8238-5da9-aed6-56809b122d85', '80acabf0-1c18-5cd1-a06d-20bde77e9a3d', NULL, 18, 18, 'For a period of about forty years he put up with them in the wilderness.'),
  ('514e1149-b7b6-5638-a4b4-9974fb45dcca', '80acabf0-1c18-5cd1-a06d-20bde77e9a3d', NULL, 19, 19, 'When he had destroyed seven nations in the land of Canaan, he gave them their land for an inheritance, for about four hundred fifty years.'),
  ('ba074b5d-4bcb-5929-ae07-b99beb8f55bb', '80acabf0-1c18-5cd1-a06d-20bde77e9a3d', NULL, 20, 20, 'After these things he gave them judges until Samuel the prophet.'),
  ('383a6a07-af71-5f85-adc8-857f9fc2a238', '80acabf0-1c18-5cd1-a06d-20bde77e9a3d', NULL, 21, 21, 'Afterward they asked for a king, and God gave to them Saul the son of Kish, a man of the tribe of Benjamin, for forty years.'),
  ('0ecde965-fa16-5349-adcc-693d89544020', '80acabf0-1c18-5cd1-a06d-20bde77e9a3d', NULL, 22, 22, 'When he had removed him, he raised up David to be their king, to whom he also testified, ''I have found David the son of Jesse, a man after my heart, who will do all my will.'''),
  ('6e60cf90-941e-57b4-a6fc-5fc97c88b1d3', '80acabf0-1c18-5cd1-a06d-20bde77e9a3d', NULL, 23, 23, 'From this man''s seed, God has brought salvation to Israel according to his promise,'),
  ('cf15c2a4-fe09-5bff-a09b-ed91573bd573', '80acabf0-1c18-5cd1-a06d-20bde77e9a3d', NULL, 24, 24, 'before his coming, when John had first preached the baptism of repentance to Israel.'),
  ('6f0565bc-76cf-5170-a696-2cd0dc1c388d', '80acabf0-1c18-5cd1-a06d-20bde77e9a3d', NULL, 25, 25, 'As John was fulfilling his course, he said, ''What do you suppose that I am? I am not he. But behold, one comes after me the sandals of whose feet I am not worthy to untie.'''),
  ('27f215fc-df53-5afb-a036-b49161d07005', '80acabf0-1c18-5cd1-a06d-20bde77e9a3d', NULL, 26, 26, 'Brothers, children of the stock of Abraham, and those among you who fear God, the word of this salvation is sent out to you.'),
  ('eea00eec-09de-573d-abbc-49b6b732c4a4', '80acabf0-1c18-5cd1-a06d-20bde77e9a3d', NULL, 27, 27, 'For those who dwell in Jerusalem, and their rulers, because they didn''t know him, nor the voices of the prophets which are read every Sabbath, fulfilled them by condemning him.'),
  ('ab814bdb-3fae-5353-a6de-bac18aeaa902', '80acabf0-1c18-5cd1-a06d-20bde77e9a3d', NULL, 28, 28, 'Though they found no cause for death, they still asked Pilate to have him killed.'),
  ('568e1f5f-d0a2-5f39-a005-1cc859cd1c79', '80acabf0-1c18-5cd1-a06d-20bde77e9a3d', NULL, 29, 29, 'When they had fulfilled all things that were written about him, they took him down from the tree, and laid him in a tomb.'),
  ('2af553ac-8e5b-56ba-af61-9132401214a6', '80acabf0-1c18-5cd1-a06d-20bde77e9a3d', NULL, 30, 30, 'But God raised him from the dead,'),
  ('470f59db-ce3b-5d47-a022-c231db26ba1d', '80acabf0-1c18-5cd1-a06d-20bde77e9a3d', NULL, 31, 31, 'and he was seen for many days by those who came up with him from Galilee to Jerusalem, who are his witnesses to the people.'),
  ('7e0c0037-48ef-5b14-ad43-02783ae2483b', '80acabf0-1c18-5cd1-a06d-20bde77e9a3d', NULL, 32, 32, 'We bring you good news of the promise made to the fathers,'),
  ('2055e449-0efe-599c-a467-a054694b2aa4', '80acabf0-1c18-5cd1-a06d-20bde77e9a3d', NULL, 33, 33, 'that God has fulfilled the same to us, their children, in that he raised up Jesus. As it is also written in the second psalm, ''You are my Son. Today I have become your father.'''),
  ('5d347d7a-9985-53c8-a0ef-66a12c4d59b1', '80acabf0-1c18-5cd1-a06d-20bde77e9a3d', NULL, 34, 34, '"Concerning that he raised him up from the dead, now no more to return to corruption, he has spoken thus: ''I will give you the holy and sure blessings of David.'''),
  ('79ba711b-786f-5d16-a75b-baccbbaf8abc', '80acabf0-1c18-5cd1-a06d-20bde77e9a3d', NULL, 35, 35, 'Therefore he says also in another psalm, ''You will not allow your Holy One to see decay.'''),
  ('02e8aed9-1c15-5689-ad2b-0899660b594c', '80acabf0-1c18-5cd1-a06d-20bde77e9a3d', NULL, 36, 36, 'For David, after he had in his own generation served the counsel of God, fell asleep, and was laid with his fathers, and saw decay.'),
  ('e0bab075-94b9-5883-aa7d-954591f5b13b', '80acabf0-1c18-5cd1-a06d-20bde77e9a3d', NULL, 37, 37, 'But he whom God raised up saw no decay.'),
  ('44d5213b-3928-542d-aca4-a2c1d6744ed3', '80acabf0-1c18-5cd1-a06d-20bde77e9a3d', NULL, 38, 38, 'Be it known to you therefore, brothers, that through this man is proclaimed to you remission of sins,'),
  ('7fade00b-3971-5166-a4cd-451269ecc195', '80acabf0-1c18-5cd1-a06d-20bde77e9a3d', NULL, 39, 39, 'and by him everyone who believes is justified from all things, from which you could not be justified by the law of Moses.'),
  ('05a40952-b208-5298-ab0a-3c301b2d909c', '80acabf0-1c18-5cd1-a06d-20bde77e9a3d', NULL, 40, 40, 'Beware therefore, lest that come on you which is spoken in the prophets:'),
  ('eec02682-eb9a-5a1a-a158-ae52edd66b41', '80acabf0-1c18-5cd1-a06d-20bde77e9a3d', NULL, 41, 41, '''Behold, you scoffers, and wonder, and perish; for I work a work in your days, a work which you will in no way believe, if one declares it to you.''"'),
  ('0417542e-d0b8-5a6b-a968-4de77b77b6b1', '80acabf0-1c18-5cd1-a06d-20bde77e9a3d', NULL, 42, 42, 'So when the Jews went out of the synagogue, the Gentiles begged that these words might be preached to them the next Sabbath.'),
  ('a508c536-2d16-57bd-aaa4-6e915d336387', '80acabf0-1c18-5cd1-a06d-20bde77e9a3d', NULL, 43, 43, 'Now when the synagogue broke up, many of the Jews and of the devout proselytes followed Paul and Barnabas; who, speaking to them, urged them to continue in the grace of God.'),
  ('d3a29179-8d0f-5730-a842-e566623cb657', '80acabf0-1c18-5cd1-a06d-20bde77e9a3d', NULL, 44, 44, 'The next Sabbath almost the whole city was gathered together to hear the word of God.'),
  ('fcd61fe9-f9c4-5fa4-a1a0-a8fb1f4a0a7f', '80acabf0-1c18-5cd1-a06d-20bde77e9a3d', NULL, 45, 45, 'But when the Jews saw the multitudes, they were filled with jealousy, and contradicted the things which were spoken by Paul, and blasphemed.'),
  ('e31fa386-004f-5905-a5c2-44f5278a2e28', '80acabf0-1c18-5cd1-a06d-20bde77e9a3d', NULL, 46, 46, 'Paul and Barnabas spoke out boldly, and said, "It was necessary that God''s word should be spoken to you first. Since indeed you thrust it from you, and judge yourselves unworthy of eternal life, behold, we turn to the Gentiles.'),
  ('304c90bf-e9dd-5801-ae06-8bb912c47e13', '80acabf0-1c18-5cd1-a06d-20bde77e9a3d', NULL, 47, 47, 'For so has the Lord commanded us, saying, ''I have set you as a light for the Gentiles, that you should bring salvation to the uttermost parts of the earth.''"'),
  ('7c640c79-d451-55ab-a132-e4041cf99bfb', '80acabf0-1c18-5cd1-a06d-20bde77e9a3d', NULL, 48, 48, 'As the Gentiles heard this, they were glad, and glorified the word of God. As many as were appointed to eternal life believed.'),
  ('fdfb005f-87b0-51c1-a03e-35cd20219b0d', '80acabf0-1c18-5cd1-a06d-20bde77e9a3d', NULL, 49, 49, 'The Lord''s word was spread abroad throughout all the region.'),
  ('b8c7a3c9-53e5-52a8-ab01-8879abeec15b', '80acabf0-1c18-5cd1-a06d-20bde77e9a3d', NULL, 50, 50, 'But the Jews stirred up the devout and prominent women and the chief men of the city, and stirred up a persecution against Paul and Barnabas, and threw them out of their borders.'),
  ('b00ee0c7-1049-5c55-a2a8-2eb75f4f429c', '80acabf0-1c18-5cd1-a06d-20bde77e9a3d', NULL, 51, 51, 'But they shook off the dust of their feet against them, and came to Iconium.'),
  ('6b28e062-edad-5e10-a5d3-357a8102e945', '80acabf0-1c18-5cd1-a06d-20bde77e9a3d', NULL, 52, 52, 'The disciples were filled with joy with the Holy Spirit.'),
  ('9afb6649-070f-5f2d-a54f-a99b65861752', '5a9613b7-7724-5d1c-a034-c2a132ced99a', NULL, 1, 1, 'It happened in Iconium that they entered together into the synagogue of the Jews, and so spoke that a great multitude both of Jews and of Greeks believed.'),
  ('fc2aa6ea-8e47-5b9d-a6b8-953380d62618', '5a9613b7-7724-5d1c-a034-c2a132ced99a', NULL, 2, 2, 'But the disbelieving Jews stirred up and embittered the souls of the Gentiles against the brothers.'),
  ('11c27aef-0f48-5ad2-ab2e-b65d435f48a6', '5a9613b7-7724-5d1c-a034-c2a132ced99a', NULL, 3, 3, 'Therefore they stayed there a long time, speaking boldly in the Lord, who testified to the word of his grace, granting signs and wonders to be done by their hands.'),
  ('20d1cd67-e234-5ae6-a92a-d2b4302b4bd2', '5a9613b7-7724-5d1c-a034-c2a132ced99a', NULL, 4, 4, 'But the multitude of the city was divided. Part sided with the Jews, and part with the apostles.'),
  ('42475d49-922b-508d-ae0d-43cdc8459e42', '5a9613b7-7724-5d1c-a034-c2a132ced99a', NULL, 5, 5, 'When some of both the Gentiles and the Jews, with their rulers, made a violent attempt to mistreat and stone them,'),
  ('0d8c5638-0782-5fb0-a749-b1933d4b2f4f', '5a9613b7-7724-5d1c-a034-c2a132ced99a', NULL, 6, 6, 'they became aware of it, and fled to the cities of Lycaonia, Lystra, Derbe, and the surrounding region.'),
  ('7f70e90b-d0b1-5e51-a55d-a50eca9c4e60', '5a9613b7-7724-5d1c-a034-c2a132ced99a', NULL, 7, 7, 'There they preached the Good News.'),
  ('c02c5166-24a1-5d07-a3b6-9ae33f287b60', '5a9613b7-7724-5d1c-a034-c2a132ced99a', NULL, 8, 8, 'At Lystra a certain man sat, impotent in his feet, a cripple from his mother''s womb, who never had walked.'),
  ('01f7a154-6b5a-5f3d-a5d6-3064cf5ed887', '5a9613b7-7724-5d1c-a034-c2a132ced99a', NULL, 9, 9, 'He was listening to Paul speaking, who, fastening eyes on him, and seeing that he had faith to be made whole,'),
  ('0ea21a4a-97e2-58dd-ad61-a24349328ae2', '5a9613b7-7724-5d1c-a034-c2a132ced99a', NULL, 10, 10, 'said with a loud voice, "Stand upright on your feet!" He leaped up and walked.'),
  ('71dc3624-a290-5795-a0c9-c7adecbb8ef1', '5a9613b7-7724-5d1c-a034-c2a132ced99a', NULL, 11, 11, 'When the multitude saw what Paul had done, they lifted up their voice, saying in the language of Lycaonia, "The gods have come down to us in the likeness of men!"'),
  ('34250794-5a7f-5624-a27a-fd0250a22aac', '5a9613b7-7724-5d1c-a034-c2a132ced99a', NULL, 12, 12, 'They called Barnabas "Jupiter," and Paul "Mercury," because he was the chief speaker.'),
  ('6d3f2929-6f99-5e54-a136-17274ac80b71', '5a9613b7-7724-5d1c-a034-c2a132ced99a', NULL, 13, 13, 'The priest of Jupiter, whose temple was in front of their city, brought oxen and garlands to the gates, and would have made a sacrifice along with the multitudes.'),
  ('49ded217-074d-552d-a0c4-8bdc56e2449e', '5a9613b7-7724-5d1c-a034-c2a132ced99a', NULL, 14, 14, 'But when the apostles, Barnabas and Paul, heard of it, they tore their clothes, and sprang into the multitude, crying out,'),
  ('43cbe5fe-0a45-551d-a1b5-765829308664', '5a9613b7-7724-5d1c-a034-c2a132ced99a', NULL, 15, 15, '"Men, why are you doing these things? We also are men of like passions with you, and bring you good news, that you should turn from these vain things to the living God, who made the sky and the earth and the sea, and all that is in them;'),
  ('a6b5b015-a1c3-5ada-ae06-c09481d211e4', '5a9613b7-7724-5d1c-a034-c2a132ced99a', NULL, 16, 16, 'who in the generations gone by allowed all the nations to walk in their own ways.'),
  ('c8c54a18-e04f-53d7-a81a-da5bcc913fa3', '5a9613b7-7724-5d1c-a034-c2a132ced99a', NULL, 17, 17, 'Yet he didn''t leave himself without witness, in that he did good and gave you rains from the sky and fruitful seasons, filling our hearts with food and gladness."'),
  ('cbd832cc-45e8-56dc-a1d3-d5bc54860ab6', '5a9613b7-7724-5d1c-a034-c2a132ced99a', NULL, 18, 18, 'Even saying these things, they hardly stopped the multitudes from making a sacrifice to them.'),
  ('d0f858c4-4ec0-574d-a57f-ee332fff4483', '5a9613b7-7724-5d1c-a034-c2a132ced99a', NULL, 19, 19, 'But some Jews from Antioch and Iconium came there, and having persuaded the multitudes, they stoned Paul, and dragged him out of the city, supposing that he was dead.'),
  ('c0d4b832-7733-5b63-a047-2a039adbe784', '5a9613b7-7724-5d1c-a034-c2a132ced99a', NULL, 20, 20, 'But as the disciples stood around him, he rose up, and entered into the city. On the next day he went out with Barnabas to Derbe.'),
  ('38d46479-5d07-56a6-ae5d-6a974a31b8f6', '5a9613b7-7724-5d1c-a034-c2a132ced99a', NULL, 21, 21, 'When they had preached the Good News to that city, and had made many disciples, they returned to Lystra, Iconium, and Antioch,'),
  ('15d874c0-3f2f-5407-a050-76a125e1670a', '5a9613b7-7724-5d1c-a034-c2a132ced99a', NULL, 22, 22, 'confirming the souls of the disciples, exhorting them to continue in the faith, and that through many afflictions we must enter into the Kingdom of God.'),
  ('4f1130f9-0743-5f6f-ac5c-bbe24f28e863', '5a9613b7-7724-5d1c-a034-c2a132ced99a', NULL, 23, 23, 'When they had appointed elders for them in every assembly, and had prayed with fasting, they commended them to the Lord, on whom they had believed.'),
  ('625259cf-4d56-5dc9-a809-9c789a3c2b20', '5a9613b7-7724-5d1c-a034-c2a132ced99a', NULL, 24, 24, 'They passed through Pisidia, and came to Pamphylia.'),
  ('0b98a59b-3b57-55b7-a3be-d13437027f31', '5a9613b7-7724-5d1c-a034-c2a132ced99a', NULL, 25, 25, 'When they had spoken the word in Perga, they went down to Attalia.'),
  ('fea6e03e-dbd8-5733-ad50-047875acb9ab', '5a9613b7-7724-5d1c-a034-c2a132ced99a', NULL, 26, 26, 'From there they sailed to Antioch, from where they had been committed to the grace of God for the work which they had fulfilled.'),
  ('c4ccc60c-685c-57ac-ad43-459edc943f10', '5a9613b7-7724-5d1c-a034-c2a132ced99a', NULL, 27, 27, 'When they had arrived, and had gathered the assembly together, they reported all the things that God had done with them, and that he had opened a door of faith to the nations.'),
  ('776dbca2-1956-542b-a88b-8a12e2942539', '5a9613b7-7724-5d1c-a034-c2a132ced99a', NULL, 28, 28, 'They stayed there with the disciples for a long time.'),
  ('8077a32c-acb8-519c-a03b-ead30dc4f963', 'ff392a60-d5ec-56ab-a00b-2b689972f508', NULL, 1, 1, 'Some men came down from Judea and taught the brothers, "Unless you are circumcised after the custom of Moses, you can''t be saved."'),
  ('535462fd-fba5-5c84-ad7d-7622ddffac5a', 'ff392a60-d5ec-56ab-a00b-2b689972f508', NULL, 2, 2, 'Therefore when Paul and Barnabas had no small discord and discussion with them, they appointed Paul and Barnabas, and some others of them, to go up to Jerusalem to the apostles and elders about this question.'),
  ('3b05579e-9600-54a9-a70d-0f3fdc51f692', 'ff392a60-d5ec-56ab-a00b-2b689972f508', NULL, 3, 3, 'They, being sent on their way by the assembly, passed through both Phoenicia and Samaria, declaring the conversion of the Gentiles. They caused great joy to all the brothers.'),
  ('ec5d26da-10b6-5aa2-a0e0-def2abd81b09', 'ff392a60-d5ec-56ab-a00b-2b689972f508', NULL, 4, 4, 'When they had come to Jerusalem, they were received by the assembly and the apostles and the elders, and they reported all things that God had done with them.'),
  ('f2b8b936-e32e-5cd3-a273-c8d21d871978', 'ff392a60-d5ec-56ab-a00b-2b689972f508', NULL, 5, 5, 'But some of the sect of the Pharisees who believed rose up, saying, "It is necessary to circumcise them, and to command them to keep the law of Moses."'),
  ('593eb8dc-afb5-5d83-ad8a-2f86ef4879c5', 'ff392a60-d5ec-56ab-a00b-2b689972f508', NULL, 6, 6, 'The apostles and the elders were gathered together to see about this matter.'),
  ('46398965-f085-5218-ade7-97ca0b30e7cc', 'ff392a60-d5ec-56ab-a00b-2b689972f508', NULL, 7, 7, 'When there had been much discussion, Peter rose up and said to them, "Brothers, you know that a good while ago God made a choice among you, that by my mouth the nations should hear the word of the Good News, and believe.'),
  ('2fe0b787-e900-54ed-a162-5d504891732f', 'ff392a60-d5ec-56ab-a00b-2b689972f508', NULL, 8, 8, 'God, who knows the heart, testified about them, giving them the Holy Spirit, just like he did to us.'),
  ('13091611-ba15-5b8f-a476-ebd87f926b33', 'ff392a60-d5ec-56ab-a00b-2b689972f508', NULL, 9, 9, 'He made no distinction between us and them, cleansing their hearts by faith.'),
  ('18e092f5-1900-5d6e-a513-1d138cb9fba9', 'ff392a60-d5ec-56ab-a00b-2b689972f508', NULL, 10, 10, 'Now therefore why do you tempt God, that you should put a yoke on the neck of the disciples which neither our fathers nor we were able to bear?'),
  ('186f237d-9002-53cc-aa04-aea2180a7ff5', 'ff392a60-d5ec-56ab-a00b-2b689972f508', NULL, 11, 11, 'But we believe that we are saved through the grace of the Lord Jesus, just as they are."'),
  ('7e1d8680-b415-5ec2-ab7a-7d92556336e3', 'ff392a60-d5ec-56ab-a00b-2b689972f508', NULL, 12, 12, 'All the multitude kept silence, and they listened to Barnabas and Paul reporting what signs and wonders God had done among the nations through them.'),
  ('d7ed263c-2123-5b96-ad30-eb5f8cb14b5d', 'ff392a60-d5ec-56ab-a00b-2b689972f508', NULL, 13, 13, 'After they were silent, James answered, "Brothers, listen to me.'),
  ('cb2f9cbf-1628-520b-ae4f-d0eb96d7aa8e', 'ff392a60-d5ec-56ab-a00b-2b689972f508', NULL, 14, 14, 'Simeon has reported how God first visited the nations, to take out of them a people for his name.'),
  ('5654f7d7-541a-5eb9-ada8-526ade7f06e4', 'ff392a60-d5ec-56ab-a00b-2b689972f508', NULL, 15, 15, 'This agrees with the words of the prophets. As it is written,'),
  ('9da6f7d9-0a1a-5ead-a448-c9d04cc5af5c', 'ff392a60-d5ec-56ab-a00b-2b689972f508', NULL, 16, 16, '''After these things I will return. I will again build the tabernacle of David, which has fallen. I will again build its ruins. I will set it up,'),
  ('2d462cdb-ebdd-5c67-ad54-c252a44ca9be', 'ff392a60-d5ec-56ab-a00b-2b689972f508', NULL, 17, 17, 'That the rest of men may seek after the Lord; All the Gentiles who are called by my name, Says the Lord, who does all these things.'),
  ('5ee43ebf-0be7-50be-ab1a-7d1cdec32d11', 'ff392a60-d5ec-56ab-a00b-2b689972f508', NULL, 18, 18, 'All his works are known to God from eternity.'''),
  ('1b90fff3-9d1f-540b-aaa1-9a6c02804129', 'ff392a60-d5ec-56ab-a00b-2b689972f508', NULL, 19, 19, '"Therefore my judgment is that we don''t trouble those from among the Gentiles who turn to God,'),
  ('2aaf0fac-3312-5bde-a4db-a67e2d05686c', 'ff392a60-d5ec-56ab-a00b-2b689972f508', NULL, 20, 20, 'but that we write to them that they abstain from the pollution of idols, from sexual immorality, from what is strangled, and from blood.'),
  ('624354a5-3258-59e1-adf7-5888108e046d', 'ff392a60-d5ec-56ab-a00b-2b689972f508', NULL, 21, 21, 'For Moses from generations of old has in every city those who preach him, being read in the synagogues every Sabbath."'),
  ('6241a767-7c37-574e-a7be-dd2786f941cf', 'ff392a60-d5ec-56ab-a00b-2b689972f508', NULL, 22, 22, 'Then it seemed good to the apostles and the elders, with the whole assembly, to choose men out of their company, and send them to Antioch with Paul and Barnabas: Judas called Barsabbas, and Silas, chief men among the brothers.'),
  ('21ecc2c5-3fc6-5f1a-a51c-d6065c80f0cf', 'ff392a60-d5ec-56ab-a00b-2b689972f508', NULL, 23, 23, 'They wrote these things by their hand: "The apostles, the elders, and the brothers, to the brothers who are of the Gentiles in Antioch, Syria, and Cilicia: greetings.'),
  ('d41f1d13-cf83-504e-a2c2-33ef1daa772d', 'ff392a60-d5ec-56ab-a00b-2b689972f508', NULL, 24, 24, 'Because we have heard that some who went out from us have troubled you with words, unsettling your souls, saying, ''You must be circumcised and keep the law,'' to whom we gave no commandment;'),
  ('03fb415a-f7c3-5e50-a23b-262f48dfa836', 'ff392a60-d5ec-56ab-a00b-2b689972f508', NULL, 25, 25, 'it seemed good to us, having come to one accord, to choose out men and send them to you with our beloved Barnabas and Paul,'),
  ('cdd05e74-8a5c-55c5-a643-27757f1f4e06', 'ff392a60-d5ec-56ab-a00b-2b689972f508', NULL, 26, 26, 'men who have risked their lives for the name of our Lord Jesus Christ.'),
  ('fb87dac5-cef5-536e-a9ad-92db2dcb50d1', 'ff392a60-d5ec-56ab-a00b-2b689972f508', NULL, 27, 27, 'We have sent therefore Judas and Silas, who themselves will also tell you the same things by word of mouth.'),
  ('6a0b71b8-335a-5194-a8b7-b8913c6174dd', 'ff392a60-d5ec-56ab-a00b-2b689972f508', NULL, 28, 28, 'For it seemed good to the Holy Spirit, and to us, to lay no greater burden on you than these necessary things:'),
  ('339efaf8-caff-5153-acba-392e409683c1', 'ff392a60-d5ec-56ab-a00b-2b689972f508', NULL, 29, 29, 'that you abstain from things sacrificed to idols, from blood, from things strangled, and from sexual immorality, from which if you keep yourselves, it will be well with you. Farewell."'),
  ('ec1f4058-2eeb-5db5-aaf3-df28bc383eee', 'ff392a60-d5ec-56ab-a00b-2b689972f508', NULL, 30, 30, 'So, when they were sent off, they came to Antioch. Having gathered the multitude together, they delivered the letter.'),
  ('a2a20dad-6d17-5238-abb1-cba70f0e826b', 'ff392a60-d5ec-56ab-a00b-2b689972f508', NULL, 31, 31, 'When they had read it, they rejoiced over the encouragement.'),
  ('3ba498a3-fd52-5882-ac32-8f66eca3e961', 'ff392a60-d5ec-56ab-a00b-2b689972f508', NULL, 32, 32, 'Judas and Silas, also being prophets themselves, encouraged the brothers with many words, and strengthened them.'),
  ('bc33b303-84d6-5b02-a5e7-607f04967602', 'ff392a60-d5ec-56ab-a00b-2b689972f508', NULL, 33, 33, 'After they had spent some time there, they were sent back with greetings from the brothers to the apostles.'),
  ('93401dfc-9ff9-5b59-aee1-e628b346c837', 'ff392a60-d5ec-56ab-a00b-2b689972f508', NULL, 34, 34, ''),
  ('9b474148-fb66-593b-addc-7e8efc150cf8', 'ff392a60-d5ec-56ab-a00b-2b689972f508', NULL, 35, 35, 'But Paul and Barnabas stayed in Antioch, teaching and preaching the word of the Lord, with many others also.'),
  ('088c0259-e7fe-51a8-ac79-2e6dd9045a5c', 'ff392a60-d5ec-56ab-a00b-2b689972f508', NULL, 36, 36, 'After some days Paul said to Barnabas, "Let''s return now and visit our brothers in every city in which we proclaimed the word of the Lord, to see how they are doing."'),
  ('ad83dbf5-67cf-5c82-ac40-d5253372bf42', 'ff392a60-d5ec-56ab-a00b-2b689972f508', NULL, 37, 37, 'Barnabas planned to take John, who was called Mark, with them also.'),
  ('a5f64716-3e01-58a3-a6df-c9f9059c26a2', 'ff392a60-d5ec-56ab-a00b-2b689972f508', NULL, 38, 38, 'But Paul didn''t think that it was a good idea to take with them someone who had withdrawn from them in Pamphylia, and didn''t go with them to do the work.'),
  ('c8701e49-5377-5536-ab6b-aa5fc7d71817', 'ff392a60-d5ec-56ab-a00b-2b689972f508', NULL, 39, 39, 'Then the contention grew so sharp that they separated from each other. Barnabas took Mark with him, and sailed away to Cyprus,'),
  ('35a3d951-e8d3-5150-a246-66e4b549ae7c', 'ff392a60-d5ec-56ab-a00b-2b689972f508', NULL, 40, 40, 'but Paul chose Silas, and went out, being commended by the brothers to the grace of God.'),
  ('71c132e5-c90b-5d54-a50e-dd960225a88a', 'ff392a60-d5ec-56ab-a00b-2b689972f508', NULL, 41, 41, 'He went through Syria and Cilicia, strengthening the assemblies.'),
  ('27ae4e38-9ff9-55dd-a9ad-e6869eb51b4d', 'f91e8390-b2dd-52a3-a104-bbf97cdfd788', NULL, 1, 1, 'He came to Derbe and Lystra: and behold, a certain disciple was there, named Timothy, the son of a Jewess who believed; but his father was a Greek.'),
  ('04ca1ce8-e4a8-51d5-adae-361920a1bed1', 'f91e8390-b2dd-52a3-a104-bbf97cdfd788', NULL, 2, 2, 'The brothers who were at Lystra and Iconium gave a good testimony about him.'),
  ('0e8a5dd9-c9e5-54d4-a0ea-0605ecea6943', 'f91e8390-b2dd-52a3-a104-bbf97cdfd788', NULL, 3, 3, 'Paul wanted to have him go out with him, and he took and circumcised him because of the Jews who were in those parts; for they all knew that his father was a Greek.'),
  ('deb0ef81-2cc4-5c21-a876-b59a03121ac5', 'f91e8390-b2dd-52a3-a104-bbf97cdfd788', NULL, 4, 4, 'As they went on their way through the cities, they delivered the decrees to them to keep which had been ordained by the apostles and elders who were at Jerusalem.'),
  ('75bdc3f2-7bed-5d71-a4c5-cc1ad10792c3', 'f91e8390-b2dd-52a3-a104-bbf97cdfd788', NULL, 5, 5, 'So the assemblies were strengthened in the faith, and increased in number daily.'),
  ('55fa4b00-f1c0-5e49-ad67-7920afaf1a24', 'f91e8390-b2dd-52a3-a104-bbf97cdfd788', NULL, 6, 6, 'When they had gone through the region of Phrygia and Galatia, they were forbidden by the Holy Spirit to speak the word in Asia.'),
  ('2edb77c4-1e61-5968-a1d2-7fe79c643956', 'f91e8390-b2dd-52a3-a104-bbf97cdfd788', NULL, 7, 7, 'When they had come opposite Mysia, they tried to go into Bithynia, but the Spirit didn''t allow them.'),
  ('81af9ce2-f92c-5b56-a7ad-f9eb882dc42e', 'f91e8390-b2dd-52a3-a104-bbf97cdfd788', NULL, 8, 8, 'Passing by Mysia, they came down to Troas.'),
  ('6523c2fe-d459-533b-a4c6-7122e968671a', 'f91e8390-b2dd-52a3-a104-bbf97cdfd788', NULL, 9, 9, 'A vision appeared to Paul in the night. There was a man of Macedonia standing, begging him, and saying, "Come over into Macedonia and help us."'),
  ('64e73497-f5eb-5e81-a797-4abaaa9fdc99', 'f91e8390-b2dd-52a3-a104-bbf97cdfd788', NULL, 10, 10, 'When he had seen the vision, immediately we sought to go out to Macedonia, concluding that the Lord had called us to preach the Good News to them.'),
  ('6052f7a9-58a4-59f5-a75f-f1ebc3a038df', 'f91e8390-b2dd-52a3-a104-bbf97cdfd788', NULL, 11, 11, 'Setting sail therefore from Troas, we made a straight course to Samothrace, and the day following to Neapolis;'),
  ('01a8c9ca-82aa-50df-a6ba-ef407a6fa046', 'f91e8390-b2dd-52a3-a104-bbf97cdfd788', NULL, 12, 12, 'and from there to Philippi, which is a city of Macedonia, the foremost of the district, a Roman colony. We were staying some days in this city.'),
  ('6bf922c1-60c1-578d-a78c-6d41a6134acd', 'f91e8390-b2dd-52a3-a104-bbf97cdfd788', NULL, 13, 13, 'On the Sabbath day we went forth outside of the city by a riverside, where we supposed there was a place of prayer, and we sat down, and spoke to the women who had come together.'),
  ('af58c5a8-226b-5946-a0b9-fa6198788e9d', 'f91e8390-b2dd-52a3-a104-bbf97cdfd788', NULL, 14, 14, 'A certain woman named Lydia, a seller of purple, of the city of Thyatira, one who worshiped God, heard us; whose heart the Lord opened to listen to the things which were spoken by Paul.'),
  ('c56a2df9-b6a2-5332-a4fb-5a9e21274504', 'f91e8390-b2dd-52a3-a104-bbf97cdfd788', NULL, 15, 15, 'When she and her household were baptized, she begged us, saying, "If you have judged me to be faithful to the Lord, come into my house, and stay." So she persuaded us.'),
  ('2e5d3c21-da91-5540-a2f0-6a304774bffa', 'f91e8390-b2dd-52a3-a104-bbf97cdfd788', NULL, 16, 16, 'It happened, as we were going to prayer, that a certain girl having a spirit of divination met us, who brought her masters much gain by fortune telling.'),
  ('22c1e7de-0fa1-5dc0-afc4-a3b70036777c', 'f91e8390-b2dd-52a3-a104-bbf97cdfd788', NULL, 17, 17, 'Following Paul and us, she cried out, "These men are servants of the Most High God, who proclaim to us a way of salvation!"'),
  ('a7c51fb4-b162-5ce5-ad4d-024a860bfaf2', 'f91e8390-b2dd-52a3-a104-bbf97cdfd788', NULL, 18, 18, 'She was doing this for many days. But Paul, becoming greatly annoyed, turned and said to the spirit, "I command you in the name of Jesus Christ to come out of her!" It came out that very hour.'),
  ('ea48adfb-dec2-5f5e-ac5d-f564bd1eb191', 'f91e8390-b2dd-52a3-a104-bbf97cdfd788', NULL, 19, 19, 'But when her masters saw that the hope of their gain was gone, they seized Paul and Silas, and dragged them into the marketplace before the rulers.'),
  ('5f74c66c-c4de-5c31-a6f8-9a6b8f8b77d4', 'f91e8390-b2dd-52a3-a104-bbf97cdfd788', NULL, 20, 20, 'When they had brought them to the magistrates, they said, "These men, being Jews, are agitating our city,'),
  ('d63c0bd7-4363-5a66-a95b-103f2db316ca', 'f91e8390-b2dd-52a3-a104-bbf97cdfd788', NULL, 21, 21, 'and set forth customs which it is not lawful for us to accept or to observe, being Romans."'),
  ('bb5b67c3-d43e-54e7-a22b-37c8c3ccbb6e', 'f91e8390-b2dd-52a3-a104-bbf97cdfd788', NULL, 22, 22, 'The multitude rose up together against them, and the magistrates tore their clothes off of them, and commanded them to be beaten with rods.'),
  ('45c491bc-a53d-585a-a66a-51a78631ed93', 'f91e8390-b2dd-52a3-a104-bbf97cdfd788', NULL, 23, 23, 'When they had laid many stripes on them, they threw them into prison, charging the jailer to keep them safely,'),
  ('13224f4b-bbed-5bc6-af26-24d027f70060', 'f91e8390-b2dd-52a3-a104-bbf97cdfd788', NULL, 24, 24, 'who, having received such a command, threw them into the inner prison, and secured their feet in the stocks.'),
  ('23789adb-d823-54d5-ac98-71090e620b72', 'f91e8390-b2dd-52a3-a104-bbf97cdfd788', NULL, 25, 25, 'But about midnight Paul and Silas were praying and singing hymns to God, and the prisoners were listening to them.'),
  ('0bd500c7-c3ff-506a-a8a7-a95ae462d817', 'f91e8390-b2dd-52a3-a104-bbf97cdfd788', NULL, 26, 26, 'Suddenly there was a great earthquake, so that the foundations of the prison were shaken; and immediately all the doors were opened, and everyone''s bonds were loosened.'),
  ('8f3276bb-4cf5-5225-a89a-5206c134880b', 'f91e8390-b2dd-52a3-a104-bbf97cdfd788', NULL, 27, 27, 'The jailer, being roused out of sleep and seeing the prison doors open, drew his sword and was about to kill himself, supposing that the prisoners had escaped.'),
  ('bfdc8c55-ee0d-5d66-aa9c-189ccfdf7257', 'f91e8390-b2dd-52a3-a104-bbf97cdfd788', NULL, 28, 28, 'But Paul cried with a loud voice, saying, "Don''t harm yourself, for we are all here!"'),
  ('43dc71b4-94e0-5173-ac46-1ecc68a736c1', 'f91e8390-b2dd-52a3-a104-bbf97cdfd788', NULL, 29, 29, 'He called for lights and sprang in, and, fell down trembling before Paul and Silas,'),
  ('a6a492c8-fc77-5f1a-a8c2-450f3934c5cc', 'f91e8390-b2dd-52a3-a104-bbf97cdfd788', NULL, 30, 30, 'and brought them out and said, "Sirs, what must I do to be saved?"'),
  ('162f8581-2701-5f2c-a2d6-0103d6ec8409', 'f91e8390-b2dd-52a3-a104-bbf97cdfd788', NULL, 31, 31, 'They said, "Believe in the Lord Jesus Christ, and you will be saved, you and your household."'),
  ('fb7f3b39-ac68-5482-ae81-eb9a049ac1d1', 'f91e8390-b2dd-52a3-a104-bbf97cdfd788', NULL, 32, 32, 'They spoke the word of the Lord to him, and to all who were in his house.'),
  ('b4aa7d23-5dc6-50e0-a8fb-1e191a6b8df0', 'f91e8390-b2dd-52a3-a104-bbf97cdfd788', NULL, 33, 33, 'He took them the same hour of the night, and washed their stripes, and was immediately baptized, he and all his household.'),
  ('5a6eb518-dbbf-5cf8-a9ba-ce3fb9408fca', 'f91e8390-b2dd-52a3-a104-bbf97cdfd788', NULL, 34, 34, 'He brought them up into his house, and set food before them, and rejoiced greatly, with all his household, having believed in God.'),
  ('f613e504-5db2-5dda-abfc-45b1d15c9e98', 'f91e8390-b2dd-52a3-a104-bbf97cdfd788', NULL, 35, 35, 'But when it was day, the magistrates sent the sergeants, saying, "Let those men go."'),
  ('788df5d1-58b2-5b88-a814-a7ff62b8696c', 'f91e8390-b2dd-52a3-a104-bbf97cdfd788', NULL, 36, 36, 'The jailer reported these words to Paul, saying, "The magistrates have sent to let you go; now therefore come out, and go in peace."'),
  ('ebc6c354-f092-53ba-a944-aa6c81de9000', 'f91e8390-b2dd-52a3-a104-bbf97cdfd788', NULL, 37, 37, 'But Paul said to them, "They have beaten us publicly, without a trial, men who are Romans, and have cast us into prison! Do they now release us secretly? No, most certainly, but let them come themselves and bring us out!"'),
  ('4d8d8c23-6804-506d-ab55-cc0f4f14d06a', 'f91e8390-b2dd-52a3-a104-bbf97cdfd788', NULL, 38, 38, 'The sergeants reported these words to the magistrates, and they were afraid when they heard that they were Romans,'),
  ('a5e8f066-b1bd-5bee-ade5-24dfb76e78b9', 'f91e8390-b2dd-52a3-a104-bbf97cdfd788', NULL, 39, 39, 'and they came and begged them. When they had brought them out, they asked them to depart from the city.'),
  ('5b7ad630-0caa-574b-aa18-7fc25f6acfbf', 'f91e8390-b2dd-52a3-a104-bbf97cdfd788', NULL, 40, 40, 'They went out of the prison, and entered into Lydia''s house. When they had seen the brothers, they encouraged them, and departed.'),
  ('f2b4bbc0-98c3-53e7-a4b0-ee2ce353e663', '05931b1e-e388-5cb6-a8bd-c2d516374055', NULL, 1, 1, 'Now when they had passed through Amphipolis and Apollonia, they came to Thessalonica, where there was a Jewish synagogue.'),
  ('a98b7871-1c7a-5ae4-a810-5c274ed4e330', '05931b1e-e388-5cb6-a8bd-c2d516374055', NULL, 2, 2, 'Paul, as was his custom, went in to them, and for three Sabbath days reasoned with them from the Scriptures,'),
  ('1f9f044f-7b0b-533a-af7e-204ce316038a', '05931b1e-e388-5cb6-a8bd-c2d516374055', NULL, 3, 3, 'explaining and demonstrating that the Christ had to suffer and rise again from the dead, and saying, "This Jesus, whom I proclaim to you, is the Christ."'),
  ('ad7e4b01-01b3-546a-ab0a-da3fa91b5ceb', '05931b1e-e388-5cb6-a8bd-c2d516374055', NULL, 4, 4, 'Some of them were persuaded, and joined Paul and Silas, of the devout Greeks a great multitude, and not a few of the chief women.'),
  ('b0c30b48-12f4-5b20-a54c-913ec0ee418f', '05931b1e-e388-5cb6-a8bd-c2d516374055', NULL, 5, 5, 'But the unpersuaded Jews took along some wicked men from the marketplace, and gathering a crowd, set the city in an uproar. Assaulting the house of Jason, they sought to bring them out to the people.'),
  ('3032ffc1-8f4a-5381-a6d3-0153bece08bf', '05931b1e-e388-5cb6-a8bd-c2d516374055', NULL, 6, 6, 'When they didn''t find them, they dragged Jason and certain brothers before the rulers of the city, crying, "These who have turned the world upside down have come here also,'),
  ('b33171b5-5c14-5ab0-a68c-8639b6c45113', '05931b1e-e388-5cb6-a8bd-c2d516374055', NULL, 7, 7, 'whom Jason has received. These all act contrary to the decrees of Caesar, saying that there is another king, Jesus!"'),
  ('a88eb670-926e-5162-a7a0-23d70a2f4577', '05931b1e-e388-5cb6-a8bd-c2d516374055', NULL, 8, 8, 'The multitude and the rulers of the city were troubled when they heard these things.'),
  ('354ff299-f8ba-5130-ad02-5f98b29d2dc5', '05931b1e-e388-5cb6-a8bd-c2d516374055', NULL, 9, 9, 'When they had taken security from Jason and the rest, they let them go.'),
  ('a60be6ca-067d-5fd8-aae9-9ff085e17159', '05931b1e-e388-5cb6-a8bd-c2d516374055', NULL, 10, 10, 'The brothers immediately sent Paul and Silas away by night to Beroea. When they arrived, they went into the Jewish synagogue.'),
  ('3219026c-a243-5074-a81c-78d147b43af3', '05931b1e-e388-5cb6-a8bd-c2d516374055', NULL, 11, 11, 'Now these were more noble than those in Thessalonica, in that they received the word with all readiness of the mind, examining the Scriptures daily to see whether these things were so.'),
  ('60472c38-2683-54c0-a6a3-26593e265176', '05931b1e-e388-5cb6-a8bd-c2d516374055', NULL, 12, 12, 'Many of them therefore believed; also of the prominent Greek women, and not a few men.'),
  ('788d3913-494c-5ac9-ad65-fd65d77ec3ee', '05931b1e-e388-5cb6-a8bd-c2d516374055', NULL, 13, 13, 'But when the Jews of Thessalonica had knowledge that the word of God was proclaimed by Paul at Beroea also, they came there likewise, agitating the multitudes.'),
  ('3b5f7a61-7214-5284-acad-a196c030baa8', '05931b1e-e388-5cb6-a8bd-c2d516374055', NULL, 14, 14, 'Then the brothers immediately sent out Paul to go as far as to the sea, and Silas and Timothy still stayed there.'),
  ('4e41eae0-5ce6-5766-acf8-d6ea2d4ea196', '05931b1e-e388-5cb6-a8bd-c2d516374055', NULL, 15, 15, 'But those who escorted Paul brought him as far as Athens. Receiving a commandment to Silas and Timothy that they should come to him very quickly, they departed.'),
  ('12f5050d-7bcc-5b7d-a3f5-df79b520ffbf', '05931b1e-e388-5cb6-a8bd-c2d516374055', NULL, 16, 16, 'Now while Paul waited for them at Athens, his spirit was provoked within him as he saw the city full of idols.'),
  ('97cdded6-0bfa-599c-a380-e2d143bc962f', '05931b1e-e388-5cb6-a8bd-c2d516374055', NULL, 17, 17, 'So he reasoned in the synagogue with the Jews and the devout persons, and in the marketplace every day with those who met him.'),
  ('336e788e-3280-5afe-ac7d-ed5ccf19609a', '05931b1e-e388-5cb6-a8bd-c2d516374055', NULL, 18, 18, 'Some of the Epicurean and Stoic philosophers also were conversing with him. Some said, "What does this babbler want to say?" Others said, "He seems to be advocating foreign deities," because he preached Jesus and the resurrection.'),
  ('bc5bc291-3899-58d1-a454-78101944ba90', '05931b1e-e388-5cb6-a8bd-c2d516374055', NULL, 19, 19, 'They took hold of him, and brought him to the Areopagus, saying, "May we know what this new teaching is, which is spoken by you?'),
  ('d58b7311-3b91-5399-af05-f9444cec81e6', '05931b1e-e388-5cb6-a8bd-c2d516374055', NULL, 20, 20, 'For you bring certain strange things to our ears. We want to know therefore what these things mean."'),
  ('8fbf9eb4-0de9-542b-a379-595e7d9c371f', '05931b1e-e388-5cb6-a8bd-c2d516374055', NULL, 21, 21, 'Now all the Athenians and the strangers living there spent their time in nothing else, but either to tell or to hear some new thing.'),
  ('24f986ab-e061-53df-a3fd-6074c3d47f4f', '05931b1e-e388-5cb6-a8bd-c2d516374055', NULL, 22, 22, 'Paul stood in the middle of the Areopagus, and said, "You men of Athens, I perceive that you are very religious in all things.'),
  ('de3077e0-2564-52e4-a145-21b3ebc67d30', '05931b1e-e388-5cb6-a8bd-c2d516374055', NULL, 23, 23, 'For as I passed along, and observed the objects of your worship, I found also an altar with this inscription: ''TO AN UNKNOWN GOD.'' What therefore you worship in ignorance, this I announce to you.'),
  ('db81d0b1-c1cb-5ee6-a018-079e1f508e03', '05931b1e-e388-5cb6-a8bd-c2d516374055', NULL, 24, 24, 'The God who made the world and all things in it, he, being Lord of heaven and earth, doesn''t dwell in temples made with hands,'),
  ('d3667155-1483-5a9e-af8e-c50dc7391447', '05931b1e-e388-5cb6-a8bd-c2d516374055', NULL, 25, 25, 'neither is he served by men''s hands, as though he needed anything, seeing he himself gives to all life and breath, and all things.'),
  ('387e7192-8642-542e-ab18-e59222b53e2f', '05931b1e-e388-5cb6-a8bd-c2d516374055', NULL, 26, 26, 'He made from one blood every nation of men to dwell on all the surface of the earth, having determined appointed seasons, and the boundaries of their dwellings,'),
  ('2ca81ca2-8a91-5926-a874-9fe0f00ed091', '05931b1e-e388-5cb6-a8bd-c2d516374055', NULL, 27, 27, 'that they should seek the Lord, if perhaps they might reach out for him and find him, though he is not far from each one of us.'),
  ('8bdf1ded-79b6-5a34-ac7e-cfd9c18b6204', '05931b1e-e388-5cb6-a8bd-c2d516374055', NULL, 28, 28, '''For in him we live, and move, and have our being.'' As some of your own poets have said, ''For we are also his offspring.'''),
  ('072379f0-15f9-550c-a5be-ddce4d1c5906', '05931b1e-e388-5cb6-a8bd-c2d516374055', NULL, 29, 29, 'Being then the offspring of God, we ought not to think that the Divine Nature is like gold, or silver, or stone, engraved by art and design of man.'),
  ('0511ca58-b866-5b9c-aa7f-b01943a285a9', '05931b1e-e388-5cb6-a8bd-c2d516374055', NULL, 30, 30, 'The times of ignorance therefore God overlooked. But now he commands that all people everywhere should repent,'),
  ('f6821fc0-a1d0-5cbd-a469-6a25d79d6fec', '05931b1e-e388-5cb6-a8bd-c2d516374055', NULL, 31, 31, 'because he has appointed a day in which he will judge the world in righteousness by the man whom he has ordained; of which he has given assurance to all men, in that he has raised him from the dead."'),
  ('855119c5-986a-501c-ab42-b5d321ea303d', '05931b1e-e388-5cb6-a8bd-c2d516374055', NULL, 32, 32, 'Now when they heard of the resurrection of the dead, some mocked; but others said, "We want to hear you again concerning this."'),
  ('a0036bbc-f279-56ed-a0bc-963622d963c2', '05931b1e-e388-5cb6-a8bd-c2d516374055', NULL, 33, 33, 'Thus Paul went out from among them.'),
  ('d42a9e5a-a73c-55c5-a74c-1846a7fe7dbd', '05931b1e-e388-5cb6-a8bd-c2d516374055', NULL, 34, 34, 'But certain men joined with him, and believed, among whom also was Dionysius the Areopagite, and a woman named Damaris, and others with them.'),
  ('f516ef47-782e-5e83-ae45-3bef3423e6bb', 'bf1cf8a2-3646-59db-a12c-0d676f0413b6', NULL, 1, 1, 'After these things Paul departed from Athens, and came to Corinth.'),
  ('2acf5232-d1b6-5c59-a509-cec88e275cf9', 'bf1cf8a2-3646-59db-a12c-0d676f0413b6', NULL, 2, 2, 'He found a certain Jew named Aquila, a man of Pontus by race, who had recently come from Italy, with his wife Priscilla, because Claudius had commanded all the Jews to depart from Rome. He came to them,'),
  ('61327a30-6514-532b-a2a7-4a5edb03126c', 'bf1cf8a2-3646-59db-a12c-0d676f0413b6', NULL, 3, 3, 'and because he practiced the same trade, he lived with them and worked, for by trade they were tent makers.'),
  ('1cff86d6-a9a2-5b0e-af7e-1a0e0cfb48bd', 'bf1cf8a2-3646-59db-a12c-0d676f0413b6', NULL, 4, 4, 'He reasoned in the synagogue every Sabbath, and persuaded Jews and Greeks.'),
  ('0ffcc5ec-265a-5baf-a8cd-189893ff42ad', 'bf1cf8a2-3646-59db-a12c-0d676f0413b6', NULL, 5, 5, 'But when Silas and Timothy came down from Macedonia, Paul was compelled by the Spirit, testifying to the Jews that Jesus was the Christ.'),
  ('18cdcda5-9776-5644-a907-4cbea836e3e3', 'bf1cf8a2-3646-59db-a12c-0d676f0413b6', NULL, 6, 6, 'When they opposed him and blasphemed, he shook out his clothing and said to them, "Your blood be on your own heads! I am clean. From now on, I will go to the Gentiles!"'),
  ('3aeecf71-ce39-538c-a3ef-09efcf5e5f86', 'bf1cf8a2-3646-59db-a12c-0d676f0413b6', NULL, 7, 7, 'He departed there, and went into the house of a certain man named Justus, one who worshiped God, whose house was next door to the synagogue.'),
  ('0bd7ebe0-70d2-5ffd-a178-c92b148ae987', 'bf1cf8a2-3646-59db-a12c-0d676f0413b6', NULL, 8, 8, 'Crispus, the ruler of the synagogue, believed in the Lord with all his house. Many of the Corinthians, when they heard, believed and were baptized.'),
  ('eebf3209-4ca3-54f6-a220-393af2ea7389', 'bf1cf8a2-3646-59db-a12c-0d676f0413b6', NULL, 9, 9, 'The Lord said to Paul in the night by a vision, "Don''t be afraid, but speak and don''t be silent;'),
  ('be31d744-e0a6-59f6-a7dd-124291a58ef4', 'bf1cf8a2-3646-59db-a12c-0d676f0413b6', NULL, 10, 10, 'for I am with you, and no one will attack you to harm you, for I have many people in this city."'),
  ('0f17155f-373e-57c0-abba-26ee80ad225d', 'bf1cf8a2-3646-59db-a12c-0d676f0413b6', NULL, 11, 11, 'He lived there a year and six months, teaching the word of God among them.'),
  ('8e2e82f0-fd9c-55a8-a004-f9b026d3cd1d', 'bf1cf8a2-3646-59db-a12c-0d676f0413b6', NULL, 12, 12, 'But when Gallio was proconsul of Achaia, the Jews with one accord rose up against Paul and brought him before the judgment seat,'),
  ('013fac94-c532-50ff-ab31-a9d5cddbe707', 'bf1cf8a2-3646-59db-a12c-0d676f0413b6', NULL, 13, 13, 'saying, "This man persuades men to worship God contrary to the law."'),
  ('df9a19de-8f58-5d80-a71a-1e885125afb7', 'bf1cf8a2-3646-59db-a12c-0d676f0413b6', NULL, 14, 14, 'But when Paul was about to open his mouth, Gallio said to the Jews, "If indeed it were a matter of wrong or of wicked crime, you Jews, it would be reasonable that I should bear with you;'),
  ('e038c299-00bb-57f1-a808-d4d9ff168593', 'bf1cf8a2-3646-59db-a12c-0d676f0413b6', NULL, 15, 15, 'but if they are questions about words and names and your own law, look to it yourselves. For I don''t want to be a judge of these matters."'),
  ('bb215f6b-b4d9-50c5-aa81-af5d528d63ff', 'bf1cf8a2-3646-59db-a12c-0d676f0413b6', NULL, 16, 16, 'He drove them from the judgment seat.'),
  ('d6a8c06f-ad16-5ef7-a49d-91c9e9b05ddd', 'bf1cf8a2-3646-59db-a12c-0d676f0413b6', NULL, 17, 17, 'Then all the Greeks laid hold on Sosthenes, the ruler of the synagogue, and beat him before the judgment seat. Gallio didn''t care about any of these things.'),
  ('a7939c19-3bbe-5f6e-ac9d-21d6ed62dd34', 'bf1cf8a2-3646-59db-a12c-0d676f0413b6', NULL, 18, 18, 'Paul, having stayed after this many more days, took his leave of the brothers, and sailed from there for Syria, together with Priscilla and Aquila. He shaved his head in Cenchreae, for he had a vow.'),
  ('7bad3705-281d-5eb8-ab81-96916975405b', 'bf1cf8a2-3646-59db-a12c-0d676f0413b6', NULL, 19, 19, 'He came to Ephesus, and he left them there; but he himself entered into the synagogue, and reasoned with the Jews.'),
  ('a8421a0f-c9e8-5862-ade1-fe28de5fd0c7', 'bf1cf8a2-3646-59db-a12c-0d676f0413b6', NULL, 20, 20, 'When they asked him to stay with them a longer time, he declined;'),
  ('128c84fb-5e61-5e05-a82a-b8564cbeb1f0', 'bf1cf8a2-3646-59db-a12c-0d676f0413b6', NULL, 21, 21, 'but taking his leave of them, and saying, "I must by all means keep this coming feast in Jerusalem, but I will return again to you if God wills," he set sail from Ephesus.'),
  ('387eb81b-82d7-5e89-a20c-c4a591da733f', 'bf1cf8a2-3646-59db-a12c-0d676f0413b6', NULL, 22, 22, 'When he had landed at Caesarea, he went up and greeted the assembly, and went down to Antioch.'),
  ('ba03e959-6be4-5338-a9bc-e18892454554', 'bf1cf8a2-3646-59db-a12c-0d676f0413b6', NULL, 23, 23, 'Having spent some time there, he departed, and went through the region of Galatia, and Phrygia, in order, establishing all the disciples.'),
  ('7050d52f-248d-5494-a0a9-9bd47f59d52e', 'bf1cf8a2-3646-59db-a12c-0d676f0413b6', NULL, 24, 24, 'Now a certain Jew named Apollos, an Alexandrian by race, an eloquent man, came to Ephesus. He was mighty in the Scriptures.'),
  ('cb685393-2663-5da2-a729-046aa6dd46c6', 'bf1cf8a2-3646-59db-a12c-0d676f0413b6', NULL, 25, 25, 'This man had been instructed in the way of the Lord; and being fervent in spirit, he spoke and taught accurately the things concerning Jesus, although he knew only the baptism of John.'),
  ('dacc554c-7ac1-5e7b-a1cb-532929b2a36c', 'bf1cf8a2-3646-59db-a12c-0d676f0413b6', NULL, 26, 26, 'He began to speak boldly in the synagogue. But when Priscilla and Aquila heard him, they took him aside, and explained to him the way of God more accurately.'),
  ('1f28c2b5-1afb-5970-a22c-c8bbf2beecb6', 'bf1cf8a2-3646-59db-a12c-0d676f0413b6', NULL, 27, 27, 'When he had determined to pass over into Achaia, the brothers encouraged him, and wrote to the disciples to receive him. When he had come, he greatly helped those who had believed through grace;'),
  ('2ba361c7-e7b6-5a45-af14-62b45c8f0f60', 'bf1cf8a2-3646-59db-a12c-0d676f0413b6', NULL, 28, 28, 'for he powerfully refuted the Jews, publicly showing by the Scriptures that Jesus was the Christ.'),
  ('8c3a38f3-a607-5a1e-ac13-3bcb30fd9759', '9e47f6cc-2cbe-51e3-a5fd-09fbffe4055c', NULL, 1, 1, 'It happened that, while Apollos was at Corinth, Paul, having passed through the upper country, came to Ephesus, and found certain disciples.'),
  ('21d97f60-2b3f-5d0a-a07f-07a468d10e40', '9e47f6cc-2cbe-51e3-a5fd-09fbffe4055c', NULL, 2, 2, 'He said to them, "Did you receive the Holy Spirit when you believed?" They said to him, "No, we haven''t even heard that there is a Holy Spirit."'),
  ('dffe4f37-1f48-567d-ae7a-5e4de01541b3', '9e47f6cc-2cbe-51e3-a5fd-09fbffe4055c', NULL, 3, 3, 'He said, "Into what then were you baptized?" They said, "Into John''s baptism."'),
  ('d71a5846-3987-542c-a139-2a645821544c', '9e47f6cc-2cbe-51e3-a5fd-09fbffe4055c', NULL, 4, 4, 'Paul said, "John indeed baptized with the baptism of repentance, saying to the people that they should believe in the one who would come after him, that is, in Jesus."'),
  ('7f23028c-26b1-5a7c-a34e-371d350b74b9', '9e47f6cc-2cbe-51e3-a5fd-09fbffe4055c', NULL, 5, 5, 'When they heard this, they were baptized in the name of the Lord Jesus.'),
  ('d6fe31d7-d374-594d-a96f-285b541b1635', '9e47f6cc-2cbe-51e3-a5fd-09fbffe4055c', NULL, 6, 6, 'When Paul had laid his hands on them, the Holy Spirit came on them, and they spoke with other languages and prophesied.'),
  ('308add5f-586d-5034-a12b-686aa0f69a7a', '9e47f6cc-2cbe-51e3-a5fd-09fbffe4055c', NULL, 7, 7, 'They were about twelve men in all.'),
  ('6e8ebd0e-874e-5503-a442-4525c578e2ab', '9e47f6cc-2cbe-51e3-a5fd-09fbffe4055c', NULL, 8, 8, 'He entered into the synagogue, and spoke boldly for a period of three months, reasoning and persuading about the things concerning the Kingdom of God.'),
  ('43a857bb-f11e-53df-afd5-4f5c1efd3515', '9e47f6cc-2cbe-51e3-a5fd-09fbffe4055c', NULL, 9, 9, 'But when some were hardened and disobedient, speaking evil of the Way before the multitude, he departed from them, and separated the disciples, reasoning daily in the school of Tyrannus.'),
  ('28deb615-5904-5c86-ad55-eddeef6f9dd4', '9e47f6cc-2cbe-51e3-a5fd-09fbffe4055c', NULL, 10, 10, 'This continued for two years, so that all those who lived in Asia heard the word of the Lord Jesus, both Jews and Greeks.'),
  ('247b6814-07b9-505c-a1d9-3719d71b2b3b', '9e47f6cc-2cbe-51e3-a5fd-09fbffe4055c', NULL, 11, 11, 'God worked special miracles by the hands of Paul,'),
  ('d1db6784-0409-5e89-a7d0-f8fba62711e7', '9e47f6cc-2cbe-51e3-a5fd-09fbffe4055c', NULL, 12, 12, 'so that even handkerchiefs or aprons were carried away from his body to the sick, and the evil spirits went out.'),
  ('0d22fbe0-8e74-565a-a18e-708012b55249', '9e47f6cc-2cbe-51e3-a5fd-09fbffe4055c', NULL, 13, 13, 'But some of the itinerant Jews, exorcists, took on themselves to invoke over those who had the evil spirits the name of the Lord Jesus, saying, "We adjure you by Jesus whom Paul preaches."'),
  ('260771f4-679e-5958-a03e-694c807cfa4c', '9e47f6cc-2cbe-51e3-a5fd-09fbffe4055c', NULL, 14, 14, 'There were seven sons of one Sceva, a Jewish chief priest, who did this.'),
  ('a9930919-33a8-52bf-adfa-fc9e956bafd4', '9e47f6cc-2cbe-51e3-a5fd-09fbffe4055c', NULL, 15, 15, 'The evil spirit answered, "Jesus I know, and Paul I know, but who are you?"'),
  ('1e901f8a-7d02-5182-a3c9-82f01ee77483', '9e47f6cc-2cbe-51e3-a5fd-09fbffe4055c', NULL, 16, 16, 'The man in whom the evil spirit was leaped on them, and overpowered them, and prevailed against them, so that they fled out of that house naked and wounded.'),
  ('8caa581a-a0b9-5c7f-a384-b0041464cd2c', '9e47f6cc-2cbe-51e3-a5fd-09fbffe4055c', NULL, 17, 17, 'This became known to all, both Jews and Greeks, who lived at Ephesus. Fear fell on them all, and the name of the Lord Jesus was magnified.'),
  ('bc0f4825-b05c-5e07-a5e8-de277d9ede09', '9e47f6cc-2cbe-51e3-a5fd-09fbffe4055c', NULL, 18, 18, 'Many also of those who had believed came, confessing, and declaring their deeds.'),
  ('22b6b8db-a148-5965-a394-711a04f1c5f4', '9e47f6cc-2cbe-51e3-a5fd-09fbffe4055c', NULL, 19, 19, 'Many of those who practiced magical arts brought their books together and burned them in the sight of all. They counted the price of them, and found it to be fifty thousand pieces of silver.'),
  ('6d25fc5d-a80d-5e35-ab9f-3dd175ec1814', '9e47f6cc-2cbe-51e3-a5fd-09fbffe4055c', NULL, 20, 20, 'So the word of the Lord was growing and becoming mighty.'),
  ('c372be5d-7396-5465-a4b2-6c37558a2928', '9e47f6cc-2cbe-51e3-a5fd-09fbffe4055c', NULL, 21, 21, 'Now after these things had ended, Paul determined in the spirit, when he had passed through Macedonia and Achaia, to go to Jerusalem, saying, "After I have been there, I must also see Rome."'),
  ('703a6b63-9216-5a76-a706-e6030b952bbc', '9e47f6cc-2cbe-51e3-a5fd-09fbffe4055c', NULL, 22, 22, 'Having sent into Macedonia two of those who served him, Timothy and Erastus, he himself stayed in Asia for a while.'),
  ('a3c17ba0-9969-57c7-a54a-665b6ea6b6a0', '9e47f6cc-2cbe-51e3-a5fd-09fbffe4055c', NULL, 23, 23, 'About that time there arose no small stir concerning the Way.'),
  ('3c0760bf-eb21-5e34-a098-4116dc701cc2', '9e47f6cc-2cbe-51e3-a5fd-09fbffe4055c', NULL, 24, 24, 'For a certain man named Demetrius, a silversmith, who made silver shrines of Artemis, brought no little business to the craftsmen,'),
  ('09ec99c0-41a2-5783-abd4-7743a7e69ccd', '9e47f6cc-2cbe-51e3-a5fd-09fbffe4055c', NULL, 25, 25, 'whom he gathered together, with the workmen of like occupation, and said, "Sirs, you know that by this business we have our wealth.')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('13994897-5163-5ba2-a9ec-ce1d2caec9d2', '9e47f6cc-2cbe-51e3-a5fd-09fbffe4055c', NULL, 26, 26, 'You see and hear, that not at Ephesus alone, but almost throughout all Asia, this Paul has persuaded and turned away many people, saying that they are no gods, that are made with hands.'),
  ('d5475ba0-ec0b-53b6-a0dd-73f02b576da5', '9e47f6cc-2cbe-51e3-a5fd-09fbffe4055c', NULL, 27, 27, 'Not only is there danger that this our trade come into disrepute, but also that the temple of the great goddess Artemis will be counted as nothing, and her majesty destroyed, whom all Asia and the world worships."'),
  ('a87dfe49-623c-5a75-afc7-fa66bd04ffea', '9e47f6cc-2cbe-51e3-a5fd-09fbffe4055c', NULL, 28, 28, 'When they heard this they were filled with anger, and cried out, saying, "Great is Artemis of the Ephesians!"'),
  ('449f4f2c-2c58-5474-a5ed-3897c286a184', '9e47f6cc-2cbe-51e3-a5fd-09fbffe4055c', NULL, 29, 29, 'The whole city was filled with confusion, and they rushed with one accord into the theater, having seized Gaius and Aristarchus, men of Macedonia, Paul''s companions in travel.'),
  ('ee345dc9-6cd4-5f85-af2d-f8e8198a7bd4', '9e47f6cc-2cbe-51e3-a5fd-09fbffe4055c', NULL, 30, 30, 'When Paul wanted to enter in to the people, the disciples didn''t allow him.'),
  ('80f25ab9-0da5-52cb-aa16-aa1afc125b26', '9e47f6cc-2cbe-51e3-a5fd-09fbffe4055c', NULL, 31, 31, 'Certain also of the Asiarchs, being his friends, sent to him and begged him not to venture into the theater.'),
  ('289ea303-f41d-5388-a996-a30e3cb154e5', '9e47f6cc-2cbe-51e3-a5fd-09fbffe4055c', NULL, 32, 32, 'Some therefore cried one thing, and some another, for the assembly was in confusion. Most of them didn''t know why they had come together.'),
  ('d55f3776-a712-57c0-aaa5-84ac5c04d687', '9e47f6cc-2cbe-51e3-a5fd-09fbffe4055c', NULL, 33, 33, 'They brought Alexander out of the multitude, the Jews putting him forward. Alexander beckoned with his hand, and would have made a defense to the people.'),
  ('447bfa7c-4494-5ef9-a75d-8eae9d0676c0', '9e47f6cc-2cbe-51e3-a5fd-09fbffe4055c', NULL, 34, 34, 'But when they perceived that he was a Jew, all with one voice for a time of about two hours cried out, "Great is Artemis of the Ephesians!"'),
  ('5269dd09-6222-5106-ad66-6d836ad44454', '9e47f6cc-2cbe-51e3-a5fd-09fbffe4055c', NULL, 35, 35, 'When the town clerk had quieted the multitude, he said, "You men of Ephesus, what man is there who doesn''t know that the city of the Ephesians is temple keeper of the great goddess Artemis, and of the image which fell down from Zeus?'),
  ('4f897235-4e6a-58e1-aabf-51ed69708c0a', '9e47f6cc-2cbe-51e3-a5fd-09fbffe4055c', NULL, 36, 36, 'Seeing then that these things can''t be denied, you ought to be quiet, and to do nothing rash.'),
  ('f2b62e1b-9e6c-55db-a626-f9c404249c5e', '9e47f6cc-2cbe-51e3-a5fd-09fbffe4055c', NULL, 37, 37, 'For you have brought these men here, who are neither robbers of temples nor blasphemers of your goddess.'),
  ('7183fdf2-3a9b-5743-a722-479d770255c3', '9e47f6cc-2cbe-51e3-a5fd-09fbffe4055c', NULL, 38, 38, 'If therefore Demetrius and the craftsmen who are with him have a matter against anyone, the courts are open, and there are proconsuls. Let them press charges against one another.'),
  ('43c9ae4c-9bb0-5bf3-a8cd-936f2351b5f2', '9e47f6cc-2cbe-51e3-a5fd-09fbffe4055c', NULL, 39, 39, 'But if you seek anything about other matters, it will be settled in the regular assembly.'),
  ('5c88c3e8-bdc8-5b4d-a7c2-f2e22a1915b9', '9e47f6cc-2cbe-51e3-a5fd-09fbffe4055c', NULL, 40, 40, 'For indeed we are in danger of being accused concerning this day''s riot, there being no cause. Concerning it, we wouldn''t be able to give an account of this commotion."'),
  ('a3b9c144-dd58-5204-ae4a-2b510fe58a48', '9e47f6cc-2cbe-51e3-a5fd-09fbffe4055c', NULL, 41, 41, 'When he had thus spoken, he dismissed the assembly.'),
  ('135208f8-0a7c-56e5-af35-ff2e49f7d4a7', '9b5483bf-2789-57b9-a352-1ba368cceeef', NULL, 1, 1, 'After the uproar had ceased, Paul sent for the disciples, took leave of them, and departed to go into Macedonia.'),
  ('0a400f77-d84f-52ee-a9c4-f83c01c24ee0', '9b5483bf-2789-57b9-a352-1ba368cceeef', NULL, 2, 2, 'When he had gone through those parts, and had encouraged them with many words, he came into Greece.'),
  ('40afe3ed-968a-58f4-a512-b89aa90993f2', '9b5483bf-2789-57b9-a352-1ba368cceeef', NULL, 3, 3, 'When he had spent three months there, and a plot was made against him by Jews as he was about to set sail for Syria, he determined to return through Macedonia.'),
  ('616291d1-4dbf-5bac-a26a-36c2fd45069c', '9b5483bf-2789-57b9-a352-1ba368cceeef', NULL, 4, 4, 'These accompanied him as far as Asia: Sopater of Beroea; Aristarchus and Secundus of the Thessalonians; Gaius of Derbe; Timothy; and Tychicus and Trophimus of Asia.'),
  ('5088ce5b-3a56-5ea4-a870-4c014f181c3f', '9b5483bf-2789-57b9-a352-1ba368cceeef', NULL, 5, 5, 'But these had gone ahead, and were waiting for us at Troas.'),
  ('7e6d2b6f-a39a-5cdb-a12e-1ce0c1dec8d5', '9b5483bf-2789-57b9-a352-1ba368cceeef', NULL, 6, 6, 'We sailed away from Philippi after the days of Unleavened Bread, and came to them at Troas in five days, where we stayed seven days.'),
  ('3c654481-bb26-594a-a0e7-fd943a355ad0', '9b5483bf-2789-57b9-a352-1ba368cceeef', NULL, 7, 7, 'On the first day of the week, when the disciples were gathered together to break bread, Paul talked with them, intending to depart on the next day, and continued his speech until midnight.'),
  ('f1071553-9a79-50fb-a5fa-1075c29d586e', '9b5483bf-2789-57b9-a352-1ba368cceeef', NULL, 8, 8, 'There were many lights in the upper room where we were gathered together.'),
  ('a4d098e0-da44-56d8-af53-cc55d08b705b', '9b5483bf-2789-57b9-a352-1ba368cceeef', NULL, 9, 9, 'A certain young man named Eutychus sat in the window, weighed down with deep sleep. As Paul spoke still longer, being weighed down by his sleep, he fell down from the third story, and was taken up dead.'),
  ('106eab1a-c303-51e8-a7cd-bebe5156d6c3', '9b5483bf-2789-57b9-a352-1ba368cceeef', NULL, 10, 10, 'Paul went down, and fell upon him, and embracing him said, "Don''t be troubled, for his life is in him."'),
  ('4ac5e527-65e4-537d-ae11-20134a756442', '9b5483bf-2789-57b9-a352-1ba368cceeef', NULL, 11, 11, 'When he had gone up, and had broken bread, and eaten, and had talked with them a long while, even until break of day, he departed.'),
  ('74d782d3-ad4d-525c-a5ed-1700bf582d40', '9b5483bf-2789-57b9-a352-1ba368cceeef', NULL, 12, 12, 'They brought the boy in alive, and were greatly comforted.'),
  ('a57565ed-bfa3-50f8-a7a0-5bc0162c3525', '9b5483bf-2789-57b9-a352-1ba368cceeef', NULL, 13, 13, 'But we who went ahead to the ship set sail for Assos, intending to take Paul aboard there, for he had so arranged, intending himself to go by land.'),
  ('5f82cb6d-5e74-55cb-ac1d-bbd066039ebd', '9b5483bf-2789-57b9-a352-1ba368cceeef', NULL, 14, 14, 'When he met us at Assos, we took him aboard, and came to Mitylene.'),
  ('39dfb30e-7d37-52ce-ad7e-7cf2218db18d', '9b5483bf-2789-57b9-a352-1ba368cceeef', NULL, 15, 15, 'Sailing from there, we came the following day opposite Chios. The next day we touched at Samos and stayed at Trogyllium, and the day after we came to Miletus.'),
  ('e4b35b3b-df54-545b-a29e-ec69291f30c9', '9b5483bf-2789-57b9-a352-1ba368cceeef', NULL, 16, 16, 'For Paul had determined to sail past Ephesus, that he might not have to spend time in Asia; for he was hastening, if it were possible for him, to be in Jerusalem on the day of Pentecost.'),
  ('c8243154-ddab-59ad-a4fb-cf51f2cd4f20', '9b5483bf-2789-57b9-a352-1ba368cceeef', NULL, 17, 17, 'From Miletus he sent to Ephesus, and called to himself the elders of the assembly.'),
  ('b8dcdd85-0bc8-5bf8-a1d8-434a892d75b9', '9b5483bf-2789-57b9-a352-1ba368cceeef', NULL, 18, 18, 'When they had come to him, he said to them, "You yourselves know, from the first day that I set foot in Asia, how I was with you all the time,'),
  ('0a473130-c984-5ffe-afa3-c83b06510886', '9b5483bf-2789-57b9-a352-1ba368cceeef', NULL, 19, 19, 'serving the Lord with all humility, with many tears, and with trials which happened to me by the plots of the Jews;'),
  ('d17c8271-864d-5947-a2ae-58f5e8cbe48f', '9b5483bf-2789-57b9-a352-1ba368cceeef', NULL, 20, 20, 'how I didn''t shrink from declaring to you anything that was profitable, teaching you publicly and from house to house,'),
  ('292248c4-8c51-5ce3-a7d1-5c269ef74799', '9b5483bf-2789-57b9-a352-1ba368cceeef', NULL, 21, 21, 'testifying both to Jews and to Greeks repentance toward God, and faith toward our Lord Jesus.'),
  ('a2d22c7c-b75a-573a-ac44-82374d142006', '9b5483bf-2789-57b9-a352-1ba368cceeef', NULL, 22, 22, 'Now, behold, I go bound by the Spirit to Jerusalem, not knowing what will happen to me there;'),
  ('0815b542-8b91-5803-abf4-4e54261880fc', '9b5483bf-2789-57b9-a352-1ba368cceeef', NULL, 23, 23, 'except that the Holy Spirit testifies in every city, saying that bonds and afflictions wait for me.'),
  ('a93da259-78d1-5616-a3c3-510e04d51a90', '9b5483bf-2789-57b9-a352-1ba368cceeef', NULL, 24, 24, 'But these things don''t count; nor do I hold my life dear to myself, so that I may finish my race with joy, and the ministry which I received from the Lord Jesus, to fully testify to the Good News of the grace of God.'),
  ('76963d89-9c02-5b8d-aae0-79523a4395d5', '9b5483bf-2789-57b9-a352-1ba368cceeef', NULL, 25, 25, '"Now, behold, I know that you all, among whom I went about preaching the Kingdom of God, will see my face no more.'),
  ('3eab08e5-f8d0-5f86-af6d-438d126136de', '9b5483bf-2789-57b9-a352-1ba368cceeef', NULL, 26, 26, 'Therefore I testify to you this day that I am clean from the blood of all men,'),
  ('865dfc0d-17d8-5fbe-a305-6287698b1cbf', '9b5483bf-2789-57b9-a352-1ba368cceeef', NULL, 27, 27, 'for I didn''t shrink from declaring to you the whole counsel of God.'),
  ('7224221f-84f4-5ebf-ab08-026e2ac273d6', '9b5483bf-2789-57b9-a352-1ba368cceeef', NULL, 28, 28, 'Take heed, therefore, to yourselves, and to all the flock, in which the Holy Spirit has made you overseers, to shepherd the assembly of the Lord and God which he purchased with his own blood.'),
  ('c12591e3-7808-5009-ad38-a81316244250', '9b5483bf-2789-57b9-a352-1ba368cceeef', NULL, 29, 29, 'For I know that after my departure, vicious wolves will enter in among you, not sparing the flock.'),
  ('85a60ee2-4807-5c70-ae9c-3f278c5c3a04', '9b5483bf-2789-57b9-a352-1ba368cceeef', NULL, 30, 30, 'Men will arise from among your own selves, speaking perverse things, to draw away the disciples after them.'),
  ('d596fdad-eb63-53bb-a3bd-a33c0cda47a1', '9b5483bf-2789-57b9-a352-1ba368cceeef', NULL, 31, 31, 'Therefore watch, remembering that for a period of three years I didn''t cease to admonish everyone night and day with tears.'),
  ('8cc0100d-033b-5c6a-a2d5-d6fe6a458e44', '9b5483bf-2789-57b9-a352-1ba368cceeef', NULL, 32, 32, 'Now, brothers, I entrust you to God, and to the word of his grace, which is able to build up, and to give you the inheritance among all those who are sanctified.'),
  ('3996b04e-7be3-5127-a3f2-b2a2fe16568f', '9b5483bf-2789-57b9-a352-1ba368cceeef', NULL, 33, 33, 'I coveted no one''s silver, or gold, or clothing.'),
  ('de025082-296e-5a6b-a246-4bc83016dc28', '9b5483bf-2789-57b9-a352-1ba368cceeef', NULL, 34, 34, 'You yourselves know that these hands served my necessities, and those who were with me.'),
  ('52958c20-6f41-55d9-affd-9ee4667a36e4', '9b5483bf-2789-57b9-a352-1ba368cceeef', NULL, 35, 35, 'In all things I gave you an example, that so laboring you ought to help the weak, and to remember the words of the Lord Jesus, that he himself said, ''It is more blessed to give than to receive.''"'),
  ('0d126b8e-765c-572d-a789-da2eee72c09a', '9b5483bf-2789-57b9-a352-1ba368cceeef', NULL, 36, 36, 'When he had spoken these things, he knelt down and prayed with them all.'),
  ('b3b6811d-bb91-508d-a1be-736ae9d0f53e', '9b5483bf-2789-57b9-a352-1ba368cceeef', NULL, 37, 37, 'They all wept a lot, and fell on Paul''s neck and kissed him,'),
  ('e638f3d8-3189-5f5a-aa99-d1073bac4f20', '9b5483bf-2789-57b9-a352-1ba368cceeef', NULL, 38, 38, 'sorrowing most of all because of the word which he had spoken, that they should see his face no more. And they accompanied him to the ship.'),
  ('0e2f96cb-d621-5905-ac61-f948c96a090a', '863921de-d73d-56d2-a26f-b675ec522def', NULL, 1, 1, 'When it happened that we had parted from them and had set sail, we came with a straight course to Cos, and the next day to Rhodes, and from there to Patara.'),
  ('03e5d5be-f355-56ee-abfd-55f4d58bb372', '863921de-d73d-56d2-a26f-b675ec522def', NULL, 2, 2, 'Having found a ship crossing over to Phoenicia, we went aboard, and set sail.'),
  ('3f21bead-2fe9-5897-acf4-2f15838afc4b', '863921de-d73d-56d2-a26f-b675ec522def', NULL, 3, 3, 'When we had come in sight of Cyprus, leaving it on the left hand, we sailed to Syria, and landed at Tyre, for there the ship was to unload her cargo.'),
  ('6c5d45b6-7727-509c-a407-4f55bd723253', '863921de-d73d-56d2-a26f-b675ec522def', NULL, 4, 4, 'Having found disciples, we stayed there seven days. These said to Paul through the Spirit, that he should not go up to Jerusalem.'),
  ('5406f880-8fe9-5ab0-a53b-fd56146610d1', '863921de-d73d-56d2-a26f-b675ec522def', NULL, 5, 5, 'When it happened that we had accomplished the days, we departed and went on our journey. They all, with wives and children, brought us on our way until we were out of the city. Kneeling down on the beach, we prayed.'),
  ('e05a4752-715c-5800-a9ca-378c27a21371', '863921de-d73d-56d2-a26f-b675ec522def', NULL, 6, 6, 'After saying goodbye to each other, we went on board the ship, and they returned home again.'),
  ('e0ca28b2-4578-51f4-af24-7c9853a41727', '863921de-d73d-56d2-a26f-b675ec522def', NULL, 7, 7, 'When we had finished the voyage from Tyre, we arrived at Ptolemais. We greeted the brothers, and stayed with them one day.'),
  ('c290dd69-8c3e-5fd3-ab11-7d49dd012980', '863921de-d73d-56d2-a26f-b675ec522def', NULL, 8, 8, 'On the next day, we, who were Paul''s companions, departed, and came to Caesarea. We entered into the house of Philip the evangelist, who was one of the seven, and stayed with him.'),
  ('6a352f58-d4a3-5353-a73b-071485ab5e99', '863921de-d73d-56d2-a26f-b675ec522def', NULL, 9, 9, 'Now this man had four virgin daughters who prophesied.'),
  ('0afba958-cedd-5d6e-a574-bb0ef892d610', '863921de-d73d-56d2-a26f-b675ec522def', NULL, 10, 10, 'As we stayed there some days, a certain prophet named Agabus came down from Judea.'),
  ('9025bb3b-c418-5985-a2b1-907856398467', '863921de-d73d-56d2-a26f-b675ec522def', NULL, 11, 11, 'Coming to us, and taking Paul''s belt, he bound his own feet and hands, and said, "Thus says the Holy Spirit: ''So will the Jews at Jerusalem bind the man who owns this belt, and will deliver him into the hands of the Gentiles.''"'),
  ('f96d139c-b665-56e4-ac9b-09615df77a84', '863921de-d73d-56d2-a26f-b675ec522def', NULL, 12, 12, 'When we heard these things, both we and they of that place begged him not to go up to Jerusalem.'),
  ('9af7bf41-8b24-5736-a823-dd0b07202c22', '863921de-d73d-56d2-a26f-b675ec522def', NULL, 13, 13, 'Then Paul answered, "What are you doing, weeping and breaking my heart? For I am ready not only to be bound, but also to die at Jerusalem for the name of the Lord Jesus."'),
  ('a9a98de6-96ae-5543-ae45-966bd8696ce8', '863921de-d73d-56d2-a26f-b675ec522def', NULL, 14, 14, 'When he would not be persuaded, we ceased, saying, "The Lord''s will be done."'),
  ('e325b80b-ff74-5f21-ab2b-bb66adb66659', '863921de-d73d-56d2-a26f-b675ec522def', NULL, 15, 15, 'After these days we took up our baggage and went up to Jerusalem.'),
  ('bac40d4a-339f-5d18-ad41-45ca05f84ad1', '863921de-d73d-56d2-a26f-b675ec522def', NULL, 16, 16, 'Some of the disciples from Caesarea also went with us, bringing one Mnason of Cyprus, an early disciple, with whom we would stay.'),
  ('75455e96-5a7d-533c-ab47-40851510e722', '863921de-d73d-56d2-a26f-b675ec522def', NULL, 17, 17, 'When we had come to Jerusalem, the brothers received us gladly.'),
  ('1c0189f2-bf34-525c-add1-8e344f0641c6', '863921de-d73d-56d2-a26f-b675ec522def', NULL, 18, 18, 'The day following, Paul went in with us to James; and all the elders were present.'),
  ('b4d6007f-b4c2-5d14-a219-15d606aa35a9', '863921de-d73d-56d2-a26f-b675ec522def', NULL, 19, 19, 'When he had greeted them, he reported one by one the things which God had worked among the Gentiles through his ministry.'),
  ('4d735016-185c-5232-a8eb-4fc9216807a2', '863921de-d73d-56d2-a26f-b675ec522def', NULL, 20, 20, 'They, when they heard it, glorified God. They said to him, "You see, brother, how many thousands there are among the Jews of those who have believed, and they are all zealous for the law.'),
  ('24cdad86-62bf-56ea-a85c-e2acacdba775', '863921de-d73d-56d2-a26f-b675ec522def', NULL, 21, 21, 'They have been informed about you, that you teach all the Jews who are among the Gentiles to forsake Moses, telling them not to circumcise their children neither to walk after the customs.'),
  ('115a65f1-64c9-56d6-ac86-a03fccf2accd', '863921de-d73d-56d2-a26f-b675ec522def', NULL, 22, 22, 'What then? The assembly must certainly meet, for they will hear that you have come.'),
  ('8cccd69a-8993-595c-af7e-c6e0a21773d3', '863921de-d73d-56d2-a26f-b675ec522def', NULL, 23, 23, 'Therefore do what we tell you. We have four men who have taken a vow.'),
  ('2476da3d-7789-563f-a94e-882cabeb19ed', '863921de-d73d-56d2-a26f-b675ec522def', NULL, 24, 24, 'Take them, and purify yourself with them, and pay their expenses for them, that they may shave their heads. Then all will know that there is no truth in the things that they have been informed about you, but that you yourself also walk keeping the law.'),
  ('aef3b21b-1d5f-516a-afa9-ccd15a34e05f', '863921de-d73d-56d2-a26f-b675ec522def', NULL, 25, 25, 'But concerning the Gentiles who believe, we have written our decision that they should observe no such thing, except that they should keep themselves from food offered to idols, from blood, from strangled things, and from sexual immorality."'),
  ('49aeea78-c239-5f0d-a965-01251877a624', '863921de-d73d-56d2-a26f-b675ec522def', NULL, 26, 26, 'Then Paul took the men, and the next day, purified himself and went with them into the temple, declaring the fulfillment of the days of purification, until the offering was offered for every one of them.'),
  ('45645a94-403a-5001-a198-b9613a3ae1a2', '863921de-d73d-56d2-a26f-b675ec522def', NULL, 27, 27, 'When the seven days were almost completed, the Jews from Asia, when they saw him in the temple, stirred up all the multitude and laid hands on him,'),
  ('6e5c0f55-d935-56bb-af1c-0f5a517924d4', '863921de-d73d-56d2-a26f-b675ec522def', NULL, 28, 28, 'crying out, "Men of Israel, help! This is the man who teaches all men everywhere against the people, and the law, and this place. Moreover, he also brought Greeks into the temple, and has defiled this holy place!"'),
  ('2fed6abe-e634-531e-a9b9-f60d4ba76908', '863921de-d73d-56d2-a26f-b675ec522def', NULL, 29, 29, 'For they had seen Trophimus, the Ephesian, with him in the city, and they supposed that Paul had brought him into the temple.'),
  ('40b1d251-bcdf-5b20-a02c-62b722f4f778', '863921de-d73d-56d2-a26f-b675ec522def', NULL, 30, 30, 'All the city was moved, and the people ran together. They seized Paul and dragged him out of the temple. Immediately the doors were shut.'),
  ('928e6868-293a-51a4-a60a-8e1baf2a77db', '863921de-d73d-56d2-a26f-b675ec522def', NULL, 31, 31, 'As they were trying to kill him, news came up to the commanding officer of the regiment that all Jerusalem was in an uproar.'),
  ('398e0a98-a393-5ba6-ada3-7e0550aa3bef', '863921de-d73d-56d2-a26f-b675ec522def', NULL, 32, 32, 'Immediately he took soldiers and centurions, and ran down to them. They, when they saw the chief captain and the soldiers, stopped beating Paul.'),
  ('2e019964-9c10-5f3e-ab3b-b558b260fa3f', '863921de-d73d-56d2-a26f-b675ec522def', NULL, 33, 33, 'Then the commanding officer came near, arrested him, commanded him to be bound with two chains, and inquired who he was and what he had done.'),
  ('6ea82b9a-fb79-5df9-af55-fa180a7171db', '863921de-d73d-56d2-a26f-b675ec522def', NULL, 34, 34, 'Some shouted one thing, and some another, among the crowd. When he couldn''t find out the truth because of the noise, he commanded him to be brought into the barracks.'),
  ('6e6b54a4-a1b5-5b69-a3a2-a95c688b3460', '863921de-d73d-56d2-a26f-b675ec522def', NULL, 35, 35, 'When he came to the stairs, it happened that he was carried by the soldiers because of the violence of the crowd;'),
  ('e922ec64-0a6a-5513-aaf0-7ec1783af2c0', '863921de-d73d-56d2-a26f-b675ec522def', NULL, 36, 36, 'for the multitude of the people followed after, crying out, "Away with him!"'),
  ('cebb7f39-5d5b-59c4-ab86-05edb0544945', '863921de-d73d-56d2-a26f-b675ec522def', NULL, 37, 37, 'As Paul was about to be brought into the barracks, he asked the commanding officer, "May I speak to you?" He said, "Do you know Greek?'),
  ('42fac0d0-4459-593c-a868-9e870f54c724', '863921de-d73d-56d2-a26f-b675ec522def', NULL, 38, 38, 'Aren''t you then the Egyptian, who before these days stirred up to sedition and led out into the wilderness the four thousand men of the Assassins?"'),
  ('dfae1871-fbd5-5f60-a379-86b0b0b8b0de', '863921de-d73d-56d2-a26f-b675ec522def', NULL, 39, 39, 'But Paul said, "I am a Jew, from Tarsus in Cilicia, a citizen of no insignificant city. I beg you, allow me to speak to the people."'),
  ('59bda50a-676f-5e14-a34e-72db5a17c5f5', '863921de-d73d-56d2-a26f-b675ec522def', NULL, 40, 40, 'When he had given him permission, Paul, standing on the stairs, beckoned with his hand to the people. When there was a great silence, he spoke to them in the Hebrew language, saying,'),
  ('a48280fb-eefa-5c83-a7f0-63493042b878', 'f87522b4-6224-54ba-a592-e5b6cfd3a1c4', NULL, 1, 1, '"Brothers and fathers, listen to the defense which I now make to you."'),
  ('cda59c6b-de52-56f8-a931-92463ae373ae', 'f87522b4-6224-54ba-a592-e5b6cfd3a1c4', NULL, 2, 2, 'When they heard that he spoke to them in the Hebrew language, they were even more quiet. He said,'),
  ('a317974a-0ccf-5933-a909-18e72901b911', 'f87522b4-6224-54ba-a592-e5b6cfd3a1c4', NULL, 3, 3, '"I am indeed a Jew, born in Tarsus of Cilicia, but brought up in this city at the feet of Gamaliel, instructed according to the strict tradition of the law of our fathers, being zealous for God, even as you all are this day.'),
  ('03ac3efa-e572-53a3-a0bd-7424cf0c024c', 'f87522b4-6224-54ba-a592-e5b6cfd3a1c4', NULL, 4, 4, 'I persecuted this Way to the death, binding and delivering into prisons both men and women.'),
  ('bcd34e54-fda7-58a7-a352-90fde612bfa8', 'f87522b4-6224-54ba-a592-e5b6cfd3a1c4', NULL, 5, 5, 'As also the high priest and all the council of the elders testify, from whom also I received letters to the brothers, and traveled to Damascus to bring them also who were there to Jerusalem in bonds to be punished.'),
  ('23ee53e2-9649-52ec-aea1-a3bc2a861462', 'f87522b4-6224-54ba-a592-e5b6cfd3a1c4', NULL, 6, 6, 'It happened that, as I made my journey, and came close to Damascus, about noon, suddenly there shone from the sky a great light around me.'),
  ('32fa9398-15bd-5a5f-a813-8a56744d081c', 'f87522b4-6224-54ba-a592-e5b6cfd3a1c4', NULL, 7, 7, 'I fell to the ground, and heard a voice saying to me, ''Saul, Saul, why are you persecuting me?'''),
  ('033640f9-46bc-5c68-a520-9aa40727f4b2', 'f87522b4-6224-54ba-a592-e5b6cfd3a1c4', NULL, 8, 8, 'I answered, ''Who are you, Lord?'' He said to me, ''I am Jesus of Nazareth, whom you persecute.'''),
  ('6eb6c930-019b-59ec-a48d-9e89a431e68e', 'f87522b4-6224-54ba-a592-e5b6cfd3a1c4', NULL, 9, 9, '"Those who were with me indeed saw the light and were afraid, but they didn''t understand the voice of him who spoke to me.'),
  ('8088a19f-d025-523a-a32b-66964f547b40', 'f87522b4-6224-54ba-a592-e5b6cfd3a1c4', NULL, 10, 10, 'I said, ''What shall I do, Lord?'' The Lord said to me, ''Arise, and go into Damascus. There you will be told about all things which are appointed for you to do.'''),
  ('b0c51dde-6d01-5126-ace9-6ace52c05f99', 'f87522b4-6224-54ba-a592-e5b6cfd3a1c4', NULL, 11, 11, 'When I couldn''t see for the glory of that light, being led by the hand of those who were with me, I came into Damascus.'),
  ('cfeef5ca-7ded-596c-a725-834fcf2698ca', 'f87522b4-6224-54ba-a592-e5b6cfd3a1c4', NULL, 12, 12, 'One Ananias, a devout man according to the law, well reported of by all the Jews who lived in Damascus,'),
  ('b3fbfc25-11d1-53f3-a66e-c698b5bf9145', 'f87522b4-6224-54ba-a592-e5b6cfd3a1c4', NULL, 13, 13, 'came to me, and standing by me said to me, ''Brother Saul, receive your sight!'' In that very hour I looked up at him.'),
  ('e1d22ebf-d53c-5ddf-aeda-4a2e3b52b700', 'f87522b4-6224-54ba-a592-e5b6cfd3a1c4', NULL, 14, 14, 'He said, ''The God of our fathers has appointed you to know his will, and to see the Righteous One, and to hear a voice from his mouth.'),
  ('f945d845-c20a-5927-a34f-edd377d8d101', 'f87522b4-6224-54ba-a592-e5b6cfd3a1c4', NULL, 15, 15, 'For you will be a witness for him to all men of what you have seen and heard.'),
  ('2a386097-5f42-5aab-aed4-a2c3a9bdceb0', 'f87522b4-6224-54ba-a592-e5b6cfd3a1c4', NULL, 16, 16, 'Now why do you wait? Arise, be baptized, and wash away your sins, calling on the name of the Lord.'''),
  ('4bb5dde7-fbdd-50a6-a236-fc1f2ecdfcce', 'f87522b4-6224-54ba-a592-e5b6cfd3a1c4', NULL, 17, 17, '"It happened that, when I had returned to Jerusalem, and while I prayed in the temple, I fell into a trance,'),
  ('1252f55e-d51c-507e-a2eb-a5e66e991e07', 'f87522b4-6224-54ba-a592-e5b6cfd3a1c4', NULL, 18, 18, 'and saw him saying to me, ''Hurry and get out of Jerusalem quickly, because they will not receive testimony concerning me from you.'''),
  ('5321c766-fd2f-5477-ae35-e0af4a2d49b8', 'f87522b4-6224-54ba-a592-e5b6cfd3a1c4', NULL, 19, 19, 'I said, ''Lord, they themselves know that I imprisoned and beat in every synagogue those who believed in you.'),
  ('288416c7-c4c8-54cf-abdd-df6a08fceb09', 'f87522b4-6224-54ba-a592-e5b6cfd3a1c4', NULL, 20, 20, 'When the blood of Stephen, your witness, was shed, I also was standing by, and consenting to his death, and guarding the cloaks of those who killed him.'''),
  ('0bdfb28d-4530-55c4-aeb5-8506215d4452', 'f87522b4-6224-54ba-a592-e5b6cfd3a1c4', NULL, 21, 21, '"He said to me, ''Depart, for I will send you out far from here to the Gentiles.''"'),
  ('b08dc35b-62ac-5f11-afe4-4dc13e2ab870', 'f87522b4-6224-54ba-a592-e5b6cfd3a1c4', NULL, 22, 22, 'They listened to him until he said that; then they lifted up their voice, and said, "Rid the earth of this fellow, for he isn''t fit to live!"'),
  ('e54d6cdf-44c5-5654-a8b0-125f50521437', 'f87522b4-6224-54ba-a592-e5b6cfd3a1c4', NULL, 23, 23, 'As they cried out, and threw off their cloaks, and threw dust into the air,'),
  ('6a967c7b-78c6-5dd7-a227-1848b132fd34', 'f87522b4-6224-54ba-a592-e5b6cfd3a1c4', NULL, 24, 24, 'the commanding officer commanded him to be brought into the barracks, ordering him to be examined by scourging, that he might know for what crime they shouted against him like that.'),
  ('793c16c2-3527-5e34-ac71-e8a07a52b93e', 'f87522b4-6224-54ba-a592-e5b6cfd3a1c4', NULL, 25, 25, 'When they had tied him up with thongs, Paul asked the centurion who stood by, "Is it lawful for you to scourge a man who is a Roman, and not found guilty?"'),
  ('1b605308-61e9-5771-abb7-560690bd6bd9', 'f87522b4-6224-54ba-a592-e5b6cfd3a1c4', NULL, 26, 26, 'When the centurion heard it, he went to the commanding officer and told him, "Watch what you are about to do, for this man is a Roman!"'),
  ('1be27ac6-4c5d-59cf-a2b7-f554c07b8d11', 'f87522b4-6224-54ba-a592-e5b6cfd3a1c4', NULL, 27, 27, 'The commanding officer came and asked him, "Tell me, are you a Roman?" He said, "Yes."'),
  ('8d9a9c07-792e-5390-a7c5-945be7309ae9', 'f87522b4-6224-54ba-a592-e5b6cfd3a1c4', NULL, 28, 28, 'The commanding officer answered, "I bought my citizenship for a great price." Paul said, "But I was born a Roman."'),
  ('df7b2c8a-6db0-5384-a969-2c3d6679d598', 'f87522b4-6224-54ba-a592-e5b6cfd3a1c4', NULL, 29, 29, 'Immediately those who were about to examine him departed from him, and the commanding officer also was afraid when he realized that he was a Roman, because he had bound him.'),
  ('0b6acec0-24fd-5a42-a897-6e150c329dee', 'f87522b4-6224-54ba-a592-e5b6cfd3a1c4', NULL, 30, 30, 'But on the next day, desiring to know the truth about why he was accused by the Jews, he freed him from the bonds, and commanded the chief priests and all the council to come together, and brought Paul down and set him before them.'),
  ('306b8ea9-02f5-5137-aadc-eca12b3f88f7', 'e04eb58b-520a-50bc-a452-9dfb4dee8b81', NULL, 1, 1, 'Paul, looking steadfastly at the council, said, "Brothers, I have lived before God in all good conscience until this day."'),
  ('6072b33f-e1d1-5731-a500-7128ce2b071d', 'e04eb58b-520a-50bc-a452-9dfb4dee8b81', NULL, 2, 2, 'The high priest, Ananias, commanded those who stood by him to strike him on the mouth.'),
  ('391a5de2-78bb-5f48-ae6a-ae13f878a3e1', 'e04eb58b-520a-50bc-a452-9dfb4dee8b81', NULL, 3, 3, 'Then Paul said to him, "God will strike you, you whitewashed wall! Do you sit to judge me according to the law, and command me to be struck contrary to the law?"'),
  ('fbd8350b-79d5-578d-ae12-7adc33eee22d', 'e04eb58b-520a-50bc-a452-9dfb4dee8b81', NULL, 4, 4, 'Those who stood by said, "Do you malign God''s high priest?"'),
  ('8aa3de12-da08-50c8-a16b-eaf310bbff07', 'e04eb58b-520a-50bc-a452-9dfb4dee8b81', NULL, 5, 5, 'Paul said, "I didn''t know, brothers, that he was high priest. For it is written, ''You shall not speak evil of a ruler of your people.''"'),
  ('2cc88a5e-54ef-59ae-a614-bb16547a7c9c', 'e04eb58b-520a-50bc-a452-9dfb4dee8b81', NULL, 6, 6, 'But when Paul perceived that the one part were Sadducees and the other Pharisees, he cried out in the council, "Men and brothers, I am a Pharisee, a son of Pharisees. Concerning the hope and resurrection of the dead I am being judged!"'),
  ('7d071182-3333-5aae-a60a-3a15a5ef0660', 'e04eb58b-520a-50bc-a452-9dfb4dee8b81', NULL, 7, 7, 'When he had said this, an argument arose between the Pharisees and Sadducees, and the assembly was divided.'),
  ('af845302-ff72-55f6-ae5f-3ebee497c3af', 'e04eb58b-520a-50bc-a452-9dfb4dee8b81', NULL, 8, 8, 'For the Sadducees say that there is no resurrection, nor angel, nor spirit; but the Pharisees confess all of these.'),
  ('0632df3b-7958-597d-a6b7-270433052711', 'e04eb58b-520a-50bc-a452-9dfb4dee8b81', NULL, 9, 9, 'A great clamor arose, and some of the scribes of the Pharisees part stood up, and contended, saying, "We find no evil in this man. But if a spirit or angel has spoken to him, let''s not fight against God!"'),
  ('eda9d4cc-ecec-55a6-a739-146684408934', 'e04eb58b-520a-50bc-a452-9dfb4dee8b81', NULL, 10, 10, 'When a great argument arose, the commanding officer, fearing that Paul would be torn in pieces by them, commanded the soldiers to go down and take him by force from among them, and bring him into the barracks.'),
  ('14acd5bb-d1bd-5b98-ad0e-bfdfa1ae679f', 'e04eb58b-520a-50bc-a452-9dfb4dee8b81', NULL, 11, 11, 'The following night, the Lord stood by him, and said, "Cheer up, Paul, for as you have testified about me at Jerusalem, so you must testify also at Rome."'),
  ('ef3ce47d-3de8-55d2-a433-a201442dba2d', 'e04eb58b-520a-50bc-a452-9dfb4dee8b81', NULL, 12, 12, 'When it was day, some of the Jews banded together, and bound themselves under a curse, saying that they would neither eat nor drink until they had killed Paul.'),
  ('a0a66c59-2150-502e-a13c-0b889eb769af', 'e04eb58b-520a-50bc-a452-9dfb4dee8b81', NULL, 13, 13, 'There were more than forty people who had made this conspiracy.'),
  ('fdf4dc7f-52ee-57e2-afe1-ac075f18b1e5', 'e04eb58b-520a-50bc-a452-9dfb4dee8b81', NULL, 14, 14, 'They came to the chief priests and the elders, and said, "We have bound ourselves under a great curse, to taste nothing until we have killed Paul.'),
  ('f077765d-8a7c-5be6-ad4a-ea45b9ee6816', 'e04eb58b-520a-50bc-a452-9dfb4dee8b81', NULL, 15, 15, 'Now therefore, you with the council inform the commanding officer that he should bring him down to you tomorrow, as though you were going to judge his case more exactly. We are ready to kill him before he comes near."'),
  ('5742727d-8698-504f-ab7c-a9e7f7af4fc9', 'e04eb58b-520a-50bc-a452-9dfb4dee8b81', NULL, 16, 16, 'But Paul''s sister''s son heard of their lying in wait, and he came and entered into the barracks and told Paul.'),
  ('908f3d9c-16bf-5c3d-a9ad-8ceb930b8eb9', 'e04eb58b-520a-50bc-a452-9dfb4dee8b81', NULL, 17, 17, 'Paul summoned one of the centurions, and said, "Bring this young man to the commanding officer, for he has something to tell him."'),
  ('ee5c3e4a-e372-53bd-ab38-faa06a2112ee', 'e04eb58b-520a-50bc-a452-9dfb4dee8b81', NULL, 18, 18, 'So he took him, and brought him to the commanding officer, and said, "Paul, the prisoner, summoned me and asked me to bring this young man to you, who has something to tell you."'),
  ('168e25ce-d3a7-5de5-a28a-7e42afc9b10f', 'e04eb58b-520a-50bc-a452-9dfb4dee8b81', NULL, 19, 19, 'The commanding officer took him by the hand, and going aside, asked him privately, "What is it that you have to tell me?"'),
  ('df76e6b5-e9cc-52b0-aff7-345e8f5cf67f', 'e04eb58b-520a-50bc-a452-9dfb4dee8b81', NULL, 20, 20, 'He said, "The Jews have agreed to ask you to bring Paul down to the council tomorrow, as though intending to inquire somewhat more accurately concerning him.'),
  ('10445662-1bc4-5af8-a28f-f1490f171bd8', 'e04eb58b-520a-50bc-a452-9dfb4dee8b81', NULL, 21, 21, 'Therefore don''t yield to them, for more than forty men lie in wait for him, who have bound themselves under a curse neither to eat nor to drink until they have killed him. Now they are ready, looking for the promise from you."'),
  ('86731303-5875-5bf8-aa6f-69261b56f324', 'e04eb58b-520a-50bc-a452-9dfb4dee8b81', NULL, 22, 22, 'So the commanding officer let the young man go, charging him, "Tell no one that you have revealed these things to me."'),
  ('13a54ad5-d38f-5584-ab69-34d029bb2755', 'e04eb58b-520a-50bc-a452-9dfb4dee8b81', NULL, 23, 23, 'He called to himself two of the centurions, and said, "Prepare two hundred soldiers to go as far as Caesarea, with seventy horsemen, and two hundred men armed with spears, at the third hour of the night."'),
  ('9ca023f4-41fb-54b5-a10f-5e1d74979968', 'e04eb58b-520a-50bc-a452-9dfb4dee8b81', NULL, 24, 24, 'He asked them to provide animals, that they might set Paul on one, and bring him safely to Felix the governor.'),
  ('5bb3a79b-464d-5840-a5ba-120603dad45f', 'e04eb58b-520a-50bc-a452-9dfb4dee8b81', NULL, 25, 25, 'He wrote a letter like this:'),
  ('8163bef8-9a47-5280-a6ee-e9b6f1adbaa5', 'e04eb58b-520a-50bc-a452-9dfb4dee8b81', NULL, 26, 26, '"Claudius Lysias to the most excellent governor Felix: Greetings.'),
  ('e49af6d9-2f05-53be-abad-ea59e87b6705', 'e04eb58b-520a-50bc-a452-9dfb4dee8b81', NULL, 27, 27, '"This man was seized by the Jews, and was about to be killed by them, when I came with the soldiers and rescued him, having learned that he was a Roman.'),
  ('1bc82cc7-bf95-517d-a8c8-afd409ea2cb3', 'e04eb58b-520a-50bc-a452-9dfb4dee8b81', NULL, 28, 28, 'Desiring to know the cause why they accused him, I brought him down to their council.'),
  ('c88abda6-6436-5537-aa64-28d6e3cb4c7a', 'e04eb58b-520a-50bc-a452-9dfb4dee8b81', NULL, 29, 29, 'I found him to be accused about questions of their law, but not to be charged with anything worthy of death or of imprisonment.'),
  ('445655be-23e4-5ab1-afb4-68b1fc0c433f', 'e04eb58b-520a-50bc-a452-9dfb4dee8b81', NULL, 30, 30, 'When I was told that the Jews lay in wait for the man, I sent him to you immediately, charging his accusers also to bring their accusations against him before you. Farewell."'),
  ('40e48a48-fff3-59d9-ae86-3f93d4d43e36', 'e04eb58b-520a-50bc-a452-9dfb4dee8b81', NULL, 31, 31, 'So the soldiers, carrying out their orders, took Paul and brought him by night to Antipatris.'),
  ('f55f3b96-be4d-5e1e-af31-3c8d919c8255', 'e04eb58b-520a-50bc-a452-9dfb4dee8b81', NULL, 32, 32, 'But on the next day they left the horsemen to go with him, and returned to the barracks.'),
  ('11e49ef2-1123-5255-aa46-c98f1c8e0cff', 'e04eb58b-520a-50bc-a452-9dfb4dee8b81', NULL, 33, 33, 'When they came to Caesarea and delivered the letter to the governor, they also presented Paul to him.'),
  ('dcbe7b9a-02ac-574e-a03d-9ecc3416400e', 'e04eb58b-520a-50bc-a452-9dfb4dee8b81', NULL, 34, 34, 'When the governor had read it, he asked what province he was from. When he understood that he was from Cilicia, he said,'),
  ('5c61cdc3-1c8b-5587-a6e0-b198e692648f', 'e04eb58b-520a-50bc-a452-9dfb4dee8b81', NULL, 35, 35, '"I will hear you fully when your accusers also arrive." He commanded that he be kept in Herod''s palace.'),
  ('28d2adca-5a2f-56fb-a639-28147784d0c3', '193ccc19-5171-5308-ac23-31733989cab7', NULL, 1, 1, 'After five days, the high priest, Ananias, came down with certain elders and an orator, one Tertullus. They informed the governor against Paul.'),
  ('a0d26296-a0b9-5d6d-afac-c5842a3d7ef5', '193ccc19-5171-5308-ac23-31733989cab7', NULL, 2, 2, 'When he was called, Tertullus began to accuse him, saying, "Seeing that by you we enjoy much peace, and that excellent measures are coming to this nation,'),
  ('d8bf9d3e-f117-591f-a004-d91cfe2e902e', '193ccc19-5171-5308-ac23-31733989cab7', NULL, 3, 3, 'we accept it in all ways and in all places, most excellent Felix, with all thankfulness.'),
  ('0bd3aeb9-e1ad-59d9-a914-da2f3b3bfbd8', '193ccc19-5171-5308-ac23-31733989cab7', NULL, 4, 4, 'But, that I don''t delay you, I entreat you to bear with us and hear a few words.'),
  ('8ee14346-0825-5b58-a7a8-684c4c055123', '193ccc19-5171-5308-ac23-31733989cab7', NULL, 5, 5, 'For we have found this man to be a plague, an instigator of insurrections among all the Jews throughout the world, and a ringleader of the sect of the Nazarenes.'),
  ('ad6e2925-6b35-5c3d-a6e0-4008d448634f', '193ccc19-5171-5308-ac23-31733989cab7', NULL, 6, 6, 'He even tried to profane the temple, and we arrested him.'),
  ('3e7d60a0-3889-589d-aaf7-8978fe248619', '193ccc19-5171-5308-ac23-31733989cab7', NULL, 7, 7, ''),
  ('85ea9032-f263-5501-a62b-bc35fe666db5', '193ccc19-5171-5308-ac23-31733989cab7', NULL, 8, 8, 'By examining him yourself you may ascertain all these things of which we accuse him."'),
  ('86af5b08-1819-5c86-a491-d9ea6b33fb29', '193ccc19-5171-5308-ac23-31733989cab7', NULL, 9, 9, 'The Jews also joined in the attack, affirming that these things were so.'),
  ('291aca2f-924a-58fb-a369-64f2f2c310ca', '193ccc19-5171-5308-ac23-31733989cab7', NULL, 10, 10, 'When the governor had beckoned to him to speak, Paul answered, "Because I know that you have been a judge of this nation for many years, I cheerfully make my defense,'),
  ('e8684fb8-1c34-5e5c-abb8-8c309b6d21a9', '193ccc19-5171-5308-ac23-31733989cab7', NULL, 11, 11, 'seeing that you can recognize that it is not more than twelve days since I went up to worship at Jerusalem.'),
  ('fc6348e6-2854-532a-a680-78af0fcec99f', '193ccc19-5171-5308-ac23-31733989cab7', NULL, 12, 12, 'In the temple they didn''t find me disputing with anyone or stirring up a crowd, either in the synagogues, or in the city.'),
  ('7dd60134-a8fb-5f31-a93f-5a41bbce0249', '193ccc19-5171-5308-ac23-31733989cab7', NULL, 13, 13, 'Nor can they prove to you the things of which they now accuse me.'),
  ('69faaeb7-2b16-5783-af38-f085b9b20e33', '193ccc19-5171-5308-ac23-31733989cab7', NULL, 14, 14, 'But this I confess to you, that after the Way, which they call a sect, so I serve the God of our fathers, believing all things which are according to the law, and which are written in the prophets;'),
  ('a87c0cc7-e963-5f3b-a349-808887dedfae', '193ccc19-5171-5308-ac23-31733989cab7', NULL, 15, 15, 'having hope toward God, which these also themselves look for, that there will be a resurrection of the dead, both of the just and unjust.'),
  ('cdb21b0a-3d19-5359-a7d1-5cd8bf6227ce', '193ccc19-5171-5308-ac23-31733989cab7', NULL, 16, 16, 'Herein I also practice always having a conscience void of offense toward God and men.'),
  ('4cef9df5-8496-5438-ad72-7847309692ba', '193ccc19-5171-5308-ac23-31733989cab7', NULL, 17, 17, 'Now after some years, I came to bring gifts for the needy to my nation, and offerings;'),
  ('bfffc1cf-5750-5c94-ad3a-adb55935c580', '193ccc19-5171-5308-ac23-31733989cab7', NULL, 18, 18, 'amid which certain Jews from Asia found me purified in the temple, not with a mob, nor with turmoil.'),
  ('5efbf649-7bc7-5d36-a84b-e2b600a664b0', '193ccc19-5171-5308-ac23-31733989cab7', NULL, 19, 19, 'They ought to have been here before you, and to make accusation, if they had anything against me.'),
  ('80e7ca0d-c85e-5bd0-aa95-ba5c8011e986', '193ccc19-5171-5308-ac23-31733989cab7', NULL, 20, 20, 'Or else let these men themselves say what injustice they found in me when I stood before the council,'),
  ('4fe1ba82-28a5-5b42-aec4-5fb6330b1140', '193ccc19-5171-5308-ac23-31733989cab7', NULL, 21, 21, 'unless it is for this one thing that I cried standing among them, ''Concerning the resurrection of the dead I am being judged before you today!''"'),
  ('fb7a474c-f851-50bf-aa08-3a14032466e7', '193ccc19-5171-5308-ac23-31733989cab7', NULL, 22, 22, 'But Felix, having more exact knowledge concerning the Way, deferred them, saying, "When Lysias, the commanding officer, comes down, I will decide your case."'),
  ('107f9241-6c45-56c6-a2fa-2c236bd6f22d', '193ccc19-5171-5308-ac23-31733989cab7', NULL, 23, 23, 'He ordered the centurion that Paul should be kept in custody, and should have some privileges, and not to forbid any of his friends to serve him or to visit him.'),
  ('2686258e-6882-58b5-a87f-908be3fcfd6e', '193ccc19-5171-5308-ac23-31733989cab7', NULL, 24, 24, 'But after some days, Felix came with Drusilla, his wife, who was a Jewess, and sent for Paul, and heard him concerning the faith in Christ Jesus.'),
  ('069d299f-fb21-5c3b-a1fb-1c0c558a6f11', '193ccc19-5171-5308-ac23-31733989cab7', NULL, 25, 25, 'As he reasoned about righteousness, self-control, and the judgment to come, Felix was terrified, and answered, "Go your way for this time, and when it is convenient for me, I will summon you."'),
  ('beb3d77d-11da-5885-a624-97dcbe1fce87', '193ccc19-5171-5308-ac23-31733989cab7', NULL, 26, 26, 'Meanwhile, he also hoped that money would be given to him by Paul, that he might release him. Therefore also he sent for him more often, and talked with him.'),
  ('38602310-1212-506a-a2db-657536ba5046', '193ccc19-5171-5308-ac23-31733989cab7', NULL, 27, 27, 'But when two years were fulfilled, Felix was succeeded by Porcius Festus, and desiring to gain favor with the Jews, Felix left Paul in bonds.'),
  ('b09c8272-31ae-5f1d-a62d-bf803c33519d', 'cba8ad8e-792b-5de5-ad4c-036bf9af3144', NULL, 1, 1, 'Festus therefore, having come into the province, after three days went up to Jerusalem from Caesarea.'),
  ('1fb90673-1b74-515a-a0a5-423544ac129c', 'cba8ad8e-792b-5de5-ad4c-036bf9af3144', NULL, 2, 2, 'Then the high priest and the principal men of the Jews informed him against Paul, and they begged him,'),
  ('537092d3-3b9e-55eb-a962-aadac07225a3', 'cba8ad8e-792b-5de5-ad4c-036bf9af3144', NULL, 3, 3, 'asking a favor against him, that he would summon him to Jerusalem; plotting to kill him on the way.'),
  ('eaaac29a-8033-5f92-aacd-33d20358914b', 'cba8ad8e-792b-5de5-ad4c-036bf9af3144', NULL, 4, 4, 'However Festus answered that Paul should be kept in custody at Caesarea, and that he himself was about to depart shortly.'),
  ('c394f6dc-3425-567c-acfc-59b702f83327', 'cba8ad8e-792b-5de5-ad4c-036bf9af3144', NULL, 5, 5, '"Let them therefore," said he, "that are in power among you go down with me, and if there is anything wrong in the man, let them accuse him."'),
  ('0e10068b-0cc9-5685-a764-a2479effd51e', 'cba8ad8e-792b-5de5-ad4c-036bf9af3144', NULL, 6, 6, 'When he had stayed among them more than ten days, he went down to Caesarea, and on the next day he sat on the judgment seat, and commanded Paul to be brought.'),
  ('d513490f-998c-5c3f-a729-70f865692b6a', 'cba8ad8e-792b-5de5-ad4c-036bf9af3144', NULL, 7, 7, 'When he had come, the Jews who had come down from Jerusalem stood around him, bringing against him many and grievous charges which they could not prove,'),
  ('623af474-7eb3-5a1d-a11b-184e5950f971', 'cba8ad8e-792b-5de5-ad4c-036bf9af3144', NULL, 8, 8, 'while he said in his defense, "Neither against the law of the Jews, nor against the temple, nor against Caesar, have I sinned at all."'),
  ('4f871038-0c86-55d1-aa30-be33af02b174', 'cba8ad8e-792b-5de5-ad4c-036bf9af3144', NULL, 9, 9, 'But Festus, desiring to gain favor with the Jews, answered Paul and said, "Are you willing to go up to Jerusalem, and be judged by me there concerning these things?"'),
  ('75a4494c-a3c1-586e-a981-6f0e95009861', 'cba8ad8e-792b-5de5-ad4c-036bf9af3144', NULL, 10, 10, 'But Paul said, "I am standing before Caesar''s judgment seat, where I ought to be tried. I have done no wrong to the Jews, as you also know very well.'),
  ('395466e0-73a1-55f1-a7c5-d684c0c73ab6', 'cba8ad8e-792b-5de5-ad4c-036bf9af3144', NULL, 11, 11, 'For if I have done wrong, and have committed anything worthy of death, I don''t refuse to die; but if none of those things is true that they accuse me of, no one can give me up to them. I appeal to Caesar!"'),
  ('2bdcddfb-4cad-5a33-a194-de699db987a1', 'cba8ad8e-792b-5de5-ad4c-036bf9af3144', NULL, 12, 12, 'Then Festus, when he had conferred with the council, answered, "You have appealed to Caesar. To Caesar you shall go."'),
  ('7bf7baf0-6767-5e6f-ad52-302f60f62a99', 'cba8ad8e-792b-5de5-ad4c-036bf9af3144', NULL, 13, 13, 'Now when some days had passed, King Agrippa and Bernice arrived at Caesarea, and greeted Festus.'),
  ('6a4bc6f0-d9e2-5a4a-a29e-810c51414c2d', 'cba8ad8e-792b-5de5-ad4c-036bf9af3144', NULL, 14, 14, 'As he stayed there many days, Festus laid Paul''s case before the king, saying, "There is a certain man left a prisoner by Felix;'),
  ('16410146-a7e3-5cf2-a2f9-9bd6c6e5a0fb', 'cba8ad8e-792b-5de5-ad4c-036bf9af3144', NULL, 15, 15, 'about whom, when I was at Jerusalem, the chief priests and the elders of the Jews informed me, asking for a sentence against him.'),
  ('f1565fa7-c4a0-5341-a7f8-cd6b8001fc05', 'cba8ad8e-792b-5de5-ad4c-036bf9af3144', NULL, 16, 16, 'To whom I answered that it is not the custom of the Romans to give up any man to destruction, before the accused has met the accusers face to face, and has had opportunity to make his defense concerning the matter laid against him.'),
  ('a9a59a49-0cee-57d1-a7c2-c827b94e34c3', 'cba8ad8e-792b-5de5-ad4c-036bf9af3144', NULL, 17, 17, 'When therefore they had come together here, I didn''t delay, but on the next day sat on the judgment seat, and commanded the man to be brought.'),
  ('9b55d41e-e1e0-580b-a369-8afc6e5f08e0', 'cba8ad8e-792b-5de5-ad4c-036bf9af3144', NULL, 18, 18, 'Concerning whom, when the accusers stood up, they brought no charge of such things as I supposed;'),
  ('96066034-e8c8-511a-a5a0-6b4f5160f626', 'cba8ad8e-792b-5de5-ad4c-036bf9af3144', NULL, 19, 19, 'but had certain questions against him about their own religion, and about one Jesus, who was dead, whom Paul affirmed to be alive.'),
  ('eb108b09-e6bf-5eb2-a77b-68f7cbd4fc96', 'cba8ad8e-792b-5de5-ad4c-036bf9af3144', NULL, 20, 20, 'Being perplexed how to inquire concerning these things, I asked whether he was willing to go to Jerusalem and there be judged concerning these matters.'),
  ('b5d8a622-01c8-52d5-a5d4-e99a1526ccf5', 'cba8ad8e-792b-5de5-ad4c-036bf9af3144', NULL, 21, 21, 'But when Paul had appealed to be kept for the decision of the emperor, I commanded him to be kept until I could send him to Caesar."'),
  ('39233f6f-47b2-5fc7-a982-74a545d63f2a', 'cba8ad8e-792b-5de5-ad4c-036bf9af3144', NULL, 22, 22, 'Agrippa said to Festus, "I also would like to hear the man myself." "Tomorrow," he said, "you shall hear him."'),
  ('decb178a-274f-5fbf-ae77-a9552684dd0b', 'cba8ad8e-792b-5de5-ad4c-036bf9af3144', NULL, 23, 23, 'So on the next day, when Agrippa and Bernice had come with great pomp, and they had entered into the place of hearing with the commanding officers and principal men of the city, at the command of Festus, Paul was brought in.'),
  ('785155b3-7d23-5688-a19e-2aa38dac04df', 'cba8ad8e-792b-5de5-ad4c-036bf9af3144', NULL, 24, 24, 'Festus said, "King Agrippa, and all men who are here present with us, you see this man, about whom all the multitude of the Jews petitioned me, both at Jerusalem and here, crying that he ought not to live any longer.'),
  ('2a0ef759-8694-5d0a-ae0c-d8da7f31f506', 'cba8ad8e-792b-5de5-ad4c-036bf9af3144', NULL, 25, 25, 'But when I found that he had committed nothing worthy of death, and as he himself appealed to the emperor I determined to send him.'),
  ('19c84fde-433b-52ba-a538-d52fddd1c3d3', 'cba8ad8e-792b-5de5-ad4c-036bf9af3144', NULL, 26, 26, 'Of whom I have no certain thing to write to my lord. Therefore I have brought him forth before you, and especially before you, King Agrippa, that, after examination, I may have something to write.'),
  ('c12ce656-5415-57c7-a5ac-0b4ffd654f81', 'cba8ad8e-792b-5de5-ad4c-036bf9af3144', NULL, 27, 27, 'For it seems to me unreasonable, in sending a prisoner, not to also specify the charges against him."'),
  ('4d4f1abf-5755-598a-abca-6ed66a1edacf', '1638e9eb-d072-5b1e-a17f-b31999f0d527', NULL, 1, 1, 'Agrippa said to Paul, "You may speak for yourself." Then Paul stretched out his hand, and made his defense.'),
  ('6f7e1e5f-60ae-5516-a701-972683993429', '1638e9eb-d072-5b1e-a17f-b31999f0d527', NULL, 2, 2, '"I think myself happy, King Agrippa, that I am to make my defense before you this day concerning all the things that I am accused by the Jews,'),
  ('158d066d-a5b9-56aa-a586-e737c0605419', '1638e9eb-d072-5b1e-a17f-b31999f0d527', NULL, 3, 3, 'especially because you are expert in all customs and questions which are among the Jews. Therefore I beg you to hear me patiently.'),
  ('63913146-7aa3-5dcb-a59b-741db51de04c', '1638e9eb-d072-5b1e-a17f-b31999f0d527', NULL, 4, 4, '"Indeed, all the Jews know my way of life from my youth up, which was from the beginning among my own nation and at Jerusalem;'),
  ('730992a3-9e74-599c-a782-764c3b176d1d', '1638e9eb-d072-5b1e-a17f-b31999f0d527', NULL, 5, 5, 'having known me from the first, if they are willing to testify, that after the strictest sect of our religion I lived a Pharisee.'),
  ('7bc3ce39-3119-587c-a8f0-ad786e1c7384', '1638e9eb-d072-5b1e-a17f-b31999f0d527', NULL, 6, 6, 'Now I stand here to be judged for the hope of the promise made by God to our fathers,'),
  ('9a9994ef-7422-59b8-ad85-50e6031ed434', '1638e9eb-d072-5b1e-a17f-b31999f0d527', NULL, 7, 7, 'which our twelve tribes, earnestly serving night and day, hope to attain. Concerning this hope I am accused by the Jews, King Agrippa!'),
  ('4e857bdd-9f48-571d-a158-469f244e1051', '1638e9eb-d072-5b1e-a17f-b31999f0d527', NULL, 8, 8, 'Why is it judged incredible with you, if God does raise the dead?'),
  ('3cd31905-d687-53a1-a455-4d1dfbab6eeb', '1638e9eb-d072-5b1e-a17f-b31999f0d527', NULL, 9, 9, '"I myself most certainly thought that I ought to do many things contrary to the name of Jesus of Nazareth.'),
  ('a2be5d4e-573b-5ffd-a77b-55e6f0dfb234', '1638e9eb-d072-5b1e-a17f-b31999f0d527', NULL, 10, 10, 'This I also did in Jerusalem. I both shut up many of the saints in prisons, having received authority from the chief priests, and when they were put to death I gave my vote against them.'),
  ('a4f56e6b-99ac-5169-aae6-fd8876dd5d69', '1638e9eb-d072-5b1e-a17f-b31999f0d527', NULL, 11, 11, 'Punishing them often in all the synagogues, I tried to make them blaspheme. Being exceedingly enraged against them, I persecuted them even to foreign cities.'),
  ('4882deeb-cf60-5b74-a458-f9c1fc50a006', '1638e9eb-d072-5b1e-a17f-b31999f0d527', NULL, 12, 12, '"Whereupon as I traveled to Damascus with the authority and commission from the chief priests,'),
  ('27a4c6ac-6a8d-55d8-a5f7-c9c2eb3be7e6', '1638e9eb-d072-5b1e-a17f-b31999f0d527', NULL, 13, 13, 'at noon, O king, I saw on the way a light from the sky, brighter than the sun, shining around me and those who traveled with me.'),
  ('e5006c0f-3cc2-5de7-a4e4-a9ec3543aba6', '1638e9eb-d072-5b1e-a17f-b31999f0d527', NULL, 14, 14, 'When we had all fallen to the earth, I heard a voice saying to me in the Hebrew language, ''Saul, Saul, why are you persecuting me? It is hard for you to kick against the goads.'''),
  ('2c277cf4-73be-55e8-aaee-f974dfcae593', '1638e9eb-d072-5b1e-a17f-b31999f0d527', NULL, 15, 15, '"I said, ''Who are you, Lord?'' "He said, ''I am Jesus, whom you are persecuting.'),
  ('87b7496a-8275-56ad-a527-73295d16004b', '1638e9eb-d072-5b1e-a17f-b31999f0d527', NULL, 16, 16, 'But arise, and stand on your feet, for I have appeared to you for this purpose: to appoint you a servant and a witness both of the things which you have seen, and of the things which I will reveal to you;'),
  ('421d11e3-70f6-50da-ad9c-ab6274203e0b', '1638e9eb-d072-5b1e-a17f-b31999f0d527', NULL, 17, 17, 'delivering you from the people, and from the Gentiles, to whom I send you,'),
  ('0f6efed2-1571-5968-ad44-6dda6434262f', '1638e9eb-d072-5b1e-a17f-b31999f0d527', NULL, 18, 18, 'to open their eyes, that they may turn from darkness to light and from the power of Satan to God, that they may receive remission of sins and an inheritance among those who are sanctified by faith in me.'''),
  ('b7e50d38-3145-56f2-a8ce-0033bc625e67', '1638e9eb-d072-5b1e-a17f-b31999f0d527', NULL, 19, 19, '"Therefore, King Agrippa, I was not disobedient to the heavenly vision,'),
  ('9bebbb01-e836-527e-ae31-d8cf05823397', '1638e9eb-d072-5b1e-a17f-b31999f0d527', NULL, 20, 20, 'but declared first to them of Damascus, at Jerusalem, and throughout all the country of Judea, and also to the Gentiles, that they should repent and turn to God, doing works worthy of repentance.'),
  ('896c7015-5aa2-5299-abf7-a9222de215c1', '1638e9eb-d072-5b1e-a17f-b31999f0d527', NULL, 21, 21, 'For this reason the Jews seized me in the temple, and tried to kill me.'),
  ('f32f6202-2308-5451-ab55-499af3ec683f', '1638e9eb-d072-5b1e-a17f-b31999f0d527', NULL, 22, 22, 'Having therefore obtained the help that is from God, I stand to this day testifying both to small and great, saying nothing but what the prophets and Moses said would happen,'),
  ('ee2c69bc-dc48-5262-a5f3-9fb670badda2', '1638e9eb-d072-5b1e-a17f-b31999f0d527', NULL, 23, 23, 'how the Christ must suffer, and how, by the resurrection of the dead, he would be first to proclaim light both to these people and to the Gentiles."'),
  ('0ec9aeec-61f5-558e-a4b5-a666ea1d10ea', '1638e9eb-d072-5b1e-a17f-b31999f0d527', NULL, 24, 24, 'As he thus made his defense, Festus said with a loud voice, "Paul, you are crazy! Your great learning is driving you insane!"'),
  ('7e12c919-7b7f-5f15-a44c-183a752e7d1f', '1638e9eb-d072-5b1e-a17f-b31999f0d527', NULL, 25, 25, 'But he said, "I am not crazy, most excellent Festus, but boldly declare words of truth and reasonableness.'),
  ('436b5daa-5175-592d-af75-9b5928a529ae', '1638e9eb-d072-5b1e-a17f-b31999f0d527', NULL, 26, 26, 'For the king knows of these things, to whom also I speak freely. For I am persuaded that none of these things is hidden from him, for this has not been done in a corner.'),
  ('8ede9d2b-74a5-5fe5-a7cf-4a2a8bd687c8', '1638e9eb-d072-5b1e-a17f-b31999f0d527', NULL, 27, 27, 'King Agrippa, do you believe the prophets? I know that you believe."'),
  ('9f307ba0-0374-57c4-a1a9-633eb5c95869', '1638e9eb-d072-5b1e-a17f-b31999f0d527', NULL, 28, 28, 'Agrippa said to Paul, "With a little persuasion are you trying to make me a Christian?"'),
  ('75e1b981-b961-51c0-a3c9-5758d0af125c', '1638e9eb-d072-5b1e-a17f-b31999f0d527', NULL, 29, 29, 'Paul said, "I pray to God, that whether with little or with much, not only you, but also all that hear me this day, might become such as I am, except for these bonds."'),
  ('ed0c278d-6e08-5d23-ab1a-12ab1da72332', '1638e9eb-d072-5b1e-a17f-b31999f0d527', NULL, 30, 30, 'The king rose up with the governor, and Bernice, and those who sat with them.'),
  ('fc08c01d-c782-5637-aa62-cf99d6bd53a0', '1638e9eb-d072-5b1e-a17f-b31999f0d527', NULL, 31, 31, 'When they had withdrawn, they spoke one to another, saying, "This man does nothing worthy of death or of bonds."'),
  ('a1bdd29d-e8f7-5e50-a396-ddf11f6f378d', '1638e9eb-d072-5b1e-a17f-b31999f0d527', NULL, 32, 32, 'Agrippa said to Festus, "This man might have been set free if he had not appealed to Caesar."'),
  ('7d647d98-f456-5514-adc2-4e029946ba25', 'b6c13b6c-c277-54f8-a6c0-3f430cfe2b43', NULL, 1, 1, 'When it was determined that we should sail for Italy, they delivered Paul and certain other prisoners to a centurion named Julius, of the Augustan band.'),
  ('fd6ac0f0-2fd9-5da4-af81-8eee361ffba3', 'b6c13b6c-c277-54f8-a6c0-3f430cfe2b43', NULL, 2, 2, 'Embarking in a ship of Adramyttium, which was about to sail to places on the coast of Asia, we put to sea; Aristarchus, a Macedonian of Thessalonica, being with us.'),
  ('c62e7a97-a528-5c15-ade5-bb72477adcbb', 'b6c13b6c-c277-54f8-a6c0-3f430cfe2b43', NULL, 3, 3, 'The next day, we touched at Sidon. Julius treated Paul kindly, and gave him permission to go to his friends and refresh himself.'),
  ('d9ee5129-54ec-5d27-a9db-20eca29b89bc', 'b6c13b6c-c277-54f8-a6c0-3f430cfe2b43', NULL, 4, 4, 'Putting to sea from there, we sailed under the lee of Cyprus, because the winds were contrary.'),
  ('8f7ed3ff-c7bd-5a59-af11-212710e6b7dd', 'b6c13b6c-c277-54f8-a6c0-3f430cfe2b43', NULL, 5, 5, 'When we had sailed across the sea which is off Cilicia and Pamphylia, we came to Myra, a city of Lycia.')
